// Cyrus R1 asset slice: which custom assets a BUILD may generate (pure, client-safe).
// The build request names what the user wants (an explicit `assets` list from the composer, words in the prompt that
// the adapter's route rules recognise, or textures the mod already has); the plan-tier gate
// (lib/cyrus/engine-core/asset-gate.ts) decides what the plan may create or edit; the version registry decides what
// the target version can show; ASSET_PIPELINE_READY says which pipelines exist. Anything refused is a DOWNGRADE: the
// plugin is still built, without that asset, with a plain reason for the user. Never trust the client for any of it:
// the server calls planBuildAssets on every request (lib/cyrus/assets/request.ts).
import { getAdapter } from "../adapters";
import { canAsset, normalizePlan, PLAN_LABEL, type AssetPlan } from "../engine-core/asset-gate";
import { hasCapability, resourcePackFormat } from "../versions/registry";

import { BUILD_ASSET_KINDS, type BuildAssetKind } from "./kinds";
export { BUILD_ASSET_KINDS, isBuildAssetKind, type BuildAssetKind } from "./kinds";

/**
 * Which generation pipelines the build path can run today. THE SOUND SLICE PLUGS IN HERE: set `sound: true` once the
 * build service writes sound specs and lib/cyrus/assets/sync.ts renders them (see docs "Cyrus asset slice (R1)").
 */
export const ASSET_PIPELINE_READY: Readonly<Record<BuildAssetKind, boolean>> = { texture: true, sound: false };

export type AllowedAssets = Record<BuildAssetKind, boolean>;
export type AssetDecisionCode = "allowed" | "asset_locked" | "plan_unknown" | "version" | "not_ready";
export type BuildAssetDecision = { kind: BuildAssetKind; code: AssetDecisionCode; reason?: string; needs?: AssetPlan };
export type BuildAssetPlan = {
  /** What the request asked for (sorted, unique). Empty = no asset path at all (the pre-R1 behaviour). */
  requested: BuildAssetKind[];
  allowed: AllowedAssets;
  decisions: BuildAssetDecision[];
  /** Customer-visible, one per refused kind: why, and what Cyrus builds instead. */
  notices: string[];
  plan: AssetPlan | null;
};

const FALLBACK: Record<BuildAssetKind, string> = { texture: "vanilla item looks", sound: "vanilla sounds" };
const WORD: Record<BuildAssetKind, string> = { texture: "Custom textures", sound: "Custom sounds" };

/** Asset kinds the adapter's route rules recognise in the request text (deterministic keyword match, no AI). */
export function detectAssetKinds(text: string, game = "minecraft"): BuildAssetKind[] {
  const adapter = getAdapter(game);
  if (!adapter || !text) return [];
  const out = new Set<BuildAssetKind>();
  for (const rule of adapter.routeRules) {
    if (!rule.assetKinds?.length) continue;
    if (!rule.keywords.some((k) => new RegExp(k, "i").test(text))) continue;
    for (const k of rule.assetKinds) {
      if (k === "sound") out.add("sound");
      else if (k === "texture" || k === "model") out.add("texture"); // item models are drawn with the texture pipeline
    }
  }
  return BUILD_ASSET_KINDS.filter((k) => out.has(k));
}

/** The request's own list: `assets: ["texture"]` or `assets: { texture: true }` (anything else is ignored). */
export function explicitAssetKinds(raw: unknown): BuildAssetKind[] {
  if (Array.isArray(raw)) return BUILD_ASSET_KINDS.filter((k) => raw.includes(k));
  if (raw && typeof raw === "object") return BUILD_ASSET_KINDS.filter((k) => (raw as Record<string, unknown>)[k] === true);
  return [];
}

export function requestedAssetKinds(input: { explicit?: unknown; text?: string; existing?: BuildAssetKind[]; game?: string }): BuildAssetKind[] {
  const s = new Set<BuildAssetKind>([...explicitAssetKinds(input.explicit), ...detectAssetKinds(input.text ?? "", input.game), ...(input.existing ?? [])]);
  return BUILD_ASSET_KINDS.filter((k) => s.has(k));
}

/** Can the target version show this kind at all? Textures need 1.21.4+ item model definitions and a known pack format. */
function versionReason(kind: BuildAssetKind, mcVersion: string): string | null {
  const pf = resourcePackFormat(mcVersion, { needsItemModels: kind === "texture" });
  if (kind === "texture" && !hasCapability(mcVersion, "itemModelDefinitions")) {
    return `${WORD.texture} need Minecraft 1.21.4 or newer (item model definitions) and this mod targets ${mcVersion}, so Cyrus builds it with ${FALLBACK.texture}. Pick 1.21.4 or newer to get custom textures.`;
  }
  if (!pf.ok) return `${WORD[kind]} aren't available for Minecraft ${mcVersion} yet (${pf.error}), so Cyrus builds it with ${FALLBACK[kind]}.`;
  return null;
}

/**
 * Decide, per requested kind: plan gate first (create for a new mod, edit for a change), then the version, then
 * whether the pipeline exists. `plan` is whatever the token economy says (`all`, `yakko`, `saka`, ...); unknown or
 * missing -> nothing may be created (fail closed).
 */
export function planBuildAssets(input: { plan: unknown; requested: BuildAssetKind[]; mcVersion: string; change?: boolean; existing?: BuildAssetKind[] }): BuildAssetPlan {
  const plan = normalizePlan(input.plan);
  const allowed: AllowedAssets = { texture: false, sound: false };
  const decisions: BuildAssetDecision[] = [];
  const notices: string[] = [];
  for (const kind of BUILD_ASSET_KINDS.filter((k) => input.requested.includes(k))) {
    const g = canAsset(plan, kind, input.change ? "edit" : "create");
    if (!g.ok) {
      const code = g.code === "plan_unknown" ? "plan_unknown" : "asset_locked";
      // Keeping what the mod already has is never gated: say so instead of implying the textures disappear.
      const reason = input.existing?.includes(kind)
        ? `This mod's existing ${WORD[kind].toLowerCase()} are kept exactly as they are. ${g.reason}`
        : `${g.reason} Cyrus will build the plugin with ${FALLBACK[kind]} instead.`;
      decisions.push({ kind, code, reason, ...(g.needs ? { needs: g.needs } : {}) });
      notices.push(reason);
      continue;
    }
    const vr = versionReason(kind, input.mcVersion);
    if (vr) { decisions.push({ kind, code: "version", reason: vr }); notices.push(vr); continue; }
    if (!ASSET_PIPELINE_READY[kind]) {
      const reason = `${WORD[kind]} are not built into Cyrus yet, so this mod uses ${FALLBACK[kind]} for now.`;
      decisions.push({ kind, code: "not_ready", reason });
      notices.push(reason);
      continue;
    }
    allowed[kind] = true;
    decisions.push({ kind, code: "allowed" });
  }
  return { requested: [...input.requested].sort() as BuildAssetKind[], allowed, decisions, notices, plan };
}

export const anyAllowed = (a: AllowedAssets) => BUILD_ASSET_KINDS.some((k) => a[k]);
export const planLabel = (p: AssetPlan | null) => (p ? PLAN_LABEL[p] : "unknown");
// Asset kinds a Cyrus build can generate (R1: texture now, sound next). Tiny and dependency-free so client code
// (lib/cyrus/meta.ts) can use it without pulling in the adapters or the version registry.
export const BUILD_ASSET_KINDS = ["texture", "sound"] as const;
export type BuildAssetKind = (typeof BUILD_ASSET_KINDS)[number];
export const isBuildAssetKind = (v: unknown): v is BuildAssetKind => typeof v === "string" && (BUILD_ASSET_KINDS as readonly string[]).includes(v);

// Cyrus R1: what the PORTAL does with the texture specs a succeeded build returns (called from the ModBuild sync path,
// lib/modbuilder/store.ts, so it runs in the API routes and the worker sweep alike). In order:
//   1. re-validate, render and quality-check every spec (lib/cyrus/assets/textures.ts); failures are dropped, never shipped
//   2. build the deterministic resource pack through the version registry (lib/cyrus/textures/pack.ts, NO allowPreview)
//   3. publish it to the pack store (lib/cyrus/packhost; off in production until the owner configures storage)
//   4. compute the Pack Loader entry with the pure applyPackChange
//   5. record one CyrusRevision (kind generated, manifest with jar + spec + pack hashes, engine record) and one
//      CyrusProjectAsset per texture (provenance carries the spec and its quality report)
// Idempotent: re-running for the same build finds its revision (by modBuildId) and the content-addressed asset rows
// and the immutable pack object, so nothing is duplicated. Dependencies are injected (./sync-deps.ts has the real ones).
import type { MbAssets } from "../../modbuilder/types";
import type { SvcAssetResult } from "../../modbuilder/client";
import type { AddRevisionInput, RecordAssetInput } from "../engine-core/store";
import type { ManifestEntry } from "../engine-core/revisions";
import type { StoreSelection } from "../packhost/config";
import { applyPackChange } from "../packhost/loader-config";
import { publishPack } from "../packhost/publish";
import { buildPack } from "../textures/pack";
import { QUALITY_VERSION } from "../textures/quality";
import { checkReturnedTexture, sha256Hex } from "./textures";

export const PACK_ROLE = "main";
export const TEXTURE_SPEC_MIME = "application/vnd.nxeon.texture-spec+json";

export type ProjectRow = { id: string; namespace: string; userId: string };
export type AssetSyncDeps = {
  selectStore: () => StoreSelection;
  projectForRootBuild: (rootBuildId: string) => Promise<ProjectRow | null>;
  createProject: (i: { userId: string; game: string; rootBuildId: string }) => Promise<ProjectRow>;
  findRevisionForBuild: (projectId: string, modBuildId: string) => Promise<{ id: string } | null>;
  headRevisionId: (projectId: string) => Promise<string | null>;
  addRevision: (projectId: string, input: AddRevisionInput) => Promise<{ id: string }>;
  recordAsset: (projectId: string, a: RecordAssetInput) => Promise<unknown>;
};

export type SyncBuild = { id: string; userId: string; rootBuildId: string | null; mcVersion: string; pluginName: string | null; jarName: string | null; jarSha256: string | null };

const clip = (s: string, n: number) => (s.length > n ? s.slice(0, n - 1) + "…" : s);

export async function syncBuildAssets(build: SyncBuild, ar: SvcAssetResult | null | undefined, deps: AssetSyncDeps): Promise<MbAssets | null> {
  if (!ar || (!ar.textures?.length && !ar.downgraded?.length)) return null;
  const root = build.rootBuildId ?? build.id;
  let project = await deps.projectForRootBuild(root);
  if (!project) {
    // A kept-texture change on a chain made before its project existed; create it (same reserved namespace rules).
    try { project = await deps.createProject({ userId: build.userId, game: "minecraft", rootBuildId: root }); }
    catch { project = await deps.projectForRootBuild(root); }
  }
  if (!project) throw new Error(`no Cyrus project for build chain ${root}`);
  const base: MbAssets = { status: "none", namespace: project.namespace, projectId: project.id, revisionId: null, textures: [], dropped: [...(ar.downgraded ?? [])].slice(0, 24), pack: null, loader: null, notices: [...(ar.warnings ?? [])].slice(0, 20) };
  if (ar.namespace && ar.namespace !== project.namespace) {
    return { ...base, status: "failed", notices: [...base.notices, "The custom textures were made for a different namespace than this mod's, so they were not shipped."] };
  }

  // 1. never trust the service: validate, render and quality-check again
  const ok: Extract<ReturnType<typeof checkReturnedTexture>, { ok: true }>[] = [];
  for (const t of (ar.textures ?? []).slice(0, 24)) {
    const c = checkReturnedTexture(t);
    if (!c.ok) { base.dropped.push({ name: c.name, reason: c.reason }); base.notices.push(`Custom texture "${c.name}" was left out: it did not pass Nxeon's texture checks.`); continue; }
    if (ok.some((x) => x.name === c.name)) continue;
    ok.push(c);
  }
  if (!ok.length) return base;
  const name = build.pluginName || "this mod";

  // 2. the deterministic pack, through the registry (preview versions refused: no allowPreview in this path)
  const built = buildPack({ namespace: project.namespace, description: clip(`${name}: custom textures by Cyrus`, 100), mcVersion: build.mcVersion, textures: ok.map((c) => c.spec) });
  const textures = ok.map((c) => ({ name: c.name, model: `${project!.namespace}:${c.name}`, specSha256: c.specSha256, pngSha256: c.pngSha256, quality: c.quality.verdict as "pass" | "warn" }));
  if (!built.ok) {
    return { ...base, status: "failed", textures, notices: [...base.notices, `The resource pack could not be built for Minecraft ${build.mcVersion}: ${built.error}.`] };
  }
  const pack = built.pack;
  const packSha256 = sha256Hex(pack.zip);

  // 3. host it (immutable, content addressed); 4. the Pack Loader entry
  let url: string | null = null;
  let loader: MbAssets["loader"] = null;
  const notices = [...base.notices];
  const sel = deps.selectStore();
  if (sel.ok) {
    // A storage outage must not hold the plugin back: the pack stays "unhosted" (the revision still records it).
    const pub = await publishPack(sel.store, pack.zip, { maxBytes: sel.maxBytes }).catch((e) => ({ ok: false as const, code: "store_error" as const, error: (e as Error).message }));
    if (pub.ok) {
      url = pub.url;
      const prompt = clip(`${name} uses custom item textures. Accept the pack to see them.`, 300);
      const r = applyPackChange(null, { op: "upsert", namespace: project.namespace, role: PACK_ROLE, sha1: pub.sha1, prompt, required: false }, { urlFor: () => pub.url });
      if (r.ok) loader = { id: r.id, url: pub.url, sha1: pub.sha1, prompt, required: false };
      else notices.push("The pack was published, but its delivery entry could not be prepared.");
    } else notices.push(`The resource pack could not be published (${pub.code}).`);
  } else {
    notices.push("The resource pack is built, but pack delivery to servers is not switched on yet, so players won't see the custom textures yet.");
  }

  // 5. revision + asset rows (idempotent)
  const manifest: ManifestEntry[] = [
    ...(build.jarName && build.jarSha256 ? [{ path: `plugin/${build.jarName}`, sha256: build.jarSha256, role: "artifact" as const }] : []),
    ...ok.map((c) => ({ path: `assets/textures/${c.name}.json`, sha256: c.specSha256, role: "asset" as const })),
    { path: `resourcepack/${pack.sha1}.zip`, sha256: packSha256, role: "resourcePack" as const },
  ];
  let revisionId: string | null = null;
  for (let attempt = 0; attempt < 4 && !revisionId; attempt++) {
    const found = await deps.findRevisionForBuild(project.id, build.id);
    if (found) { revisionId = found.id; break; }
    const head = await deps.headRevisionId(project.id);
    try {
      const rev = await deps.addRevision(project.id, {
        kind: "generated", manifest, modBuildId: build.id, status: "passed", expectedHeadId: head,
        engine: { ...(ar.promptVersion ? { promptVersion: ar.promptVersion } : {}), toolchain: `cyrus-textures ${QUALITY_VERSION} (service ${ar.qualityVersion}); pack format ${pack.packFormat}` },
        message: clip(`${ok.length} custom texture${ok.length > 1 ? "s" : ""}; pack ${pack.sha1.slice(0, 12)}${ar.kept ? " (kept unchanged)" : ""}`, 200),
      });
      revisionId = rev.id;
    } catch (e) {
      if ((e as { code?: string }).code === "stale_head") continue; // someone appended meanwhile: look again
      throw e;
    }
  }
  if (!revisionId) throw new Error("could not record the asset revision (the project kept moving)");
  for (const c of ok) {
    await deps.recordAsset(project.id, {
      revisionId, assetKey: c.name, kind: "texture", sha256: c.specSha256, size: Buffer.byteLength(c.canonical), origin: "generated",
      mime: TEXTURE_SPEC_MIME, path: `assets/textures/${c.name}.json`,
      provenance: { generator: "cyrus-texture-dsl", spec: c.spec, quality: c.quality, pngSha256: c.pngSha256, packSha1: pack.sha1, modBuildId: build.id, kept: ar.kept === true },
    });
  }
  return {
    ...base, status: url ? "ready" : "unhosted", revisionId, textures, notices,
    pack: { sha1: pack.sha1, sha256: packSha256, bytes: pack.bytes, format: pack.packFormat, clientVerified: pack.packClientVerified, url },
    loader,
  };
}

/** Read ModBuild.result.assets defensively (old rows have none). */
export function readBuildAssets(result: unknown): MbAssets | null {
  const a = (result as { assets?: unknown } | null)?.assets as MbAssets | undefined;
  if (!a || typeof a !== "object" || !Array.isArray(a.textures) || typeof a.namespace !== "string") return null;
  return a;
}
// Portal half of the texture specs a build returns (Cyrus R1). The build service already validated them with its JS
// copy (services/modbuilder/textures.js); the portal NEVER trusts that: it re-validates with lib/cyrus/textures,
// renders, runs the quality bar and identifies each spec by the sha256 of its canonical JSON (same bytes on both sides).
import { createHash } from "node:crypto";
import { checkSpec, type TextureSpec } from "../textures/dsl";
import { encodePng } from "../textures/png";
import { render } from "../textures/render";
import { qualityProblems, textureQuality, type QualityReport } from "../textures/quality";

/** Sorted keys at every level; the JS twin is services/modbuilder/textures.js canonicalJson. */
export function canonicalJson(v: unknown): string {
  if (Array.isArray(v)) return `[${v.map(canonicalJson).join(",")}]`;
  if (v && typeof v === "object") return `{${Object.keys(v).sort().map((k) => `${JSON.stringify(k)}:${canonicalJson((v as Record<string, unknown>)[k])}`).join(",")}}`;
  return JSON.stringify(v);
}
export const sha256Hex = (b: Buffer | string) => createHash("sha256").update(b).digest("hex");
export const specSha256 = (spec: TextureSpec) => sha256Hex(canonicalJson(spec));

export type CheckedTexture =
  | { ok: true; name: string; spec: TextureSpec; specSha256: string; canonical: string; png: Buffer; pngSha256: string; quality: QualityReport }
  | { ok: false; name: string; reason: string; quality?: QualityReport };

/** Validate + render + quality one returned texture. A failing quality verdict is refused (never shipped). */
export function checkReturnedTexture(t: { name?: unknown; spec?: unknown }): CheckedTexture {
  const name = typeof t.name === "string" ? t.name : "?";
  const c = checkSpec(t.spec);
  if (!c.ok) return { ok: false, name, reason: c.error };
  if (c.spec.name !== name) return { ok: false, name, reason: `spec name ${c.spec.name} does not match ${name}` };
  const raster = render(c.spec);
  const quality = textureQuality(raster);
  if (quality.verdict === "fail") return { ok: false, name, reason: qualityProblems(quality)[0] ?? "failed the texture checks", quality };
  const png = encodePng(raster);
  const canonical = canonicalJson(c.spec);
  return { ok: true, name, spec: c.spec, specSha256: sha256Hex(canonical), canonical, png, pngSha256: sha256Hex(png), quality };
}
// The real dependencies of lib/cyrus/assets/sync.ts (engine-core store + pack store from env). SERVER ONLY.
import { db } from "../../db";
import { addRevision, createProject, projectForRootBuild, recordAsset } from "../engine-core/store";
import { selectPackStore } from "../packhost/config";
import type { AssetSyncDeps } from "./sync";

export function defaultAssetSyncDeps(env: Record<string, string | undefined> = process.env): AssetSyncDeps {
  return {
    selectStore: () => selectPackStore(env),
    projectForRootBuild: (root) => projectForRootBuild(root),
    createProject: (i) => createProject(i),
    findRevisionForBuild: (projectId, modBuildId) => db.cyrusRevision.findFirst({ where: { projectId, modBuildId }, orderBy: { seq: "asc" }, select: { id: true } }),
    headRevisionId: async (projectId) => (await db.cyrusProject.findUnique({ where: { id: projectId }, select: { headRevisionId: true } }))?.headRevisionId ?? null,
    addRevision: (projectId, input) => addRevision(projectId, input),
    recordAsset: (projectId, a) => recordAsset(projectId, a),
  };
}
// A Minecraft resource pack from validated texture specs: one item model per texture, wired the 1.21.4+ way
// (assets/<ns>/items/<name>.json is what `ItemMeta.setItemModel(new NamespacedKey("<ns>", "<name>"))` points at).
import { createHash } from "node:crypto";
import { checkSpec, type TextureSpec } from "./dsl";
import { encodePng } from "./png";
import { render } from "./render";
import { zip } from "./zip";
import { getVersion, resourcePackFormat } from "../versions/registry";

/** Resource-pack major format for a version, from the version registry. Throws for an unknown/unverified version (never guesses). */
export function packFormatFor(mc: string): number {
  const r = resourcePackFormat(mc);
  if (!r.ok) throw new Error(r.error);
  return r.format.major;
}

export type BuiltPack = { packFormat: number; packClientVerified: boolean; zip: Buffer; sha1: string; bytes: number; files: string[]; textures: { name: string; model: string }[] };

export function buildPack(opts: { namespace: string; description: string; mcVersion: string; textures: unknown[]; allowPreview?: boolean }): { ok: true; pack: BuiltPack } | { ok: false; error: string } {
  if (!/^[a-z][a-z0-9_]{1,30}$/.test(opts.namespace)) return { ok: false, error: "namespace must be lowercase letters, digits and underscores" };
  if (opts.textures.length === 0 || opts.textures.length > 24) return { ok: false, error: "a pack needs 1-24 textures" };
  const specs: TextureSpec[] = [];
  for (const [i, t] of opts.textures.entries()) { const c = checkSpec(t); if (!c.ok) return { ok: false, error: `texture ${i + 1}: ${c.error}` }; if (specs.some((s) => s.name === c.spec.name)) return { ok: false, error: `duplicate texture name ${c.spec.name}` }; specs.push(c.spec); }
  const ver = getVersion(opts.mcVersion);
  if (ver && ver.status === "preview" && !opts.allowPreview) return { ok: false, error: `${opts.mcVersion} is a preview version: its resource packs are not verified in a real client yet` };
  const pf = resourcePackFormat(opts.mcVersion, { needsItemModels: true });
  if (!pf.ok) return { ok: false, error: pf.error };
  const fmt = pf.format.major;
  const files: { path: string; data: Buffer }[] = [
    { path: "pack.mcmeta", data: Buffer.from(JSON.stringify({ pack: { pack_format: fmt, supported_formats: { min_inclusive: 46, max_inclusive: 999 }, min_format: 46, max_format: 999, description: opts.description.slice(0, 100) } }, null, 2)) },
  ];
  const ns = opts.namespace;
  for (const s of specs) {
    files.push({ path: `assets/${ns}/textures/item/${s.name}.png`, data: encodePng(render(s)) });
    files.push({ path: `assets/${ns}/models/item/${s.name}.json`, data: Buffer.from(JSON.stringify({ parent: "minecraft:item/handheld", textures: { layer0: `${ns}:item/${s.name}` } }, null, 2)) });
    files.push({ path: `assets/${ns}/items/${s.name}.json`, data: Buffer.from(JSON.stringify({ model: { type: "minecraft:model", model: `${ns}:item/${s.name}` } }, null, 2)) });
  }
  const z = zip(files);
  return { ok: true, pack: { packFormat: fmt, packClientVerified: pf.clientVerified, zip: z, sha1: createHash("sha1").update(z).digest("hex"), bytes: z.length, files: files.map((f) => f.path).sort(), textures: specs.map((s) => ({ name: s.name, model: `${ns}:${s.name}` })) } };
}
import { deflateRawSync } from "node:zlib";
import { crc32 } from "./png";

/** A minimal, deterministic ZIP writer (fixed timestamps, sorted entries, deflate) so the same pack always hashes the same. */
export function zip(files: { path: string; data: Buffer }[]): Buffer {
  const sorted = [...files].sort((a, b) => (a.path < b.path ? -1 : 1));
  const parts: Buffer[] = []; const central: Buffer[] = []; let offset = 0;
  const DOS_TIME = 0, DOS_DATE = (1 << 5) | 1; // 1980-01-01 00:00
