// REAL Test Flight runs of the Cyrus R1 asset slice on node-2 (not part of the unit suite: boots real Paper servers).
//   tsx test/cyrus-assets-real.ts [v12111|v262|all] [--out file.json]
// Pipeline per version: golden texture specs -> the portal sync (lib/cyrus/assets/sync.ts: re-validate, render,
// quality, buildPack through the registry, publish to a LocalDiskStore with an https public base, Pack Loader entry)
// -> packs.json exactly as deliverBuildPack writes it (applyPackChange + serializeLoaderConfig) -> a flight with the
// Nxeon Pack Loader fixture jar + the TfItemModel fixture jar (does what generated mods do: setItemModel with the
// project's nx_ key). 26.2 is a preview version, so the production sync refuses its pack (no allowPreview); for the
// flight the 26.2 pack is built with buildPack(..., allowPreview: true) HERE ONLY, and that is reported.
// SERVER SIDE ONLY: no Minecraft client connects, so the pack download, the accept prompt and the textures actually
// showing in a client are NOT verified.
// Jars on node-2: /tank/nxeon-build/tmp/testflight/inbox/fx/{NxeonPackLoader-0.1.0.jar,TfItemModel-1.0.0.jar}
// (TfItemModel built by services/modbuilder/tools/testflight/fixtures/build.sh, see docs "Cyrus asset slice (R1)").
import { mkdtempSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import path from "node:path";
import { runTestFlight, type RunResult } from "../lib/cyrus/testflight/client";
import { describe } from "../lib/cyrus/testflight/summary";
import type { TestFlightSpec } from "../lib/cyrus/testflight/types";
import { applyPackChange, LOADER_CONFIG_PATH, serializeLoaderConfig } from "../lib/cyrus/packhost/loader-config";
import { LocalDiskStore } from "../lib/cyrus/packhost/local";
import { publishPack } from "../lib/cyrus/packhost/publish";
import { buildPack } from "../lib/cyrus/textures/pack";
import { checkSpec } from "../lib/cyrus/textures/dsl";
import { HEALTH_POTION } from "../lib/cyrus/textures/sample-items";
import { syncBuildAssets, type AssetSyncDeps } from "../lib/cyrus/assets/sync";

const FX = "/tank/nxeon-build/tmp/testflight/inbox/fx";
const NS = "nx_r1fl1ght";
const BASE = "https://packs.example.invalid";
const ruby = JSON.parse(readFileSync(path.join(__dirname, "fixtures/cyrus-textures/ruby_sword.json"), "utf8"));
const specs = [ruby, HEALTH_POTION].map((s) => { const c = checkSpec(s); if (!c.ok) throw new Error(c.error); return c.spec; });

async function packFor(version: string, store: LocalDiskStore) {
  if (version === "26.2") {
    const b = buildPack({ namespace: NS, description: "TfItemModel: custom textures by Cyrus", mcVersion: version, textures: specs, allowPreview: true });
    if (!b.ok) throw new Error(b.error);
    const pub = await publishPack(store, b.pack.zip, { maxBytes: 10 * 1024 * 1024 });
    if (!pub.ok) throw new Error(pub.error);
    return { path: "buildPack(allowPreview, test only)", sha1: pub.sha1, url: pub.url, format: b.pack.packFormat, bytes: b.pack.bytes, prompt: "TfItemModel uses custom item textures. Accept the pack to see them.", required: false };
  }
  const projects = new Map([[`mbflight${version}`, { id: "cp" + "f".repeat(20), namespace: NS, userId: "flight" }]]);
  const revs: { id: string; modBuildId: string | null }[] = [];
  const deps: AssetSyncDeps = {
    selectStore: () => ({ ok: true, store, maxBytes: 10 * 1024 * 1024 }),
    projectForRootBuild: async (r) => projects.get(r) ?? null,
    createProject: async () => { throw new Error("unexpected"); },
    findRevisionForBuild: async (_p, m) => revs.find((r) => r.modBuildId === m) ?? null,
    headRevisionId: async () => revs.at(-1)?.id ?? null,
    addRevision: async (_p, i) => { const r = { id: `rev${revs.length + 1}`, modBuildId: i.modBuildId ?? null }; revs.push(r); return r; },
    recordAsset: async () => null,
  };
  const a = await syncBuildAssets(
    { id: `mbflight${version}`, userId: "flight", rootBuildId: `mbflight${version}`, mcVersion: version, pluginName: "TfItemModel", jarName: null, jarSha256: null },
    { namespace: NS, promptVersion: null, qualityVersion: "tq-1", kept: false, downgraded: [], warnings: [], textures: specs.map((s) => ({ name: s.name, path: `assets/textures/${s.name}.json`, sha256: "", spec: s, quality: null })) },
    deps,
  );
  if (!a || a.status !== "ready" || !a.loader || !a.pack) throw new Error(`sync did not produce a hosted pack: ${JSON.stringify(a)}`);
  return { path: "syncBuildAssets (production path)", sha1: a.pack.sha1, url: a.loader.url, format: a.pack.format, bytes: a.pack.bytes, prompt: a.loader.prompt, required: a.loader.required, quality: a.textures.map((t) => `${t.name}:${t.quality}`) };
}

// Thin Test Flight invoker: push the runner + artifacts to node-2, run ONE flight, parse the report, summarise.
// Not wired into the live build path. All I/O goes through the injectable `Remote`, so tests use a fake.
// Server-only (node:child_process / node:fs).
import { spawn } from "node:child_process";
import { createHash, randomBytes } from "node:crypto";
import { readFileSync, readdirSync, statSync } from "node:fs";
import path from "node:path";
import type { TestFlightReport, TestFlightSpec, TestFlightSummary, ResolvedSpec } from "./types";
import { resolveSpec, validateSpec, TF_DEFAULT_ROOT } from "./spec";
import { summarize } from "./summary";

export type ExecResult = { code: number | null; stdout: string; stderr: string };
/** Runs a shell command line on the build host. `input` is piped to stdin. */
export type Remote = { exec: (command: string, opts?: { input?: Buffer; timeoutMs?: number }) => Promise<ExecResult> };

export const NODE2 = "root@178.63.94.114";
export const BUSY_EXIT = 75;

/** POSIX single-quote a word for a remote shell. */
export const shq = (s: string) => `'${String(s).replace(/'/g, `'\\''`)}'`;

/** Real transport: ssh with BatchMode (no prompts), hard local timeout (SIGKILL of the ssh child we spawned). */
export function sshRemote(host = NODE2): Remote {
  return {
    exec: (command, opts = {}) => new Promise((resolve) => {
      const child = spawn("ssh", ["-o", "BatchMode=yes", "-o", "ConnectTimeout=15", host, command], { stdio: ["pipe", "pipe", "pipe"] });
      let stdout = "", stderr = "";
      child.stdout.on("data", (d) => (stdout += d));
      child.stderr.on("data", (d) => (stderr += d));
      const t = setTimeout(() => child.kill("SIGKILL"), opts.timeoutMs ?? 120000);
      child.on("close", (code) => { clearTimeout(t); resolve({ code, stdout, stderr }); });
      child.stdin.on("error", () => {});
      child.stdin.end(opts.input ?? undefined);
    }),
  };
}

export type RunOptions = {
  remote?: Remote;
  root?: string;
  /** Directory holding runner.js + lib.js (default: the repo copy). */
  runnerDir?: string;
  runId?: string;
  readFile?: (p: string) => Buffer;
  /** Files of a local datapack directory, relative path -> absolute path. */
  listDir?: (dir: string) => { rel: string; abs: string }[];
};

export type RunResult = { report: TestFlightReport; summary: TestFlightSummary; resolved: ResolvedSpec; stderr: string };

const sha256 = (b: Buffer) => createHash("sha256").update(b).digest("hex");

function walk(dir: string, rel = ""): { rel: string; abs: string }[] {
  const out: { rel: string; abs: string }[] = [];
  for (const e of readdirSync(path.join(dir, rel)).sort()) {
    const r = rel ? `${rel}/${e}` : e;
    if (statSync(path.join(dir, r)).isDirectory()) out.push(...walk(dir, r));
    else out.push({ rel: r, abs: path.join(dir, r) });
  }
  return out;
}

export function newRunId(version: string): string {
  return `tf-${version.replace(/[^0-9]+/g, "-")}-${Date.now().toString(36)}-${randomBytes(3).toString("hex")}`.toLowerCase();
}

/** Minimal POSIX ustar archive (regular files only) so one ssh call can carry every artifact. */
export function tarball(entries: { name: string; data: Buffer }[]): Buffer {
  const blocks: Buffer[] = [];
  for (const e of entries) {
    if (!e.name || e.name.startsWith("/") || e.name.split("/").includes("..") || Buffer.byteLength(e.name) > 99) throw new Error(`bad tar entry name ${e.name}`);
    const h = Buffer.alloc(512);
    h.write(e.name, 0, "utf8");
    h.write("0000644\0", 100); h.write("0000000\0", 108); h.write("0000000\0", 116);
    h.write(e.data.length.toString(8).padStart(11, "0") + "\0", 124);
    h.write("00000000000\0", 136);
    h.fill(" ", 148, 156);
    h.write("0", 156);
    h.write("ustar\0" + "00", 257);
    let sum = 0;

async function spec(version: string, store: LocalDiskStore): Promise<{ spec: TestFlightSpec; pack: Awaited<ReturnType<typeof packFor>>; loaderId: string }> {
  const pack = await packFor(version, store);
  const r = applyPackChange(null, { op: "upsert", namespace: NS, role: "main", sha1: pack.sha1, prompt: pack.prompt, required: pack.required }, { urlFor: () => pack.url });
  if (!r.ok) throw new Error(r.error);
  return {
    pack, loaderId: r.id,
    spec: {
      version,
      plugins: [{ remotePath: `${FX}/NxeonPackLoader-0.1.0.jar` }, { remotePath: `${FX}/TfItemModel-1.0.0.jar` }],
      files: [{ path: LOADER_CONFIG_PATH, content: serializeLoaderConfig(r.config) }],
      rcon: [
        { id: "pack-listed", command: "nxpacks list", expect: ["1 pack(s)", r.id, `sha1=${pack.sha1}`, "required=false"], expectNot: ["REJECTED"] },
        { id: "loader-status", command: "nxpacks status", expect: ["packs=1", "config=ok"] },
        { id: "item-model-ruby", command: `tfitem ${NS} ruby_sword`, expect: [`itemModel=${NS}:ruby_sword`, "material=IRON_SWORD"] },
        { id: "item-model-potion", command: `tfitem ${NS} health_potion`, expect: [`itemModel=${NS}:health_potion`] },
        { id: "plugins-listed", command: "plugins", expect: ["NxeonPackLoader", "TfItemModel"] },
      ],
    },
  };
}

const brief = (name: string, r: RunResult, extra: unknown) => ({
  name, version: r.report.version, status: r.report.status, overall: r.summary.overall, success: r.summary.success,
  bootMs: r.report.bootMs, peakRssKb: r.report.peakRssKb, timings: r.report.timings,
  checks: r.report.checks.map((c) => ({ id: c.id, status: c.status, evidence: c.evidence })),
  line: describe(r.summary), notes: r.report.notes, artifacts: r.report.artifacts, engine: r.report.engine, ...((extra as object) ?? {}),
});

async function main() {
  const which = process.argv[2] ?? "all";
  const outIdx = process.argv.indexOf("--out");
  const versions: Record<string, string> = { v12111: "1.21.11", v262: "26.2" };
  const names = which === "all" ? ["v12111", "v262"] : [which];
  const dir = mkdtempSync(path.join(tmpdir(), "cyrus-r1-flight-"));
  const store = new LocalDiskStore(dir, BASE);
  const out: unknown[] = [];
  try {
    for (const n of names) { // strictly one at a time (node-2 rule)
      const s = await spec(versions[n], store);
      const r = await runTestFlight(s.spec);
      out.push(brief(n, r, { pack: s.pack, loaderId: s.loaderId, namespace: NS, client: "none (server-side only)" }));
      console.log(`${n}: ${describe(r.summary)}`);
    }
  } finally { rmSync(dir, { recursive: true, force: true }); }
  if (outIdx > 0) writeFileSync(process.argv[outIdx + 1], JSON.stringify(out, null, 1));
  else console.log(JSON.stringify(out, null, 1));
}
main().catch((e) => { console.error(e); process.exit(1); });

