v22.23.1
/**
 * Cyrus sound: a handful of sounds SYNTHESISED with Web Audio (no audio files: nothing to download or license),
 * driven by the effects bus (lib/cyrus/fx.ts) so the studio and the /cyrus demo sound like the same instrument.
 * OFF by default and per-browser (localStorage "cyrus-sfx"); turning it on is a click, which is also what the
 * browser needs before it lets a page make noise. Every function is a no-op on the server and when disabled.
 */
type Name = "tick" | "ping" | "whoosh" | "stage" | "success" | "error" | "thump";

const KEY = "cyrus-sfx";
let ctx: AudioContext | null = null;
let master: GainNode | null = null;
let on = false;
let loaded = false;
let lastTick = 0;
let lastWhoosh = 0;
const subs = new Set<() => void>();
let drone: { stop: () => void; set: (energy: number) => void } | null = null;

function load() {
  if (loaded || typeof window === "undefined") return;
  loaded = true;
  try { on = window.localStorage.getItem(KEY) === "on"; } catch { /* storage blocked: stays off */ }
}

function ensure(): AudioContext | null {
  load();
  if (!on || typeof window === "undefined") return null;
  const AC = window.AudioContext ?? (window as unknown as { webkitAudioContext?: typeof AudioContext }).webkitAudioContext;
  if (!AC) return null;
  if (!ctx) {
    ctx = new AC();
    const comp = ctx.createDynamicsCompressor();
    master = ctx.createGain();
    master.gain.value = 0.55;
    master.connect(comp);
    comp.connect(ctx.destination);
  }
  if (ctx.state === "suspended") void ctx.resume().catch(() => {});
  return ctx;
}

function noise(c: AudioContext, seconds: number) {
  const buf = c.createBuffer(1, Math.max(1, Math.floor(c.sampleRate * seconds)), c.sampleRate);
  const d = buf.getChannelData(0);
  for (let i = 0; i < d.length; i++) d[i] = Math.random() * 2 - 1;
  const src = c.createBufferSource();
  src.buffer = buf;
  return src;
}

function tone(c: AudioContext, o: { type?: OscillatorType; f: number; to?: number; at?: number; dur: number; vol: number; attack?: number; lp?: number }) {
  const t0 = c.currentTime + (o.at ?? 0);
  const osc = c.createOscillator();
  const g = c.createGain();
  osc.type = o.type ?? "sine";
  osc.frequency.setValueAtTime(o.f, t0);
  if (o.to) osc.frequency.exponentialRampToValueAtTime(o.to, t0 + o.dur);
  g.gain.setValueAtTime(0.0001, t0);
