// Cyrus sound library (R1 sound slice): METADATA ONLY for the owner's sound-effect library. The audio itself never
// enters git, /opt/nxeon or any served directory: it lives on the render host (node-2) under
// /tank/nxeon-build/tmp/sound-library/files, keyed by the original file name and verified by sha256 before use.
// library.manifest.json is generated by scripts/cyrus/sound-manifest.ts from a metadata scan done ON node-2
// (ffprobe + ffmpeg ebur128/astats); this module is pure (no I/O beyond the JSON import) and client-safe.
//
// Ids: `<slug of the file name>_<first 4 hex of the content sha256>` (e.g. `whoosh_fast_2_3fa1`): readable for the
// model and for people, and bound to the bytes (a replaced file gets a new id, so old specs fail loudly).
// Category: the file-name prefix (the part before the first " - ", digits dropped: "Whoosh", "Gunshot", "Door").
// Group: a sound-design class derived from the words (whoosh, impact, explosion, gunshot, creature, voice, ...).
// Tags: the group, the category and every meaningful word of the name.
import manifestJson from "./library.manifest.json";

export const SOUND_LIBRARY_VERSION = 1;

export const SOUND_GROUPS = [
  "whoosh", "impact", "explosion", "gunshot", "weapon", "creature", "voice", "animal", "door", "alert", "ui", "magic",
  "electronic", "music", "cartoon", "water", "weather", "ambience", "crowd", "vehicle", "machine", "foley",
] as const;
export type SoundGroup = (typeof SOUND_GROUPS)[number];

/** Keyword -> group. Checked on the prefix words first, then on the rest of the name; first hit wins. */
const GROUP_WORDS: Record<SoundGroup, string[]> = {
  whoosh: ["whoosh", "woosh", "swoosh", "swish", "whiz", "fly", "whip", "transition", "launch", "sonic"],
  impact: ["hit", "impact", "punch", "slap", "crash", "thud", "thump", "pounding", "stamp", "stunner", "screech", "knocking", "smash", "windup"],
  explosion: ["explosion", "boom", "braam", "rumble", "blast"],
  gunshot: ["gunshot", "gunshots", "laser"],
  weapon: ["gun", "racking", "reload", "ratcheting", "blade", "sword"],
  creature: ["growl", "monster", "roar", "snarl", "creepy"],
  voice: ["scream", "gasp", "grunt", "groan", "laughter", "laughing", "sneeze", "snore", "yawn", "exhale", "uh", "disappointed", "disappointment", "cough", "breath"],
  animal: ["animals", "bird", "birds", "cat", "dog", "cow", "duck", "cricket", "crickets", "horse", "scurry", "chirp"],
  door: ["door", "doorbell", "creak"],
  alert: ["alert", "notification", "buzzer", "siren", "alarm", "beep", "beeps", "bleep", "correct", "jammer"],
  ui: ["click", "mouse", "press", "next", "pop", "ding", "combo", "tape", "snap"],
  magic: ["shimmer", "sparkle", "glissando", "harp", "zap", "electrified", "magic", "chimes", "chime", "twinkle"],
  electronic: ["digital", "glitch", "static", "shutdown", "synth", "electronic", "rewind"],
  music: ["music", "musical", "jingle", "stinger", "dramatic", "reveal", "suspense", "mystery", "drum", "drums", "drumroll", "rimshot", "piano", "organ", "string", "strings", "pluck", "twang", "bell", "record", "scratch", "dj", "cymbal", "metal", "metallic"],
  cartoon: ["trombone", "dizzy", "party", "deflating", "boing", "oh"],
  water: ["water", "underwater", "bubbles", "splash", "drop", "toilet", "rain", "sizzle"],
  weather: ["thunderstorm", "thunder", "wind", "storm"],
  ambience: ["ambient", "forest", "city", "street", "room", "night", "heartbeat"],
  crowd: ["crowd", "applause", "clap", "clapping", "cheering"],
  vehicle: ["car", "train", "helicopter", "horn", "engine"],
  machine: ["machine", "machinery", "grating", "camera"],
  foley: ["footsteps", "glass", "zipper", "typing", "page", "paper", "crumple", "plastic", "wood", "rattle", "air", "blowing", "cracking"],
};

const STOP = new Set(["a", "an", "and", "the", "of", "in", "on", "to", "with", "x", "mp3", "short", "long", "single", "version", "v"]);

export type SoundLedger = {
  provenance: string;
  /** Never asserts originality. The owner documents the source per file group (see manifest.source.licenceDocument). */
  licenceStatus: string;
};
export type LibrarySound = {
  id: string;
  file: string;
  category: string;
  group: SoundGroup;
  tags: string[];
  /** seconds */
  duration: number;
  sampleRate: number;
  channels: number;
  bitRate: number;
  bytes: number;
  /** EBU R128 integrated loudness of the source (ffmpeg ebur128), LUFS; null for a clip too short/quiet to gate. */
  lufs: number | null;
  truePeakDb: number | null;
  samplePeakDb: number | null;
  rmsDb: number | null;
  dcOffset: number | null;
  sha256: string;
  ledger: SoundLedger;
};
export type SoundManifest = {
  version: number;
  generatedAt: string;
  source: { description: string; zipSha256: string; uploadedAs: string; fileCount: number; licenceDocument: { name: string; sha256: string; licensor: string; summary: string[]; nxeonReading: string } };
  tool: string;
  files: LibrarySound[];
};

export const LEDGER_PROVENANCE = "owner-provided (2026-10-10)";
export const LEDGER_LICENCE_STATUS = "unverified: owner to document source per file group";

/** Base name without the (possibly doubled) .mp3 extension. */
export const stemOf = (file: string) => file.replace(/(\.mp3)+$/i, "");

const words = (s: string) => s.toLowerCase().replace(/['’]/g, "").split(/[^a-z0-9]+/).filter(Boolean);

/** Readable, content-bound id (see header). */
export function soundIdFor(file: string, sha256: string): string {
  const slug = words(stemOf(file)).join("_").slice(0, 40).replace(/_+$/, "") || "sound";
  return `${/^[a-z]/.test(slug) ? slug : `s_${slug}`}_${sha256.slice(0, 4)}`;
}

/** Category, group and tags from a file name (pure; the manifest test re-derives every entry with it). */
export function tagsFromFilename(file: string): { category: string; group: SoundGroup; tags: string[] } {
  const stem = stemOf(file);
  const head = stem.split(" - ")[0].replace(/\s*\d+\s*$/, "").trim();
  const category = head.replace(/-/g, " ").replace(/\s+/g, " ").split(" ").map((w) => (w ? w[0].toUpperCase() + w.slice(1).toLowerCase() : w)).join(" ") || "Misc";
  const headWords = words(head);
  const all = words(stem).filter((w) => !/^\d+$/.test(w) && !/^\d+x$/.test(w));
  const find = (ws: string[]) => { for (const w of ws) for (const g of SOUND_GROUPS) if (GROUP_WORDS[g].includes(w)) return g; return null; };
  const group = find(headWords) ?? find(all) ?? "foley";
  const tags = [...new Set([group, ...category.toLowerCase().split(" "), ...all.filter((w) => !STOP.has(w) && w.length > 1)])].slice(0, 12);
  return { category, group, tags };
}

const manifest = manifestJson as unknown as SoundManifest;
let byId: Map<string, LibrarySound> | null = null;

export function soundManifest(): SoundManifest { return manifest; }
export function librarySounds(): readonly LibrarySound[] { return manifest.files; }
export function librarySound(id: string): LibrarySound | null {
  if (!byId) byId = new Map(manifest.files.map((f) => [f.id, f]));
  return byId.get(id) ?? null;
}

export type LibraryQuery = { text?: string; tags?: string[]; group?: string; category?: string; minDuration?: number; maxDuration?: number; limit?: number; offset?: number };

/**
 * Pure search over the manifest: every given filter must match (tags: all of them; text: every word must be a tag
 * prefix, a category word or part of the file name). Sorted by relevance (text hits), then shorter first, then id.
 */
export function searchLibrary(q: LibraryQuery, files: readonly LibrarySound[] = manifest.files): { total: number; items: LibrarySound[] } {
  const qWords = words(q.text ?? "");
  const tags = (q.tags ?? []).map((t) => t.toLowerCase());
  const scored: { s: LibrarySound; score: number }[] = [];
  for (const s of files) {
    if (q.group && s.group !== q.group) continue;
    if (q.category && s.category.toLowerCase() !== q.category.toLowerCase()) continue;
    if (q.minDuration != null && s.duration < q.minDuration) continue;
    if (q.maxDuration != null && s.duration > q.maxDuration) continue;
    if (tags.some((t) => !s.tags.includes(t))) continue;
    let score = 0;
    let miss = false;
    const name = stemOf(s.file).toLowerCase();
    for (const w of qWords) {
      if (s.tags.includes(w)) score += 3;
      else if (s.tags.some((t) => t.startsWith(w))) score += 2;
      else if (name.includes(w)) score += 1;
      else { miss = true; break; }
    }
    if (!miss) scored.push({ s, score });
  }
  scored.sort((a, b) => b.score - a.score || a.s.duration - b.s.duration || (a.s.id < b.s.id ? -1 : 1));
  const off = Math.max(0, q.offset ?? 0);
  const lim = Math.min(200, Math.max(1, q.limit ?? 50));
  return { total: scored.length, items: scored.slice(off, off + lim).map((x) => x.s) };
}

/**
 * The compact catalog the build service places (read-only) in the model's workspace: ids, group, tags, durations.
 * No audio, no file names, no loudness. One line per sound, grouped; stable order so it caches.
 * services/modbuilder/sound-catalog.txt is this text for the current manifest (a test keeps them equal).
 */
export function libraryCatalogText(files: readonly LibrarySound[] = manifest.files): string {
  const lines = [
    "# Nxeon sound library catalog (read-only). One sound per line: <id> <seconds>s <tags>.",
    "# Use an id as a layer source: {\"source\": \"lib:<id>\"}. Durations are the full source length.",
  ];
  for (const g of SOUND_GROUPS) {
    const xs = files.filter((f) => f.group === g).sort((a, b) => (a.id < b.id ? -1 : 1));
    if (!xs.length) continue;
    lines.push(`## ${g}`);
    for (const f of xs) lines.push(`${f.id} ${f.duration.toFixed(2)}s ${f.tags.filter((t) => t !== g).join(",")}`);
  }
  return lines.join("\n") + "\n";
}

/** The machine-readable catalog for validators: id -> duration in seconds (the service's sound-catalog.json). */
export function libraryCatalogDurations(files: readonly LibrarySound[] = manifest.files): Record<string, number> {
  const out: Record<string, number> = {};
  for (const f of [...files].sort((a, b) => (a.id < b.id ? -1 : 1))) out[f.id] = Math.round(f.duration * 1000) / 1000;
  return out;
}

