// Cyrus sound DSP (R1 sound slice): pure, deterministic signal processing on mono Float64 PCM at SAMPLE_RATE.
// No Web Audio, no randomness (synth.ts seeds its own PRNG), no I/O: the same input gives the same samples on every
// run, which is what makes a SoundSpec render reproducible (see render.ts and the golden hashes in the tests).
// Everything here runs on the RENDER HOST (node-2) via runner.ts; the portal only imports the types and limits.
import { createHash } from "node:crypto";

export const SAMPLE_RATE = 44100;
export type Mono = Float64Array;

export const dbToLin = (db: number) => Math.pow(10, db / 20);
export const linToDb = (v: number) => (v > 0 ? 20 * Math.log10(v) : -Infinity);
const sec = (s: number) => Math.max(0, Math.round(s * SAMPLE_RATE));

/** Average of the channels (equal weight): the mono downmix every shipped sound gets (mono = positional in Minecraft). */
export function downmix(channels: Float64Array[]): Mono {
  if (channels.length === 1) return Float64Array.from(channels[0]);
  const n = Math.min(...channels.map((c) => c.length));
  const out = new Float64Array(n);
  for (let i = 0; i < n; i++) { let s = 0; for (const c of channels) s += c[i]; out[i] = s / channels.length; }
  return out;
}

/** Interleaved little-endian float32 (what `ffmpeg -f f32le` writes) -> one Float64Array per channel. */
export function deinterleaveF32(buf: Buffer, channels: number): Float64Array[] {
  const frames = Math.floor(buf.length / 4 / channels);
  const out = Array.from({ length: channels }, () => new Float64Array(frames));
  for (let i = 0; i < frames; i++) for (let c = 0; c < channels; c++) out[c][i] = buf.readFloatLE((i * channels + c) * 4);
  return out;
}

export function trim(x: Mono, startS: number, lengthS?: number): Mono {
  const a = Math.min(x.length, sec(startS));
  const b = lengthS == null ? x.length : Math.min(x.length, a + sec(lengthS));
  return x.slice(a, b);
}

export function gain(x: Mono, db: number): Mono {
  if (db === 0) return x;
  const g = dbToLin(db);
  const out = new Float64Array(x.length);
  for (let i = 0; i < x.length; i++) out[i] = x[i] * g;
  return out;
}

/** Raised-cosine fades (no clicks). Lengths in milliseconds, clamped to half the clip each. */
export function fade(x: Mono, inMs: number, outMs: number): Mono {
  const out = Float64Array.from(x);
  const half = Math.floor(x.length / 2);
  const fi = Math.min(half, sec(inMs / 1000));
  const fo = Math.min(half, sec(outMs / 1000));
  for (let i = 0; i < fi; i++) { const s = Math.sin((Math.PI / 2) * (i / fi)); out[i] *= s * s; }
  for (let i = 0; i < fo; i++) { const s = Math.sin((Math.PI / 2) * (i / fo)); out[x.length - 1 - i] *= s * s; }
  return out;
}

/**
 * Pitch change by resampling (speed changes with pitch, exactly like Minecraft's own `pitch`): ratio 2^(st/12),
 * 4-point cubic Hermite interpolation. +12 st = one octave up, half as long.
 */
export function repitch(x: Mono, semitones: number): Mono {
  if (semitones === 0 || x.length < 2) return x;
  const ratio = Math.pow(2, semitones / 12);
  const n = Math.max(1, Math.floor((x.length - 1) / ratio));
  const out = new Float64Array(n);
  const at = (i: number) => x[i < 0 ? 0 : i >= x.length ? x.length - 1 : i];
  for (let j = 0; j < n; j++) {
    const p = j * ratio; const i = Math.floor(p); const t = p - i;
    const y0 = at(i - 1), y1 = at(i), y2 = at(i + 1), y3 = at(i + 2);
    const c1 = 0.5 * (y2 - y0), c2 = y0 - 2.5 * y1 + 2 * y2 - 0.5 * y3, c3 = 0.5 * (y3 - y0) + 1.5 * (y1 - y2);
    out[j] = ((c3 * t + c2) * t + c1) * t + y1;
  }
  return out;
}

/** Sum `src` into a buffer at an offset (seconds), growing it as needed. */
export function mixAt(dst: Mono, src: Mono, offsetS: number): Mono {
  const off = sec(offsetS);
  const n = Math.max(dst.length, off + src.length);
  const out = new Float64Array(n);
  out.set(dst);
  for (let i = 0; i < src.length; i++) out[off + i] += src[i];
  return out;
}

export type BiquadKind = "lowpass" | "highpass" | "bandpass" | "highshelf";
/** RBJ cookbook biquad (direct form I). */
export function biquad(x: Mono, kind: BiquadKind, freq: number, q = Math.SQRT1_2, gainDb = 0, rate = SAMPLE_RATE): Mono {
  const f = Math.min(Math.max(freq, 10), rate * 0.49);
  const w = (2 * Math.PI * f) / rate, cw = Math.cos(w), sw = Math.sin(w), alpha = sw / (2 * q);
