// SoundSpec v1 (Cyrus R1 sound slice): what the build model writes in assets/sounds/<set>.json, what the Sound
// Studio will edit, and what the render host turns into mono Ogg Vorbis. One file = one SOUND SET (a mob, an item, a
// spell) with its events; every event becomes one namespaced key `<namespace>:<set>.<event>` in the pack's
// sounds.json, with 1-4 weighted variants and a REQUIRED subtitle. Pure, client-safe.
//
// The JS twin services/modbuilder/sounds.js checkSoundSpec MUST give the same result (ok / exact error message /
// normalised spec) on every input: test/cyrus-sounds.test.ts runs both on test/fixtures/cyrus-sounds. Change both.
//
// {
//   "version": 1, "name": "banshee",
//   "events": [{
//     "event": "hurt", "role": "hurt", "category": "hostile", "subtitle": "Banshee shrieks",
//     "variants": [{ "weight": 2,
//       "layers": [ { "source": "synth:wail", "length": 0.5, "seed": 3, "params": { "start": 900 } },
//                   { "source": "lib:scream_2_ab12", "start": 0.02, "gain": -8, "pitch": -5, "trimStart": 0.1, "length": 0.4, "fadeOut": 80 } ],
//       "processing": { "lowpass": 6000, "reverb": 0.2 } }]
//   }]
// }
export const SOUND_SPEC_VERSION = 1;

export const SOUND_ROLES = ["ambient", "hurt", "death", "attack", "step", "ability", "fire", "reload", "spawn", "ui", "other"] as const;
export type SoundRole = (typeof SOUND_ROLES)[number];
/** Bukkit SoundCategory the plugin should pass (client volume slider). */
export const SOUND_CATEGORIES = ["master", "music", "record", "weather", "block", "hostile", "neutral", "player", "ambient", "voice"] as const;
export type SoundCategory = (typeof SOUND_CATEGORIES)[number];

export const SYNTH_PRESETS = ["growl", "wail", "whoosh", "impact", "gunshot", "click", "confirm", "magic"] as const;
export type SynthPreset = (typeof SYNTH_PRESETS)[number];

/**
 * Per-role loudness band (integrated LUFS, approximated for clips < 400 ms) and the longest allowed variant.
 * Attack/death/fire loudest, step/ambient 6-10 dB lower (sounds.json `volume` stays 1; balance is baked in).
 */
export const ROLE_PROFILE: Readonly<Record<SoundRole, { target: number; min: number; max: number; maxSeconds: number }>> = {
  attack: { target: -12, min: -16, max: -9, maxSeconds: 2 },
  death: { target: -12, min: -16, max: -9, maxSeconds: 4 },
  fire: { target: -11, min: -15, max: -8, maxSeconds: 2.5 },
  ability: { target: -13, min: -18, max: -9, maxSeconds: 6 },
  hurt: { target: -14, min: -18, max: -10, maxSeconds: 1.5 },
  spawn: { target: -15, min: -20, max: -11, maxSeconds: 4 },
  reload: { target: -16, min: -21, max: -12, maxSeconds: 3 },
  ui: { target: -18, min: -23, max: -14, maxSeconds: 1.5 },
  other: { target: -16, min: -22, max: -11, maxSeconds: 6 },
  ambient: { target: -20, min: -25, max: -16, maxSeconds: 4 },
