  if (!raw || typeof raw !== "object" || Array.isArray(raw)) return { ok: false, error: `${at} must be an object` };
  const r = raw as Record<string, unknown>;
  for (const k of Object.keys(r)) if (!["lowpass", "highpass", "reverb", "echo"].includes(k)) return { ok: false, error: `${at}: unknown field ${k}` };
  if (r.lowpass !== undefined) { if (!num(r.lowpass, 200, 20000)) return { ok: false, error: `${at}.lowpass must be 200-20000 Hz` }; p.lowpass = r.lowpass; }
  if (r.highpass !== undefined) { if (!num(r.highpass, 20, 5000)) return { ok: false, error: `${at}.highpass must be 20-5000 Hz` }; p.highpass = r.highpass; }
  if (r.reverb !== undefined) { if (!num(r.reverb, 0, 1)) return { ok: false, error: `${at}.reverb must be 0-1` }; p.reverb = r.reverb; }
  if (r.echo !== undefined) {
    const e = r.echo as Record<string, unknown>;
    if (!e || typeof e !== "object" || Array.isArray(e) || !num(e.delay, 20, 1000) || !num(e.feedback, 0, 0.7) || !num(e.mix, 0, 1) || Object.keys(e).some((k) => !["delay", "feedback", "mix"].includes(k))) return { ok: false, error: `${at}.echo must be {"delay": 20-1000 ms, "feedback": 0-0.7, "mix": 0-1}` };
    p.echo = { delay: e.delay as number, feedback: e.feedback as number, mix: e.mix as number };
  }
  return { ok: true, p };
}

/** A variant that would ship one library file as-is (only trim/gain/fades) is refused: library sounds must be transformed. */
function rawLibraryCopy(v: SoundVariant): boolean {
  const audible = v.layers.filter((l) => l.source !== "silence");
  if (audible.length !== 1 || !audible[0].source.startsWith("lib:")) return false;
  const p = v.processing;
  return audible[0].pitch === 0 && p.lowpass == null && p.highpass == null && p.reverb === 0 && p.echo == null;
}

export function checkSoundSpec(raw: unknown, ctx: SoundSpecContext): { ok: true; spec: SoundSpec; seconds: number } | { ok: false; error: string } {
  if (!raw || typeof raw !== "object" || Array.isArray(raw)) return { ok: false, error: "sound spec must be an object" };
  const r = raw as Record<string, unknown>;
  for (const k of Object.keys(r)) if (!["version", "name", "events"].includes(k)) return { ok: false, error: `unknown field ${k}` };
  if (r.version !== SOUND_SPEC_VERSION) return { ok: false, error: "version must be 1" };
  if (typeof r.name !== "string" || !NAME.test(r.name)) return { ok: false, error: "name must be lowercase letters, digits and underscores (2-32 chars)" };
  if (!Array.isArray(r.events) || r.events.length < 1 || r.events.length > MAX_EVENTS_PER_SET) return { ok: false, error: `events must be a list of 1-${MAX_EVENTS_PER_SET}` };
  const events: SoundEvent[] = [];
  let seconds = 0;
  for (const [ei, rawE] of r.events.entries()) {
    const at = `events[${ei}]`;
    if (!rawE || typeof rawE !== "object" || Array.isArray(rawE)) return { ok: false, error: `${at} must be an object` };
    const e = rawE as Record<string, unknown>;
    for (const k of Object.keys(e)) if (!["event", "role", "category", "subtitle", "variants"].includes(k)) return { ok: false, error: `${at}: unknown field ${k}` };
    if (typeof e.event !== "string" || !EVENT.test(e.event)) return { ok: false, error: `${at}.event must be lowercase letters, digits and underscores (1-24 chars)` };
    if (events.some((x) => x.event === e.event)) return { ok: false, error: `${at}: duplicate event ${e.event}` };
    if (!(SOUND_ROLES as readonly string[]).includes(e.role as string)) return { ok: false, error: `${at}.role must be one of ${SOUND_ROLES.join(", ")}` };
    const role = e.role as SoundRole;
    let category = DEFAULT_CATEGORY[role];
    if (e.category !== undefined) { if (!(SOUND_CATEGORIES as readonly string[]).includes(e.category as string)) return { ok: false, error: `${at}.category must be one of ${SOUND_CATEGORIES.join(", ")}` }; category = e.category as SoundCategory; }
    if (typeof e.subtitle !== "string" || e.subtitle.trim().length < 3 || e.subtitle.length > 60 || /[\u0000-\u001f<>§]/.test(e.subtitle)) return { ok: false, error: `${at}.subtitle is required: 3-60 characters of plain text (what a deaf player should read, e.g. "Banshee wails")` };
    if (!Array.isArray(e.variants) || e.variants.length < 1 || e.variants.length > MAX_VARIANTS) return { ok: false, error: `${at}.variants must be a list of 1-${MAX_VARIANTS}` };
    const variants: SoundVariant[] = [];
    for (const [vi, rawV] of e.variants.entries()) {
      const vat = `${at}.variants[${vi}]`;
      if (!rawV || typeof rawV !== "object" || Array.isArray(rawV)) return { ok: false, error: `${vat} must be an object` };
      const v = rawV as Record<string, unknown>;
      for (const k of Object.keys(v)) if (!["weight", "layers", "processing"].includes(k)) return { ok: false, error: `${vat}: unknown field ${k}` };
      let weight = 1;
      if (v.weight !== undefined) { if (typeof v.weight !== "number" || !Number.isInteger(v.weight) || v.weight < 1 || v.weight > 10) return { ok: false, error: `${vat}.weight must be an integer 1-10` }; weight = v.weight; }
      if (!Array.isArray(v.layers) || v.layers.length < 1 || v.layers.length > MAX_LAYERS) return { ok: false, error: `${vat}.layers must be a list of 1-${MAX_LAYERS}` };
      const layers: SoundLayer[] = [];
      for (const [li, rawL] of v.layers.entries()) { const c = checkLayer(rawL, `${vat}.layers[${li}]`, ctx); if (!c.ok) return c; layers.push(c.layer); }
      if (layers.every((l) => l.source === "silence")) return { ok: false, error: `${vat}: needs at least one layer that is not silence` };
      const pc = checkProcessing(v.processing, `${vat}.processing`);
      if (!pc.ok) return pc;
      const variant: SoundVariant = { weight, layers, processing: pc.p };
      if (rawLibraryCopy(variant)) return { ok: false, error: `${vat}: a library sound may not ship unchanged; change its pitch, layer it with another sound or add lowpass/highpass/reverb/echo` };
