      if (est > ROLE_PROFILE[role].maxSeconds + 0.5) return { ok: false, error: `${vat} is about ${est.toFixed(2)} s; a ${role} sound may be at most ${ROLE_PROFILE[role].maxSeconds} s (trim it with "length")` };
      seconds += est;
      variants.push(variant);
    }
    events.push({ event: e.event, role, category, subtitle: e.subtitle.trim(), variants });
  }
  seconds = r4(seconds);
  if (seconds > MAX_SPEC_SECONDS) return { ok: false, error: `the variants add up to about ${seconds.toFixed(1)} s; the limit per sound set is ${MAX_SPEC_SECONDS} s` };
