}

/** The pack key of an event (sounds.json key, without the namespace) and the subtitle translation key. */
export const soundKey = (set: string, event: string) => `${set}.${event}`;
export const subtitleKey = (namespace: string, set: string, event: string) => `subtitles.${namespace}.${set}.${event}`;

