// are clamped to the range). Output is peak-normalised to 0.9 before the layer's own gain.
import { biquad, fade, SAMPLE_RATE, type Mono } from "./dsp";
import type { SynthPreset } from "./spec";

export type ParamDef = { min: number; max: number; def: number; doc: string };
export const SYNTH_PARAMS: Readonly<Record<SynthPreset, Record<string, ParamDef>>> = {
  growl: {
    pitch: { min: 40, max: 400, def: 110, doc: "fundamental of the throat (Hz); lower = bigger creature" },
    rough: { min: 0, max: 1, def: 0.6, doc: "noise/jitter in the voice (0 clean hum, 1 ragged snarl)" },
    formant: { min: 250, max: 2000, def: 700, doc: "main mouth resonance (Hz); low = closed 'oo', high = open 'aa'" },
    vibrato: { min: 0, max: 14, def: 5, doc: "pitch wobble rate (Hz)" },
    attack: { min: 0.005, max: 0.5, def: 0.06, doc: "seconds to full volume" },
  },
  wail: {
    start: { min: 150, max: 2000, def: 750, doc: "pitch at the start (Hz)" },
    end: { min: 80, max: 2000, def: 360, doc: "pitch at the end (Hz): a falling glide sounds mournful" },
    vibrato: { min: 0, max: 12, def: 6, doc: "vibrato rate (Hz)" },
    depth: { min: 0, max: 1, def: 0.35, doc: "vibrato depth (0-1 semitone-ish)" },
    breath: { min: 0, max: 1, def: 0.25, doc: "airy noise mixed into the voice" },
    harmonics: { min: 0, max: 1, def: 0.4, doc: "FM brightness (0 pure sine, 1 harsh)" },
  },
  whoosh: {
    low: { min: 80, max: 3000, def: 300, doc: "band centre at the edges (Hz)" },
    high: { min: 300, max: 10000, def: 2800, doc: "band centre at the peak (Hz)" },
    peak: { min: 0.1, max: 0.9, def: 0.55, doc: "where the swell peaks (0-1 of the length)" },
    q: { min: 0.3, max: 8, def: 1.2, doc: "band resonance (higher = more whistly)" },
  },
  impact: {
    thump: { min: 25, max: 250, def: 60, doc: "body pitch (Hz), falls during the hit" },
    crack: { min: 0, max: 1, def: 0.5, doc: "amount of bright noise transient" },
    decay: { min: 0.02, max: 1.5, def: 0.18, doc: "seconds for the body to fade" },
    tone: { min: 300, max: 12000, def: 4000, doc: "lowpass of the noise part (Hz)" },
  },
  gunshot: {
    body: { min: 50, max: 500, def: 150, doc: "low boom pitch (Hz)" },
    crack: { min: 0, max: 1, def: 0.85, doc: "sharp supersonic crack amount" },
    tail: { min: 0.05, max: 1.5, def: 0.35, doc: "seconds of the noisy tail" },
    room: { min: 0, max: 1, def: 0.3, doc: "slap-back echo amount" },
  },
  click: {
    pitch: { min: 300, max: 8000, def: 2200, doc: "click brightness (Hz)" },
    body: { min: 0, max: 1, def: 0.3, doc: "low knock under the tick" },
  },
  confirm: {
    root: { min: 150, max: 2500, def: 660, doc: "first note (Hz)" },
    interval: { min: -12, max: 12, def: 7, doc: "second note, semitones from the first (7 = a fifth up)" },
