    sweep: { min: -24, max: 24, def: 12, doc: "pitch glide over the sound (semitones)" },
    sparkle: { min: 0, max: 1, def: 0.6, doc: "density of glittering grains" },
    shimmer: { min: 0, max: 20, def: 7, doc: "tremolo rate (Hz)" },
  },
