      for (let i = 0; i < n; i++) {
        const t = i / n;
        const f = p.start * Math.pow(p.end / p.start, t) * Math.pow(2, (p.depth * Math.sin((TAU * p.vibrato * i) / fs)) / 12);
        mph += (f * 2) / fs; ph += f / fs;
        const s = Math.sin(TAU * ph + p.harmonics * 2 * Math.sin(TAU * mph));
        x[i] = (s * (1 - p.breath * 0.5) + breath[i] * p.breath * 2) * env(i, n, 0.08 * Math.min(1, lengthS), fs);
      }
      break;
    }
    case "whoosh": {
      // noise through a band-pass whose centre swells from low to high and back, amplitude follows the swell
      const noise = noiseBuf(n, r);
      const seg = 512;
      for (let a = 0; a < n; a += seg) {
        const t = (a + seg / 2) / n;
        const k = t < p.peak ? t / p.peak : (1 - t) / (1 - p.peak);
        const fc = p.low * Math.pow(p.high / p.low, Math.max(0, Math.min(1, k)));
        const part = biquad(noise.slice(Math.max(0, a - 64), Math.min(n, a + seg)), "bandpass", fc, p.q);
