    }
    case "impact": {
      // pitch-dropping sine thump + low-passed noise crack, exponential decay
      let ph = 0;
      const crack = biquad(noiseBuf(n, r), "lowpass", p.tone, 0.7);
      for (let i = 0; i < n; i++) {
        const t = i / fs;
        const f = p.thump * (1 + 1.5 * Math.exp(-t / 0.02));
        ph += f / fs;
        x[i] = Math.sin(TAU * ph) * Math.exp(-t / p.decay) + crack[i] * p.crack * Math.exp(-t / 0.025);
      }
      break;
    }
    case "gunshot": {
      // instant crack (high-passed noise), boom (low sine + low-passed noise), noisy tail, slap-back echo
      let ph = 0;
      const nz = noiseBuf(n, r);
      const hi = biquad(nz, "highpass", 2500, 0.7), lo = biquad(nz, "lowpass", 700, 0.7);
      for (let i = 0; i < n; i++) {
        const t = i / fs;
        ph += (p.body * (1 + Math.exp(-t / 0.01))) / fs;
        x[i] = hi[i] * p.crack * Math.exp(-t / 0.006) * 1.6 + Math.sin(TAU * ph) * Math.exp(-t / 0.08) + lo[i] * Math.exp(-t / p.tail) * 0.8;
      }
      const d = Math.round(0.09 * fs);
      for (let i = n - 1; i >= d; i--) x[i] += x[i - d] * p.room * 0.4;
      break;
    }
    case "click": {
      let ph = 0;
      const nz = biquad(noiseBuf(n, r), "bandpass", p.pitch, 4);
      for (let i = 0; i < n; i++) { const t = i / fs; ph += 180 / fs; x[i] = nz[i] * Math.exp(-t / 0.004) * 3 + Math.sin(TAU * ph) * p.body * Math.exp(-t / 0.012); }
      break;
    }
    case "confirm": {
      const half = Math.floor(n / 2);
      const notes = [p.root, p.root * Math.pow(2, p.interval / 12)];
      let ph = 0;
      for (let i = 0; i < n; i++) {
        const k = i < half ? 0 : 1; const j = i - k * half; const t = j / fs;
        ph += notes[k] / fs;
        x[i] = (Math.sin(TAU * ph) + p.bright * 0.3 * Math.sin(TAU * ph * 3)) * Math.min(1, j / (0.004 * fs)) * Math.exp(-t / Math.max(0.03, (half / fs) * 0.45));
      }
      break;
    }
    case "magic": {
      // gliding triad + tremolo + randomly placed sine grains ("sparkle")
      const ph = [0, 0, 0];
      const ratios = [1, 1.25, 1.5];
      for (let i = 0; i < n; i++) {
        const t = i / n;
        const f = p.root * Math.pow(2, (p.sweep * t) / 12);
        let s = 0;
        for (let k = 0; k < 3; k++) { ph[k] += (f * ratios[k]) / fs; s += Math.sin(TAU * ph[k]) / 3; }
        x[i] = s * (0.6 + 0.4 * Math.sin((TAU * p.shimmer * i) / fs)) * env(i, n, 0.05, fs);
      }
      const grains = Math.round(p.sparkle * 40 * (n / fs));
      for (let g = 0; g < grains; g++) {
        const at = Math.floor(r() * n), len = Math.round((0.02 + r() * 0.04) * fs), gf = p.root * (2 + r() * 4);
