// SoundSpec -> PCM (Cyrus R1 sound slice). Pure: the caller supplies decoded library sources (mono 44.1 kHz), so
// this runs the same in the render host (runner.ts, real library via ffmpeg) and in tests (synth-only / fake sources).
// Chain per variant:
//   layers: source (library | synth preset | silence) -> trimStart/length -> pitch (resample) -> fades -> gain -> mix at start
//   processing: highpass, lowpass, echo, reverb
//   finish: 30 Hz rumble cut + DC block -> trim leading/trailing silence (-60 dBFS) -> cap at the role's max length
//           -> 2 ms / 8 ms edge fades -> normalise to the role's loudness target -> look-ahead limiter at -1.5 dBFS
//           (the -1 dBTP ceiling is checked again on the DECODED Ogg, after the encoder).
import { biquad, capLength, dcBlock, echo, fade, gain, limit, mixAt, repitch, reverb, trim, trimSilence, type Mono } from "./dsp";
import { measure, normalizeGainDb, rumbleCut } from "./measure";
import { ROLE_PROFILE, type SoundRole, type SoundSpec, type SoundVariant, type SynthPreset } from "./spec";
import { synth } from "./synth";

export const RENDER_VERSION = "sr-1";
export const LIMIT_CEILING_DB = -1.5;

export type SourceLoader = (libraryId: string) => Mono;
export type RenderedVariant = { pcm: Mono; truncated: boolean; gainDb: number; peakLimited: boolean };

export function renderVariant(v: SoundVariant, role: SoundRole, load: SourceLoader): RenderedVariant {
  let mix: Mono = new Float64Array(0);
  for (const l of v.layers) {
    let x: Mono;
    if (l.source === "silence") x = new Float64Array(Math.round((l.length ?? 0) * 44100));
    else if (l.source.startsWith("synth:")) x = synth(l.source.slice(6) as SynthPreset, l.length ?? 0.5, l.seed, l.params);
    else x = trim(load(l.source.slice(4)), l.trimStart, l.length ?? undefined);
    x = repitch(x, l.pitch);
    if (l.fadeIn || l.fadeOut) x = fade(x, l.fadeIn, l.fadeOut);
    x = gain(x, l.gain);
    mix = mixAt(mix, x, l.start);
  }
  const p = v.processing;
  if (p.highpass) mix = biquad(mix, "highpass", p.highpass);
  if (p.lowpass) mix = biquad(mix, "lowpass", p.lowpass);
  if (p.echo) mix = echo(mix, p.echo.delay, p.echo.feedback, p.echo.mix);
  if (p.reverb > 0) mix = reverb(mix, p.reverb);
  mix = trimSilence(dcBlock(rumbleCut(mix)));
  const capped = capLength(mix, ROLE_PROFILE[role].maxSeconds);
  mix = fade(capped.pcm, 2, 8);
  if (!mix.length) return { pcm: mix, truncated: capped.truncated, gainDb: 0, peakLimited: false };
  const g = normalizeGainDb(measure(mix), role, LIMIT_CEILING_DB);
  mix = limit(gain(mix, Math.max(-40, Math.min(40, g.gainDb))), LIMIT_CEILING_DB);
  return { pcm: mix, truncated: capped.truncated, gainDb: g.gainDb, peakLimited: g.peakLimited };
}

export type RenderedEvent = { event: string; variants: RenderedVariant[] };
export function renderSpec(spec: SoundSpec, load: SourceLoader): RenderedEvent[] {
  return spec.events.map((e) => ({ event: e.event, variants: e.variants.map((v) => renderVariant(v, e.role, load)) }));
}

/** Library ids a spec uses (sorted, unique): what the render host must load and the ledger records. */
export function libraryIdsOf(spec: SoundSpec): string[] {
  const s = new Set<string>();
  for (const e of spec.events) for (const v of e.variants) for (const l of v.layers) if (l.source.startsWith("lib:")) s.add(l.source.slice(4));
  return [...s].sort();
}

