// The render-host contract (Cyrus R1 sound slice): what the portal sends to the render host and what comes back.
// Types + limits only (client-safe). The host side is runner.ts (bundled to runner.bundle.cjs and run on node-2);
// the portal side is host.ts (ssh transport, injectable, a fake in tests).
import type { SoundSpec } from "./spec";
import type { SoundMeasure, SoundQualityReport } from "./measure";

export const RENDER_JOB_VERSION = 1;
export const MAX_JOB_OUTPUT_BYTES = 16 * 1024 * 1024;

export type RenderJob = {
  v: 1;
  /** Library sounds the specs use: id -> the file on the render host and the sha256 it must have. */
  library: { id: string; file: string; sha256: string; channels: number }[];
  sets: { name: string; spec: SoundSpec }[];
  /** Vorbis quality (-q:a), 0-10. 4 ~ 128 kb/s stereo-equivalent; mono effects are small. */
  vorbisQuality: number;
};

export type RenderedFile = {
  index: number; weight: number;
  ogg: string; // base64
  oggSha256: string; pcmSha256: string; bytes: number;
  encoded: { codec: string; channels: number; sampleRate: number; durationS: number };
  measure: SoundMeasure; quality: SoundQualityReport;
  render: { gainDb: number; peakLimited: boolean; truncated: boolean; ceilingDb: number; passes: number };
};
export type RenderResult = {
  ok: true;
  tool: { runner: string; render: string; quality: string; ffmpeg: string };
  sets: { name: string; events: { event: string; files: RenderedFile[] }[] }[];
  errors: { set: string; event?: string; error: string }[];
} | { ok: false; error: string; code: "busy" | "bad_job" | "library" | "ffmpeg" | "transport" | "timeout" };

