// The sound RENDER HOST runner (Cyrus R1 sound slice). Runs ON node-2 only, as a plain Node process:
//   node runner.bundle.cjs --ffmpeg <dir with ffmpeg+ffprobe> --library <dir of library files>  < job.json  > result.json
// It decodes library MP3s with ffmpeg (argv, no shell, file protocol only, sha256 checked first), renders every
// variant with the pure DSP (render.ts), encodes mono Ogg Vorbis with libvorbis in bitexact mode, decodes the Ogg back
// and runs the quality bar on what players will hear. If the encoder pushed the true peak above -1 dBTP it re-renders
// with a lower limiter ceiling (at most 2 more passes; still deterministic). Bundled by
// scripts/cyrus/build-sound-runner.ts (esbuild) into lib/cyrus/sound/runner.bundle.cjs, which host.ts ships over ssh.
import { spawnSync } from "node:child_process";
import { createHash } from "node:crypto";
import { readFileSync } from "node:fs";
import path from "node:path";
import { deinterleaveF32, downmix, pcmSha256, toS16, type Mono } from "./dsp";
import type { RenderJob, RenderResult, RenderedFile } from "./job";
import { measure, soundQuality, SOUND_QUALITY_VERSION, TRUE_PEAK_MAX } from "./measure";
import { LIMIT_CEILING_DB, renderVariant, RENDER_VERSION } from "./render";
import { checkSoundSpec, MAX_BUILD_SECONDS, MAX_SOUND_SETS } from "./spec";

export const RUNNER_VERSION = "cyrus-sound-runner-1";
const sha256 = (b: Buffer) => createHash("sha256").update(b).digest("hex");

type Ff = { ffmpeg: string; ffprobe: string };
function run(bin: string, args: string[], input?: Buffer, timeoutMs = 30000): Buffer {
  const r = spawnSync(bin, args, { input, maxBuffer: 64 * 1024 * 1024, timeout: timeoutMs, killSignal: "SIGKILL" });
  if (r.error) throw new Error(`${path.basename(bin)}: ${r.error.message}`);
  if (r.status !== 0) throw new Error(`${path.basename(bin)} exited ${r.status}: ${String(r.stderr).slice(-300)}`);
  return r.stdout as Buffer;
}

/** MP3 (or anything ffmpeg reads) -> mono 44.1 kHz. Resampling in ffmpeg (swresample, deterministic), downmix here. */
export function decodeFile(ff: Ff, file: string, channels: number): Mono {
  const out = run(ff.ffmpeg, ["-nostdin", "-v", "error", "-protocol_whitelist", "file", "-i", file, "-map", "0:a:0", "-f", "f32le", "-c:a", "pcm_f32le", "-ar", "44100", "-ac", String(channels), "pipe:1"]);
  return downmix(deinterleaveF32(out, channels));
}

/** 16-bit mono PCM -> Ogg Vorbis (libvorbis, bitexact: no encoder tag, fixed stream serial). */
export function encodeOgg(ff: Ff, s16: Buffer, quality: number): Buffer {
  return run(ff.ffmpeg, ["-nostdin", "-v", "error", "-protocol_whitelist", "pipe", "-f", "s16le", "-ar", "44100", "-ac", "1", "-i", "pipe:0",
    "-map_metadata", "-1", "-fflags", "+bitexact", "-flags:a", "+bitexact", "-c:a", "libvorbis", "-q:a", String(quality), "-ac", "1", "-f", "ogg", "pipe:1"], s16);
}

export function probeOgg(ff: Ff, ogg: Buffer): { codec: string; channels: number; sampleRate: number; durationS: number } {
  const j = JSON.parse(run(ff.ffprobe, ["-v", "error", "-protocol_whitelist", "pipe", "-show_entries", "stream=codec_name,channels,sample_rate:format=duration", "-of", "json", "-i", "pipe:0"], ogg).toString("utf8"));
  const s = j.streams?.[0] ?? {};
  return { codec: String(s.codec_name), channels: Number(s.channels), sampleRate: Number(s.sample_rate), durationS: Math.round(Number(j.format?.duration ?? 0) * 1000) / 1000 };
}

export function decodeOgg(ff: Ff, ogg: Buffer): Mono {
  const out = run(ff.ffmpeg, ["-nostdin", "-v", "error", "-protocol_whitelist", "pipe", "-f", "ogg", "-i", "pipe:0", "-f", "f32le", "-c:a", "pcm_f32le", "-ac", "1", "pipe:1"], ogg);
  return deinterleaveF32(out, 1)[0];
}

export function ffmpegVersion(ff: Ff): string {
  return run(ff.ffmpeg, ["-hide_banner", "-version"]).toString("utf8").split("\n")[0].trim();
}

/** The whole job. Specs are validated AGAIN here (the host trusts nobody); library files must match their sha256. */
export function runJob(job: RenderJob, opts: { ff: Ff; libraryDir: string }): RenderResult {
  if (!job || job.v !== 1 || !Array.isArray(job.sets) || !Array.isArray(job.library)) return { ok: false, code: "bad_job", error: "not a v1 render job" };
  if (job.sets.length > MAX_SOUND_SETS) return { ok: false, code: "bad_job", error: `at most ${MAX_SOUND_SETS} sound sets` };
  const q = Number.isFinite(job.vorbisQuality) ? Math.min(10, Math.max(0, job.vorbisQuality)) : 4;
  const lib = new Map(job.library.map((l) => [l.id, l]));
  const catalog: Record<string, number> = {};
  for (const l of job.library) {
    if (!/^[^/\\\0]{1,200}$/.test(l.file) || l.file.startsWith(".")) return { ok: false, code: "bad_job", error: `bad library file name for ${l.id}` };
    catalog[l.id] = 3600; // the true length is checked by the render itself; the portal already estimated durations
  }
  const decoded = new Map<string, Mono>();
  const load = (id: string): Mono => {
    const hit = decoded.get(id); if (hit) return hit;
    const l = lib.get(id); if (!l) throw new Error(`library id ${id} is not in the job`);
    const file = path.join(opts.libraryDir, l.file);
    const bytes = readFileSync(file);
    if (sha256(bytes) !== l.sha256) throw Object.assign(new Error(`library file for ${id} does not match its sha256`), { code: "library" });
    const pcm = decodeFile(opts.ff, file, Math.max(1, Math.min(8, l.channels | 0)));
    decoded.set(id, pcm); return pcm;
  };
  const errors: { set: string; event?: string; error: string }[] = [];
  const sets: { name: string; events: { event: string; files: RenderedFile[] }[] }[] = [];
  let seconds = 0;
  for (const s of job.sets) {
    const c = checkSoundSpec(s.spec, { catalog, library: true });
    if (!c.ok) { errors.push({ set: String(s.name), error: c.error }); continue; }
    if (c.spec.name !== s.name) { errors.push({ set: String(s.name), error: "set name does not match its spec" }); continue; }
    const events: { event: string; files: RenderedFile[] }[] = [];
    for (const e of c.spec.events) {
      const files: RenderedFile[] = [];
      try {
        for (const [i, v] of e.variants.entries()) {
          let ceiling = LIMIT_CEILING_DB;
          let out: RenderedFile | null = null;
          for (let pass = 1; pass <= 3; pass++) {
            const r = renderVariant(v, e.role, load, ceiling);
            seconds += r.pcm.length / 44100;
            if (seconds > MAX_BUILD_SECONDS * 1.5) throw new Error("render budget exceeded");
            const s16 = toS16(r.pcm);
            const ogg = encodeOgg(opts.ff, s16, q);
            const enc = probeOgg(opts.ff, ogg);
            const m = measure(decodeOgg(opts.ff, ogg));
            out = {
              index: i + 1, weight: v.weight, ogg: ogg.toString("base64"), oggSha256: sha256(ogg), pcmSha256: pcmSha256(r.pcm), bytes: ogg.length,
              encoded: enc, measure: m, quality: soundQuality(m, enc, e.role),
              render: { gainDb: r.gainDb, peakLimited: r.peakLimited, truncated: r.truncated, ceilingDb: ceiling, passes: pass },
            };
            if (m.truePeakDb <= TRUE_PEAK_MAX) break;
            ceiling = Math.round((ceiling - (m.truePeakDb - TRUE_PEAK_MAX) - 0.3) * 100) / 100; // encoder overshoot: lower the ceiling and redo
          }
          files.push(out!);
        }
        events.push({ event: e.event, files });
      } catch (err) {
        const code = (err as { code?: string }).code;
        if (code === "library") return { ok: false, code: "library", error: (err as Error).message };
        errors.push({ set: c.spec.name, event: e.event, error: (err as Error).message.slice(0, 300) });
      }
    }
    sets.push({ name: c.spec.name, events });
  }
  return { ok: true, tool: { runner: RUNNER_VERSION, render: RENDER_VERSION, quality: SOUND_QUALITY_VERSION, ffmpeg: ffmpegVersion(opts.ff) }, sets, errors };
}

function arg(name: string): string | null { const i = process.argv.indexOf(name); return i > 0 ? process.argv[i + 1] ?? null : null; }

/** CLI entry (only when executed directly, never on import). */
export function main() {
  const ffDir = arg("--ffmpeg"), libraryDir = arg("--library");
  if (!ffDir || !libraryDir) { process.stdout.write(JSON.stringify({ ok: false, code: "bad_job", error: "usage: --ffmpeg <dir> --library <dir>" })); process.exitCode = 2; return; }
  const chunks: Buffer[] = [];
  process.stdin.on("data", (d) => chunks.push(d as Buffer));
  process.stdin.on("end", () => {
    let res: RenderResult;
    try {
      const job = JSON.parse(Buffer.concat(chunks).toString("utf8")) as RenderJob;
      res = runJob(job, { ff: { ffmpeg: path.join(ffDir, "ffmpeg"), ffprobe: path.join(ffDir, "ffprobe") }, libraryDir });
    } catch (e) { res = { ok: false, code: /ffmpeg|ffprobe/.test(String((e as Error).message)) ? "ffmpeg" : "bad_job", error: String((e as Error).message).slice(0, 500) }; }
    process.stdout.write(JSON.stringify(res));
  });
}

