//   npx tsx scripts/cyrus/build-sound-runner.ts [--check]
import { readFileSync, writeFileSync } from "node:fs";
import path from "node:path";

export const BUNDLE_PATH = path.join(__dirname, "../../lib/cyrus/sound/runner.bundle.cjs");

export async function buildRunnerBundle(): Promise<string> {
  const esbuild = await import("esbuild");
  const r = await esbuild.build({
    entryPoints: [path.join(__dirname, "../../lib/cyrus/sound/runner-cli.ts")],
    bundle: true, platform: "node", format: "cjs", target: "node20", write: false, minify: false, legalComments: "none",
    banner: { js: "// GENERATED by scripts/cyrus/build-sound-runner.ts from lib/cyrus/sound/*.ts. Do not edit. Runs on the render host (node-2) only." },
  });
  // esbuild writes absolute-path-free comments ("// lib/cyrus/sound/dsp.ts"), so the bundle is stable across checkouts.
  return r.outputFiles[0].text;
}

