// Cyrus synth presets (R1 sound slice): pure, SEEDED synthesizers for the sound classes a mod needs, rendered to mono
// Float64 PCM at 44.1 kHz. Original by construction (no samples, no provenance risk), cheap, deterministic: the same
// preset + params + seed + length gives the same samples on every run (golden PCM hashes in test/cyrus-sounds.test.ts).
// (lib/cyrus/sfx.ts is the BROWSER UI-sound synth of the studio; it is unrelated and unchanged.)
//
// Every preset takes `length` (seconds) and a `seed`, plus the documented params below (missing -> default, values
// are clamped to the range). Output is peak-normalised to 0.9 before the layer's own gain.
import { biquad, fade, SAMPLE_RATE, type Mono } from "./dsp";
import type { SynthPreset } from "./spec";

export { SYNTH_PARAMS, type ParamDef } from "./synth-params";
import { SYNTH_PARAMS } from "./synth-params";

