"use strict";
// Sound specs in the build service (Cyrus R1 sound slice). The model writes SoundSpec files (assets/sounds/<set>.json:
// events -> variants -> layers of synth presets / library sounds, each event with a subtitle); this module checks them
// like code (validator generated from lib/cyrus/sound/spec.ts = ./sound-spec.js) and cross-checks the plugin. The
// service has NO audio tools: rendering, loudness and the Ogg encode happen on Nxeon's render host after the build
// (the portal re-validates everything there). Plain Node, no dependencies, I/O only in the workspace helpers.
const fs = require("fs");
const path = require("path");
const crypto = require("crypto");
const SS = require("./sound-spec");

const SOUND_DIR = "assets/sounds";
const SOUND_FILE_RE = /^assets\/sounds\/[a-z][a-z0-9_]{1,31}\.json$/;
const CATALOG_REL = "sound-library/catalog.txt";

let CATALOG = null;
/** id -> seconds from sound-catalog.json (generated from the library manifest); {} when missing (= no library). */
function catalog() {
  if (CATALOG) return CATALOG;
  try { CATALOG = JSON.parse(fs.readFileSync(path.join(__dirname, "sound-catalog.json"), "utf8")).durations || {}; } catch { CATALOG = {}; }
  return CATALOG;
}
let CATALOG_TEXT = null;
function catalogText() {
  if (CATALOG_TEXT !== null) return CATALOG_TEXT;
  try { CATALOG_TEXT = fs.readFileSync(path.join(__dirname, "sound-catalog.txt"), "utf8"); } catch { CATALOG_TEXT = ""; }
  return CATALOG_TEXT;
}

function canonicalJson(v) {
  if (Array.isArray(v)) return `[${v.map(canonicalJson).join(",")}]`;
  if (v && typeof v === "object") return `{${Object.keys(v).sort().map((k) => `${JSON.stringify(k)}:${canonicalJson(v[k])}`).join(",")}}`;
  return JSON.stringify(v);
}

function listSoundFiles(ws) {
  const dir = path.join(ws, SOUND_DIR);
  let names = [];
  try { names = fs.readdirSync(dir, { withFileTypes: true }); } catch { return []; }
  return names.filter((e) => e.isFile()).map((e) => `${SOUND_DIR}/${e.name}`).filter((rel) => SOUND_FILE_RE.test(rel)).sort()
    .map((rel) => ({ rel, abs: path.join(ws, rel), size: fs.statSync(path.join(ws, rel)).size }));
}
function snapshotSoundSpecs(ws) {
  const out = new Map();
  for (const f of listSoundFiles(ws)) out.set(f.rel, fs.readFileSync(f.abs));
  return out;
}

/** Put the catalog in the workspace for the model (read-only); removed again after each AI call. */
function placeCatalog(ws) {
  const text = catalogText();
  if (!text) return false;
  const abs = path.join(ws, CATALOG_REL);
  fs.mkdirSync(path.dirname(abs), { recursive: true });
  try { fs.chmodSync(abs, 0o644); } catch { /* not there yet */ }
  fs.writeFileSync(abs, text, { mode: 0o444 });
  fs.chmodSync(abs, 0o444);
  return true;
}
function dropCatalog(ws) { fs.rmSync(path.join(ws, path.dirname(CATALOG_REL)), { recursive: true, force: true }); }

function javaText(javaFiles) {
  let all = "";
  for (const f of javaFiles) { try { all += fs.readFileSync(f.abs, "utf8") + "\n"; } catch { /* gone */ } }
  return all;
}

/**
 * Validate every sound spec in the workspace (same contract as checkWorkspaceTextures):
 *   problems (HARD): invalid JSON / spec, file name != name, too many sets / events / seconds. Dropped after the
 *     bounded repairs, never shipped.
 *   soft: the plugin should play every event with its namespaced key, use the reserved namespace, and not use
 *     vanilla keys for custom sounds. One repair, then warnings.
 */
function checkWorkspaceSounds(ws, { namespace, javaFiles = [], library = false }) {
  const files = listSoundFiles(ws);
  const ctx = { catalog: library ? catalog() : null, library: !!library };
  const results = [];
  const problems = [];
  const soft = [];
  if (files.length > SS.MAX_SOUND_SETS) problems.push(`${files.length} sound spec files; the limit is ${SS.MAX_SOUND_SETS}. Merge sets (one file per mob/item) or drop some.`);
  let events = 0, seconds = 0;
  for (const f of files.slice(0, SS.MAX_SOUND_SETS)) {
    const want = path.basename(f.rel, ".json");
    const r = { rel: f.rel, name: want, ok: false, problems: [] };
    results.push(r);
    if (f.size > SS.MAX_SOUND_SPEC_BYTES) { r.problems.push(`${f.rel} is larger than ${SS.MAX_SOUND_SPEC_BYTES / 1024} KB`); continue; }
    let json;
    try { json = JSON.parse(fs.readFileSync(f.abs, "utf8")); } catch (e) { r.problems.push(`${f.rel} is not valid JSON: ${String(e.message).slice(0, 160)}`); continue; }
    const c = SS.checkSoundSpec(json, ctx);
    if (!c.ok) { r.problems.push(`${f.rel}: ${c.error}`); continue; }
    if (c.spec.name !== want) { r.problems.push(`${f.rel}: "name" is "${c.spec.name}" but the file is ${want}.json; they must match`); continue; }
    r.spec = c.spec; r.seconds = c.seconds;
    r.sha256 = crypto.createHash("sha256").update(canonicalJson(c.spec)).digest("hex");
    events += c.spec.events.length; seconds += c.seconds;
  }
  if (events > SS.MAX_EVENTS_TOTAL) problems.push(`${events} sound events in total; the limit is ${SS.MAX_EVENTS_TOTAL}`);
  if (seconds > SS.MAX_BUILD_SECONDS) problems.push(`the sounds add up to about ${seconds.toFixed(1)} s; the limit per mod is ${SS.MAX_BUILD_SECONDS} s`);
  if (files.length && javaFiles.length) {
    const text = javaText(javaFiles);
    const foreign = [...new Set((text.match(/\bnx_[a-z0-9]{8}\b/g) || []).filter((x) => x !== namespace))];
    if (foreign.length) soft.push(`The plugin uses the namespace ${foreign.join(", ")}; this mod's reserved namespace is ${namespace}. Every custom sound key is "${namespace}:<set>.<event>".`);
    if (/"minecraft:[a-z0-9_.]+"/.test(text) && /playSound/.test(text) && /"minecraft:(entity|block|item|ambient)\./.test(text)) soft.push(`The plugin plays a "minecraft:" sound key. Custom sounds must use "${namespace}:<set>.<event>" keys; never override vanilla sounds.`);
    for (const r of results) {
      if (!r.spec) continue;
      for (const e of r.spec.events) {
        const key = `${r.spec.name}.${e.event}`;
        if (!text.includes(`"${namespace}:${key}"`) && !text.includes(`"${key}"`)) soft.push(`${r.rel}: the plugin never plays "${namespace}:${key}"; play it with world.playSound(location, "${namespace}:${key}", SoundCategory.${categoryEnum(e.category)}, 1.0f, 1.0f) or remove the event`);
      }
    }
  }
  for (const r of results) { r.ok = r.problems.length === 0; problems.push(...r.problems); }
  return { files, results, problems: [...new Set(problems)], soft: [...new Set(soft)].slice(0, 30), events, seconds: Math.round(seconds * 1000) / 1000 };
}

const CATEGORY_ENUM = { master: "MASTER", music: "MUSIC", record: "RECORDS", weather: "WEATHER", block: "BLOCKS", hostile: "HOSTILE", neutral: "NEUTRAL", player: "PLAYERS", ambient: "AMBIENT", voice: "VOICE" };
const categoryEnum = (c) => CATEGORY_ENUM[c] || "MASTER";

module.exports = { SOUND_DIR, SOUND_FILE_RE, CATALOG_REL, SS, catalog, catalogText, listSoundFiles, snapshotSoundSpecs, placeCatalog, dropCatalog, checkWorkspaceSounds, categoryEnum, canonicalJson };

