// Texture specs (assets/textures/<name>.json) survive only when the request allows textures; otherwise the ones the
// base build already had are KEPT byte for byte (keeping is never gated) and anything new or changed is removed.
function sanitizeWorkspace(ws, rec) {
  const texturesOn = texOn(rec), soundsOn = sndOn(rec);
  const kept = keptSpecs.get(rec.id) || new Map();
  SND.dropCatalog(ws); // the read-only library catalog never survives into the source
  for (const f of listFiles(ws)) {
    const spec = TX.TEXTURE_FILE_RE.test(f.rel);
