// Portal half of the sound specs a build returns (Cyrus R1 sound slice). The build service validated them with its
// generated copy of the validator; the portal NEVER trusts that: it re-validates with lib/cyrus/sound/spec.ts against
// the committed library manifest, applies the library licence policy, builds the render job (specs + library refs, no
// audio) for the render host, and checks what comes back (sha256, Ogg magic, mono, quality verdict) before anything
// goes into the pack.
import { createHash } from "node:crypto";
import type { SvcSound } from "../../modbuilder/client";
import type { PackSoundEvent } from "../textures/pack";
import type { RenderJob, RenderResult, RenderedFile } from "../sound/job";
import { libraryCatalogDurations, librarySound, LEDGER_LICENCE_STATUS, LEDGER_PROVENANCE } from "../sound/library";
import { libraryIdsOf } from "../sound/render";
import { checkSoundSpec, MAX_BUILD_SECONDS, MAX_EVENTS_TOTAL, MAX_SOUND_SETS, type SoundSpec } from "../sound/spec";
import { canonicalJson, sha256Hex } from "./textures";

export const SOUND_SPEC_MIME = "application/vnd.nxeon.sound-spec+json";
export const VORBIS_QUALITY = 4;

let CATALOG: Record<string, number> | null = null;
const catalog = () => (CATALOG ??= libraryCatalogDurations());

export type CheckedSound =
  | { ok: true; set: string; spec: SoundSpec; specSha256: string; canonical: string; seconds: number; libraryIds: string[] }
  | { ok: false; set: string; reason: string };

/**
 * Re-validate one returned sound set. `library` = may this build use the owner's library (licence cleared)? When not,
 * a set that uses it is refused here even if the service accepted it (kept specs included): no library audio ships
 * until the owner confirms the licence.
 */
export function checkReturnedSound(s: Pick<SvcSound, "key" | "spec">, opts: { library: boolean }): CheckedSound {
  const set = typeof s.key === "string" ? s.key : "?";
  const c = checkSoundSpec(s.spec, { catalog: catalog(), library: true });
  if (!c.ok) return { ok: false, set, reason: c.error };
  if (c.spec.name !== set) return { ok: false, set, reason: `spec name ${c.spec.name} does not match ${set}` };
  const libraryIds = libraryIdsOf(c.spec);
  if (libraryIds.length && !opts.library) return { ok: false, set, reason: "it uses Nxeon's sound library, which is not available for customer mods yet" };
  const canonical = canonicalJson(c.spec);
  return { ok: true, set, spec: c.spec, specSha256: sha256Hex(canonical), canonical, seconds: c.seconds, libraryIds };
}

/** Enforce the per-mod budgets across sets (sets beyond the budget are refused in order, never partially). */
export function withinBudget(sets: Extract<CheckedSound, { ok: true }>[]): { keep: Extract<CheckedSound, { ok: true }>[]; over: { set: string; reason: string }[] } {
  const keep: Extract<CheckedSound, { ok: true }>[] = [];
  const over: { set: string; reason: string }[] = [];
  let events = 0, seconds = 0;
  for (const s of sets) {
    if (keep.length >= MAX_SOUND_SETS) { over.push({ set: s.set, reason: `more than ${MAX_SOUND_SETS} sound sets` }); continue; }
    if (events + s.spec.events.length > MAX_EVENTS_TOTAL) { over.push({ set: s.set, reason: `more than ${MAX_EVENTS_TOTAL} sound events in this mod` }); continue; }
    if (seconds + s.seconds > MAX_BUILD_SECONDS) { over.push({ set: s.set, reason: `more than ${MAX_BUILD_SECONDS} s of sound in this mod` }); continue; }
    keep.push(s); events += s.spec.events.length; seconds += s.seconds;
  }
  return { keep, over };
}

/** The render job: specs + only the library entries they use (file name on the host + sha256 + channels + length). */
export function renderJobFor(sets: Extract<CheckedSound, { ok: true }>[]): RenderJob {
  const ids = [...new Set(sets.flatMap((s) => s.libraryIds))].sort();
  const library = ids.map((id) => { const l = librarySound(id)!; return { id, file: l.file, sha256: l.sha256, channels: l.channels, duration: l.duration }; });
  return { v: 1, library, sets: sets.map((s) => ({ name: s.set, spec: s.spec })), vorbisQuality: VORBIS_QUALITY };
}

export type AcceptedEvent = { set: string; event: string; role: string; category: string; subtitle: string; files: (RenderedFile & { data: Buffer })[] };

/**
 * Check the render host's answer against the specs we sent: every file must decode from base64 to bytes whose sha256
 * is the one reported, start with "OggS", be mono Vorbis and not FAIL the quality bar. A variant that fails is left
 * out; an event left with no variant is dropped (the plugin plays nothing for it), never shipped half-checked.
 */
export function acceptRendered(sets: Extract<CheckedSound, { ok: true }>[], res: Extract<RenderResult, { ok: true }>): { events: AcceptedEvent[]; dropped: { name: string; reason: string }[] } {
  const events: AcceptedEvent[] = [];
  const dropped: { name: string; reason: string }[] = [];
  for (const e of res.errors ?? []) dropped.push({ name: e.event ? `${e.set}.${e.event}` : e.set, reason: `render failed: ${String(e.error).slice(0, 160)}` });
  for (const s of sets) {
    const got = res.sets.find((x) => x.name === s.set);
    for (const ev of s.spec.events) {
      const name = `${s.set}.${ev.event}`;
      const r = got?.events.find((x) => x.event === ev.event);
      if (!r) { if (!dropped.some((d) => d.name === name || d.name === s.set)) dropped.push({ name, reason: "the render host returned nothing for it" }); continue; }
      const files: AcceptedEvent["files"] = [];
      for (const f of r.files.slice(0, ev.variants.length)) {
        const data = Buffer.from(String(f.ogg ?? ""), "base64");
        const sha = createHash("sha256").update(data).digest("hex");
        if (sha !== f.oggSha256 || data.subarray(0, 4).toString("latin1") !== "OggS") { dropped.push({ name: `${name}#${f.index}`, reason: "the rendered file did not match its checksum" }); continue; }
        if (f.encoded?.channels !== 1 || f.encoded?.codec !== "vorbis") { dropped.push({ name: `${name}#${f.index}`, reason: "not mono Ogg Vorbis" }); continue; }
        if (f.quality?.verdict === "fail") { const why = f.quality.checks.find((c) => c.status === "fail"); dropped.push({ name: `${name}#${f.index}`, reason: `failed the sound check ${why ? `${why.id} (${why.value}, limit ${why.limit})` : ""}`.trim() }); continue; }
        files.push({ ...f, weight: ev.variants[f.index - 1]?.weight ?? f.weight, data });
      }
      if (!files.length) { if (!dropped.some((d) => d.name.startsWith(name))) dropped.push({ name, reason: "no variant passed the sound checks" }); continue; }
      events.push({ set: s.set, event: ev.event, role: ev.role, category: ev.category, subtitle: ev.subtitle, files });
    }
  }
  return { events, dropped };
}

export const packSoundsOf = (events: AcceptedEvent[]): PackSoundEvent[] =>
  events.map((e) => ({ set: e.set, event: e.event, subtitle: e.subtitle, files: e.files.map((f) => ({ index: f.index, weight: f.weight, data: f.data })) }));

/** One ledger row per library sound a set uses (the owner's licence status travels with every asset). */
export function ledgerOf(s: Extract<CheckedSound, { ok: true }>): { libraryId: string; file: string; sha256: string; provenance: string; licenceStatus: string }[] {
  return s.libraryIds.map((id) => { const l = librarySound(id); return { libraryId: id, file: l?.file ?? "?", sha256: l?.sha256 ?? "", provenance: l?.ledger.provenance ?? LEDGER_PROVENANCE, licenceStatus: l?.ledger.licenceStatus ?? LEDGER_LICENCE_STATUS }; });
}

