body='''export async function syncBuildAssets(build: SyncBuild, ar: SvcAssetResult | null | undefined, deps: AssetSyncDeps): Promise<MbAssets | null> {
  if (!ar || (!ar.textures?.length && !ar.sounds?.length && !ar.downgraded?.length)) return null;
  const root = build.rootBuildId ?? build.id;
  let project = await deps.projectForRootBuild(root);
  if (!project) {
    // A kept-texture change on a chain made before its project existed; create it (same reserved namespace rules).
    try { project = await deps.createProject({ userId: build.userId, game: "minecraft", rootBuildId: root }); }
    catch { project = await deps.projectForRootBuild(root); }
  }
  if (!project) throw new Error(`no Cyrus project for build chain ${root}`);
  const hasSounds = !!ar.sounds?.length;
  const base: MbAssets = { status: "none", namespace: project.namespace, projectId: project.id, revisionId: null, textures: [], ...(hasSounds ? { sounds: [], soundRender: "none" as const } : {}), dropped: [...(ar.downgraded ?? [])].map((d) => ({ name: d.name, reason: d.reason })).slice(0, 32), pack: null, loader: null, notices: [...(ar.warnings ?? [])].slice(0, 20) };
  if (ar.namespace && ar.namespace !== project.namespace) {
    return { ...base, status: "failed", notices: [...base.notices, "The custom assets were made for a different namespace than this mod's, so they were not shipped."] };
  }

  // 1. never trust the service: validate, render and quality-check again
  const ok: Extract<ReturnType<typeof checkReturnedTexture>, { ok: true }>[] = [];
  for (const t of (ar.textures ?? []).slice(0, 24)) {
    const c = checkReturnedTexture(t);
    if (!c.ok) { base.dropped.push({ name: c.name, reason: c.reason }); base.notices.push(`Custom texture "${c.name}" was left out: it did not pass Nxeon's texture checks.`); continue; }
    if (ok.some((x) => x.name === c.name)) continue;
    ok.push(c);
  }
  // 1b. sounds: re-validate (library licence policy), budget, then render on the render host and check the result
  const sndOk: Extract<CheckedSound, { ok: true }>[] = [];
  for (const sv of (ar.sounds ?? []).slice(0, 16)) {
    const c = checkReturnedSound(sv, { library: deps.soundLibraryCleared?.() === true });
    if (!c.ok) { base.dropped.push({ name: c.set, reason: c.reason }); base.notices.push(`Custom sound set "${c.set}" was left out: ${c.reason}.`); continue; }
    if (sndOk.some((x) => x.set === c.set)) continue;
    sndOk.push(c);
  }
  const budget = withinBudget(sndOk);
  for (const o of budget.over) { base.dropped.push({ name: o.set, reason: o.reason }); base.notices.push(`Custom sound set "${o.set}" was left out: ${o.reason}.`); }
  let accepted: AcceptedEvent[] = [];
  let renderTool: Record<string, string> | null = null;
  let renderHostId: string | null = null;
  if (budget.keep.length) {
    const sel = deps.selectRenderHost?.() ?? ({ ok: false, reason: "no render host" } as const);
    if (!sel.ok) {
      base.soundRender = "off";
      base.notices.push("The custom sounds are designed, but sound rendering is not switched on yet, so players don't hear them yet.");
    } else {
      renderHostId = sel.host.id;
      const res = await sel.host.render(renderJobFor(budget.keep)).catch((e) => ({ ok: false as const, code: "transport" as const, error: (e as Error).message }));
      if (!res.ok) {
        base.soundRender = "failed";
        base.notices.push(`The custom sounds could not be rendered right now (${res.code}), so players don't hear them yet.`);
      } else {
        const a = acceptRendered(budget.keep, res);
        accepted = a.events; renderTool = res.tool;
        for (const d of a.dropped) { base.dropped.push(d); base.notices.push(`Custom sound "${d.name}" was left out: ${d.reason}.`); }
        base.soundRender = accepted.length ? "rendered" : "failed";
      }
    }
  }
  base.dropped = base.dropped.slice(0, 32);
  base.notices = [...new Set(base.notices)].slice(0, 30);
  const soundRows: NonNullable<MbAssets["sounds"]> = accepted.map((e) => ({
    set: e.set, event: e.event, key: `${project!.namespace}:${e.set}.${e.event}`, subtitle: e.subtitle, role: e.role, category: e.category, variants: e.files.length,
    quality: e.files.some((f) => f.quality.verdict === "warn") ? "warn" : "pass", specSha256: budget.keep.find((s) => s.set === e.set)!.specSha256,
  }));
  if (!ok.length && !accepted.length) {
    if (!budget.keep.length) return base;
    // sounds designed but not rendered (off / failed): still record the specs in a revision so a later re-render can ship them
  }
  const name = build.pluginName || "this mod";
  const what = ok.length && accepted.length ? "custom textures and sounds" : accepted.length ? "custom sounds" : "custom textures";

  // 2. the deterministic pack, through the registry (preview versions refused: no allowPreview in this path)
  const textures = ok.map((c) => ({ name: c.name, model: `${project!.namespace}:${c.name}`, specSha256: c.specSha256, pngSha256: c.pngSha256, quality: c.quality.verdict as "pass" | "warn" }));
  let pack: import("../textures/pack").BuiltPack | null = null;
  if (ok.length || accepted.length) {
    const built = buildPack({ namespace: project.namespace, description: clip(`${name}: ${what} by Cyrus`, 100), mcVersion: build.mcVersion, textures: ok.map((c) => c.spec), sounds: packSoundsOf(accepted) });
    if (!built.ok) {
      return { ...base, status: "failed", textures, ...(hasSounds ? { sounds: soundRows } : {}), notices: [...base.notices, `The resource pack could not be built for Minecraft ${build.mcVersion}: ${built.error}.`] };
    }
    pack = built.pack;
  }
  const packSha256 = pack ? sha256Hex(pack.zip) : null;

  // 3. host it (immutable, content addressed); 4. the Pack Loader entry
  let url: string | null = null;
  let loader: MbAssets["loader"] = null;
  const notices = [...base.notices];
  if (pack) {
    const sel = deps.selectStore();
    if (sel.ok) {
      // A storage outage must not hold the plugin back: the pack stays "unhosted" (the revision still records it).
      const pub = await publishPack(sel.store, pack.zip, { maxBytes: sel.maxBytes }).catch((e) => ({ ok: false as const, code: "store_error" as const, error: (e as Error).message }));
      if (pub.ok) {
        url = pub.url;
        const prompt = clip(ok.length && accepted.length ? `${name} uses custom item textures and sounds. Accept the pack to see and hear them.` : accepted.length ? `${name} uses custom sounds. Accept the pack to hear them.` : `${name} uses custom item textures. Accept the pack to see them.`, 300);
        const r = applyPackChange(null, { op: "upsert", namespace: project.namespace, role: PACK_ROLE, sha1: pub.sha1, prompt, required: false }, { urlFor: () => pub.url });
        if (r.ok) loader = { id: r.id, url: pub.url, sha1: pub.sha1, prompt, required: false };
        else notices.push("The pack was published, but its delivery entry could not be prepared.");
      } else notices.push(`The resource pack could not be published (${pub.code}).`);
    } else {
      notices.push(`The resource pack is built, but pack delivery to servers is not switched on yet, so players won't ${accepted.length && !ok.length ? "hear the custom sounds" : accepted.length ? "see or hear the custom assets" : "see the custom textures"} yet.`);
    }
  }

  // 5. revision + asset rows (idempotent)
  const manifest: ManifestEntry[] = [
    ...(build.jarName && build.jarSha256 ? [{ path: `plugin/${build.jarName}`, sha256: build.jarSha256, role: "artifact" as const }] : []),
    ...ok.map((c) => ({ path: `assets/textures/${c.name}.json`, sha256: c.specSha256, role: "asset" as const })),
    ...budget.keep.map((c) => ({ path: `assets/sounds/${c.set}.json`, sha256: c.specSha256, role: "asset" as const })),
    ...(pack && packSha256 ? [{ path: `resourcepack/${pack.sha1}.zip`, sha256: packSha256, role: "resourcePack" as const }] : []),
  ];
  const parts = [
    ...(ok.length ? [`${ok.length} custom texture${ok.length > 1 ? "s" : ""}`] : []),
    ...(budget.keep.length ? [`${accepted.length} custom sound event${accepted.length === 1 ? "" : "s"}${base.soundRender !== "rendered" ? ` (${budget.keep.length} set${budget.keep.length > 1 ? "s" : ""} not rendered: ${base.soundRender})` : ""}`] : []),
  ];
  const toolchain = [
    ...(ok.length ? [`cyrus-textures ${QUALITY_VERSION} (service ${ar.qualityVersion})`] : []),
    ...(renderTool ? [`cyrus-sound ${renderTool.render}/${renderTool.quality} on ${renderHostId} (${renderTool.ffmpeg.replace(/ Copyright.*$/, "")})`] : []),
    ...(pack ? [`pack format ${pack.packFormat}`] : []),
  ].join("; ");
  let revisionId: string | null = null;
  for (let attempt = 0; attempt < 4 && !revisionId; attempt++) {
    const found = await deps.findRevisionForBuild(project.id, build.id);
    if (found) { revisionId = found.id; break; }
    const head = await deps.headRevisionId(project.id);
    try {
      const rev = await deps.addRevision(project.id, {
        kind: "generated", manifest, modBuildId: build.id, status: "passed", expectedHeadId: head,
        engine: { ...(ar.promptVersion ? { promptVersion: ar.promptVersion } : {}), toolchain },
        message: clip(`${parts.join(" + ")}${pack ? `; pack ${pack.sha1.slice(0, 12)}` : ""}${ar.kept ? " (kept unchanged)" : ""}`, 200),
      });
      revisionId = rev.id;
    } catch (e) {
      if ((e as { code?: string }).code === "stale_head") continue; // someone appended meanwhile: look again
      throw e;
    }
  }
  if (!revisionId) throw new Error("could not record the asset revision (the project kept moving)");
  for (const c of ok) {
    await deps.recordAsset(project.id, {
      revisionId, assetKey: c.name, kind: "texture", sha256: c.specSha256, size: Buffer.byteLength(c.canonical), origin: "generated",
      mime: TEXTURE_SPEC_MIME, path: `assets/textures/${c.name}.json`,
      provenance: { generator: "cyrus-texture-dsl", spec: c.spec, quality: c.quality, pngSha256: c.pngSha256, packSha1: pack?.sha1 ?? null, modBuildId: build.id, kept: ar.kept === true },
    });
  }
  for (const c of budget.keep) {
    const evs = accepted.filter((e) => e.set === c.set);
    await deps.recordAsset(project.id, {
      revisionId, assetKey: c.set, kind: "sound", sha256: c.specSha256, size: Buffer.byteLength(c.canonical), origin: "generated",
      mime: SOUND_SPEC_MIME, path: `assets/sounds/${c.set}.json`,
      provenance: {
        generator: "cyrus-soundspec", spec: c.spec, render: base.soundRender, renderHost: renderHostId, tool: renderTool,
        events: evs.map((e) => ({ event: e.event, key: `${project!.namespace}:${c.set}.${e.event}`, subtitle: e.subtitle, files: e.files.map((f) => ({ index: f.index, weight: f.weight, oggSha256: f.oggSha256, pcmSha256: f.pcmSha256, bytes: f.bytes, durationS: f.encoded.durationS, measure: f.measure, quality: f.quality, render: f.render })) })),
        ledger: ledgerOf(c), packSha1: pack?.sha1 ?? null, modBuildId: build.id, kept: ar.kept === true || (ar.keptKinds ?? []).includes("sound"),
      },
    });
  }
  return {
    ...base, status: !pack ? "none" : url ? "ready" : "unhosted", revisionId, textures, ...(hasSounds ? { sounds: soundRows } : {}), notices,
    pack: pack && packSha256 ? { sha1: pack.sha1, sha256: packSha256, bytes: pack.bytes, format: pack.packFormat, clientVerified: pack.packClientVerified, url } : null,
    loader,
  };
}

