const FAKE_JAR = `#!/usr/bin/env node
const a = process.argv.slice(2); require("fs").writeFileSync(a[a.indexOf("--file") + 1], "PK fake");
`;
const FAKE_JAVAP = `#!/usr/bin/env node
`;
// The service's only npm dependency (yaml) is installed in its image, not in the app; when it
// is not resolvable here a flat key: value stand-in is enough for these plugin.yml files.
const YAML_STUB = `module.exports = {
  parse(t) { const o = {}; for (const l of String(t).split("\\n")) { const m = l.match(/^([\\w-]+):\\s*(.*)$/); if (m) o[m[1]] = m[2].replace(/^'(.*)'$/, "$1"); } return o; },
  stringify(o) { return Object.entries(o).map(([k, v]) => k + ": " + (typeof v === "string" && /^[\\d.]+$/.test(v) ? "'" + v + "'" : v)).join("\\n") + "\\n"; },
};
`;
function yamlPath(): string | null { try { require.resolve("yaml", { paths: [SVC] }); return null; } catch { return "stub"; } }

let dir = "", proc: ChildProcess | null = null, port = 0, svcErr = "";
const log = () => fs.readFileSync(path.join(dir, "claude.log"), "utf8").trim().split("\n").filter(Boolean).map((l) => JSON.parse(l));
async function api(method: string, p: string, body?: unknown) {
  const r = await fetch(`http://127.0.0.1:${port}${p}`, { method, headers: { Authorization: `Bearer ${KEY}`, "Content-Type": "application/json" }, body: body ? JSON.stringify(body) : undefined });
  return r.json();
}
async function waitDone(id: string) {
  for (let i = 0; i < 200; i++) {
    const r = await api("GET", `/builds/${id}`);
    if (r.status === "succeeded" || r.status === "failed") return r;
    await new Promise((res) => setTimeout(res, 100));
  }
  throw new Error("build did not finish");
}

describe("modbuilder 0.5 pipeline (offline, fake CLI + javac)", () => {
  before(async () => {
    dir = fs.mkdtempSync(path.join(os.tmpdir(), "mb-pipe-"));
    const bin = path.join(dir, "bin");
    fs.mkdirSync(bin);
    for (const [n, t] of [["claude", FAKE_CLAUDE], ["javac", FAKE_JAVAC], ["jar", FAKE_JAR], ["javap", FAKE_JAVAP]]) {
      fs.writeFileSync(path.join(bin, n), t, { mode: 0o755 });
    }
    const cp = path.join(dir, "cp");
    fs.mkdirSync(cp);
    fs.writeFileSync(path.join(cp, "1.21.11.txt"), "/nonexistent.jar\n");
    fs.writeFileSync(path.join(cp, "1.21.11.classes.txt"), "org/bukkit/configuration/file/FileConfiguration.class\norg/bukkit/plugin/java/JavaPlugin.class\norg/bukkit/NamespacedKey.class\n");
    fs.writeFileSync(path.join(dir, "claude.log"), "");
    fs.copyFileSync(path.join(ROOT, "test/fixtures/cyrus-textures/ruby_sword.json"), path.join(dir, "ruby_sword.json"));
    const nodePath = path.join(dir, "node_modules");
    if (yamlPath()) { fs.mkdirSync(path.join(nodePath, "yaml"), { recursive: true }); fs.writeFileSync(path.join(nodePath, "yaml", "index.js"), YAML_STUB); }
    port = 37000 + Math.floor(Math.random() * 2000);
    const child = spawn(process.execPath, [path.join(SVC, "server.js")], {
      env: {
        PATH: `${bin}:${process.env.PATH}`, HOME: dir, PORT: String(port), MB_DATA: path.join(dir, "data"), MB_WORK: path.join(dir, "work"),
        MB_TEMPLATE: path.join(SVC, "template"), MB_CP_DIR: cp, MODBUILDER_API_KEY: KEY, MB_VERSIONS: "1.21.11", MB_DEDUPE: "on",
        MB_EFFORT: "medium", MB_GUARD: "off", NODE_PATH: nodePath, // guard off: these tests count AI calls; the guard has its own tests (modbuilder-guard.test.ts)
      } as unknown as NodeJS.ProcessEnv,
      stdio: ["ignore", "ignore", "pipe"],
    });
    proc = child;
    child.stderr?.on("data", (d) => { svcErr += d; });
    for (let i = 0; i < 100; i++) {
      try { const h = await (await fetch(`http://127.0.0.1:${port}/health`)).json(); if (h.ok) return; } catch { /* starting */ }
      await new Promise((res) => setTimeout(res, 100));
    }
    throw new Error(`service did not start: ${svcErr.slice(-2000)}`);
  });
  after(() => { if (proc) proc.kill("SIGKILL"); fs.rmSync(dir, { recursive: true, force: true }); });

  it("reports 0.5 and its knobs on /health", async () => {
    const h = await (await fetch(`http://127.0.0.1:${port}/health`)).json();
    assert.equal(h.image, "0.5");
    assert.equal(h.features.usage, true);
    assert.equal(h.features.autofix, true);
    assert.equal(h.features.dedupe, true);
    assert.equal(h.features.effort, "medium");
  });

  it("builds with one AI call: wrong import + final main fixed without a model repair, usage recorded", async () => {
    await api("POST", "/builds", { id: "pipe-one-01", prompt: "Say hello to every player who joins", mcVersion: "1.21.11" });
    const r = await waitDone("pipe-one-01");
    assert.equal(r.status, "succeeded", JSON.stringify(r.events) + svcErr.slice(-3000));
    assert.equal(r.aiCalls.length, 1, "no repair call " + JSON.stringify(r.events.map((e: { message: string; detail?: string }) => e.message + (e.detail ? " :: " + e.detail : ""))));
    assert.equal(r.repairs, 0);
    const kinds = r.autofixes.map((f: { kind: string }) => f.kind).sort();
    assert.deepEqual(kinds, ["main-final", "missing-import", "wrong-import"]);
    assert.equal(r.usage.savedRepairs, 1);
    const c = r.aiCalls[0];
    assert.deepEqual(c.tokens, { input: 32904, cacheRead: 28900, output: 3040, uncached: 4, cacheWrite: 4000 });
    assert.equal(c.turnsDetail.length, 2);
    assert.deepEqual(c.toolCalls, { Write: 3 });
    assert.equal(c.effort, "medium");
    for (const s of ["generate", "validate", "precheck", "compile", "autofix", "scan"]) assert.ok(r.usage.stages[s], `stage ${s}`);
    assert.equal(r.usage.stages.compile.n, 2, "compiled, auto-fixed, compiled again");
    assert.ok(r.dedupeKey);
    assert.ok(r.events.some((e: { message: string }) => /Fixed 1 import automatically/.test(e.message)), "import fixed before javac (would have cost a pre-check repair)");
    assert.ok(r.events.some((e: { message: string }) => /Fixed 1 known API mistake automatically/.test(e.message)), "missing import fixed after javac");
    const calls = log();
    assert.deepEqual(calls[0].tools, ["Read", "Write", "Edit"], "fresh builds get the lean tool set");
    assert.equal(calls[0].effort, "medium");
    // the fixed source is what was kept
    const src = await (await fetch(`http://127.0.0.1:${port}/builds/pipe-one-01/source?path=src/main/java/dev/nxeon/plugins/hello/Hello.java`, { headers: { Authorization: `Bearer ${KEY}` } })).text();
    assert.match(src, /import org\.bukkit\.configuration\.file\.FileConfiguration;/);
    assert.match(src, /^public class Hello extends JavaPlugin/m);
    assert.match(src, /^import org\.bukkit\.NamespacedKey;$/m);
  });

  it("reuses an identical earlier build with no AI call, and `fresh: true` opts out", async () => {
    const before = log().length;
    await api("POST", "/builds", { id: "pipe-two-02", prompt: "  Say hello to every player   who joins ", mcVersion: "1.21.11" });
    const r = await waitDone("pipe-two-02");
    assert.equal(r.status, "succeeded");
    assert.equal(r.reusedFrom, "pipe-one-01");
    assert.equal(r.costUsd, 0);
    assert.equal(r.aiCalls.length, 0);
    assert.equal(r.jar.name, "Hello-1.0.0.jar");
    assert.equal(log().length, before, "the CLI was not called");
    await api("POST", "/builds", { id: "pipe-three-03", prompt: "Say hello to every player who joins", mcVersion: "1.21.11", fresh: true });
    const f = await waitDone("pipe-three-03");
    assert.equal(f.status, "succeeded");
    assert.equal(f.reusedFrom, null);
    assert.equal(log().length, before + 1);
  });

  it("change requests keep Glob/Grep and are never reused", async () => {
    await api("POST", "/builds", { id: "pipe-four-04", prompt: "Say hello to every player who joins", mcVersion: "1.21.11", baseBuildId: "pipe-one-01", changeRequest: "Say it twice" });
    const r = await waitDone("pipe-four-04");
    assert.equal(r.status, "succeeded", JSON.stringify(r.events));
    assert.equal(r.dedupeKey, null);
    const last = log().at(-1);
    assert.equal(last.kind, "change");
    assert.deepEqual(last.tools, ["Read", "Write", "Edit", "Glob", "Grep"]);
  });

  // ---- Cyrus R1 asset slice -------------------------------------------------------------------------------
  const NS = "nx_ab12cd34";
  const ev = (r: { events: { message: string }[] }) => r.events.map((e) => e.message);

  it("texture build: section + namespace sent, spec validated, returned with its quality report", async () => {
    const before = log().length;
    await api("POST", "/builds", { id: "pipe-tex-ok-01", prompt: "A ruby sword TEXTURE build", mcVersion: "1.21.11", assets: { texture: true, sound: false, namespace: NS } });
    const r = await waitDone("pipe-tex-ok-01");
    assert.equal(r.status, "succeeded", JSON.stringify(r.events) + svcErr.slice(-2000));
    const call = log()[before];
    assert.equal(call.textures, true, "TEXTURES section in the system prompt");
    assert.equal(call.nsInPrompt, NS);
    assert.deepEqual(call.tools, ["Read", "Write", "Edit"], "the model still only has Read/Write/Edit");
    assert.equal(r.aiCalls.length, 1);
    assert.equal(r.dedupeKey, null, "asset builds are never deduped");
    assert.equal(r.assetResult.namespace, NS);
    assert.equal(r.assetResult.kept, false);
    assert.deepEqual(r.assetResult.textures.map((t: { name: string }) => t.name), ["ruby_sword"]);
    assert.equal(r.assetResult.textures[0].quality.verdict, "pass");
    assert.match(r.assetResult.textures[0].sha256, /^[0-9a-f]{64}$/);
    assert.ok(r.files.some((f: { path: string }) => f.path === "assets/textures/ruby_sword.json"), "the spec is part of the source");
  });

  it("an invalid spec goes back to the model as an asset repair (bounded), then ships", async () => {
    const before = log().length;
    await api("POST", "/builds", { id: "pipe-tex-bad-02", prompt: "A ruby sword BADTEXTURE build", mcVersion: "1.21.11", assets: { texture: true, namespace: NS } });
    const r = await waitDone("pipe-tex-bad-02");
    assert.equal(r.status, "succeeded", JSON.stringify(ev(r)));
    assert.equal(r.repairs, 1);
    assert.deepEqual(log().slice(before).map((c: { kind: string }) => c.kind), ["generate", "repair-asset"]);
    assert.ok(r.events.some((e: { message: string; detail?: string }) => /ruby_sword\.json: ops\[2\]: bad line/.test(e.detail || "")), "repair feedback names the problem");
    assert.equal(r.assetResult.textures.length, 1);
  });

  it("a spec that keeps failing the quality bar is dropped with a reason, never shipped", async () => {
    await api("POST", "/builds", { id: "pipe-tex-ugly-03", prompt: "A ruby sword UGLYTEXTURE build", mcVersion: "1.21.11", assets: { texture: true, namespace: NS } });
    const r = await waitDone("pipe-tex-ugly-03");
    assert.equal(r.status, "succeeded", JSON.stringify(ev(r)));
    assert.equal(r.repairs, 2, "MB_MAX_ASSET_REPAIRS default 2");
    assert.equal(r.assetResult.textures.length, 0);
    assert.equal(r.assetResult.downgraded[0].name, "ruby_sword");
    assert.ok(r.warnings.some((w: string) => /ruby_sword.*left out/.test(w)), JSON.stringify(r.warnings));
    assert.ok(r.summary.limitations.some((l: string) => /texture checks/.test(l)));
    assert.ok(!r.files.some((f: { path: string }) => f.path.startsWith("assets/")));
  });

  it("textures not allowed: no section, no namespace, and a texture file the model writes is removed", async () => {
    const before = log().length;
    await api("POST", "/builds", { id: "pipe-tex-no-04", prompt: "A ruby sword TEXTURE build without rights", mcVersion: "1.21.11" });
    const r = await waitDone("pipe-tex-no-04");
    assert.equal(r.status, "succeeded", JSON.stringify(ev(r)));
    assert.equal(log()[before].textures, false);
    assert.equal(log()[before].nsInPrompt, null);
    assert.ok(ev(r).includes("Removed unexpected file assets/textures/ruby_sword.json"));
    assert.equal(r.assetResult, undefined);
    assert.equal(r.assets, undefined, "no assets field recorded: the pre-R1 record shape");
  });

  it("a change without texture rights keeps the base's specs byte for byte (keep is never gated)", async () => {
    await api("POST", "/builds", { id: "pipe-tex-keep-05", prompt: "A ruby sword TEXTURE build", mcVersion: "1.21.11", baseBuildId: "pipe-tex-ok-01", changeRequest: "Say it twice" });
    const r = await waitDone("pipe-tex-keep-05");
    assert.equal(r.status, "succeeded", JSON.stringify(ev(r)));
    assert.ok(ev(r).some((m: string) => /Keeping 1 existing custom texture unchanged/.test(m)));
    assert.equal(r.assetResult.kept, true);
    assert.equal(r.assetResult.textures[0].sha256, (await api("GET", "/builds/pipe-tex-ok-01")).assetResult.textures[0].sha256);
  });

  it("rejects a malformed assets field; textures on a version without item models are switched off", async () => {
    const bad = await fetch(`http://127.0.0.1:${port}/builds`, { method: "POST", headers: { Authorization: `Bearer ${KEY}`, "Content-Type": "application/json" }, body: JSON.stringify({ id: "pipe-tex-bad-06", prompt: "A ruby sword TEXTURE", mcVersion: "1.21.11", assets: { texture: true, namespace: "minecraft" } }) });
    assert.equal(bad.status, 400);
    // eslint-disable-next-line @typescript-eslint/no-require-imports
    const TX = require(path.join(SVC, "textures.js"));
    assert.deepEqual(TX.parseAssetsRequest({ texture: true, namespace: NS }, "1.21.1", new Set(["1.21.11"])), { texture: false, sound: false, namespace: NS, notes: ["textures are off: Minecraft 1.21.1 has no item model definitions"] });
    assert.equal(TX.parseAssetsRequest(undefined, "1.21.11", new Set()), null);
    assert.ok(TX.parseAssetsRequest({ texture: "yes", namespace: NS }, "1.21.11", new Set()).error);
  });
});

