// Cyrus R1 sound slice, pure tests (no ffmpeg, no network, no DB): library manifest coverage + search, SoundSpec
// validation and TS == JS (generated service copy) equivalence on the shared fixtures, generated files up to date,
// DSP / synth golden PCM hashes and determinism, measurement + quality bar, the pack with sounds, the portal sync
// with a FAKE render host (idempotent), the render-host transport with a fake ssh Remote, the sound gate across
// plans, the prompt section, and the NxLabs page lines.
import { describe, it } from "node:test";
import assert from "node:assert/strict";
import { execFileSync } from "node:child_process";
import { createHash } from "node:crypto";
import fs from "node:fs";
import path from "node:path";
import { groupFor, librarySounds, LEDGER_LICENCE_STATUS, LEDGER_PROVENANCE, libraryCatalogText, nameWords, searchLibrary, soundIdFor, soundManifest, stemOf, tagsFromFilename } from "../lib/cyrus/sound/library";
import { checkSoundSpec, type SoundSpec } from "../lib/cyrus/sound/spec";
import { libraryCatalogDurations } from "../lib/cyrus/sound/library";
import { synth } from "../lib/cyrus/sound/synth";
import { SYNTH_PRESETS } from "../lib/cyrus/sound/spec";
import { biquad, dbToLin, echo, fade, limit, mixAt, pcmSha256, repitch, reverb, SAMPLE_RATE, toS16, trimSilence, wav } from "../lib/cyrus/sound/dsp";
import { loudness, measure, soundQuality, truePeakDb } from "../lib/cyrus/sound/measure";
import { renderSpec, renderVariant } from "../lib/cyrus/sound/render";
import type { RenderJob, RenderResult } from "../lib/cyrus/sound/job";
import { selectRenderHost, sshRenderHost, type RenderHost } from "../lib/cyrus/sound/host";
import { buildPack } from "../lib/cyrus/textures/pack";
import { syncBuildAssets, type AssetSyncDeps } from "../lib/cyrus/assets/sync";
import { planBuildAssets, ASSET_PIPELINE_READY } from "../lib/cyrus/assets/plan";
import { resolveBuildAssets, existingAssetKinds } from "../lib/cyrus/assets/request";
import { assetLines } from "../lib/cyrus-mods/doc";
import type { MbAssets } from "../lib/modbuilder/types";
import type { SvcAssetResult } from "../lib/modbuilder/client";
import { LocalDiskStore } from "../lib/cyrus/packhost/local";

const ROOT = path.resolve(__dirname, "..");
// eslint-disable-next-line @typescript-eslint/no-require-imports
const SSJS = require(path.join(ROOT, "services/modbuilder/sound-spec.js"));
// eslint-disable-next-line @typescript-eslint/no-require-imports
const P = require(path.join(ROOT, "services/modbuilder/prompts.js"));
const FIX = JSON.parse(fs.readFileSync(path.join(ROOT, "test/fixtures/cyrus-sounds/specs.json"), "utf8")) as { cases: { name: string; ctx: "lib" | "nolib"; valid: boolean; spec: unknown }[] };
const CATALOG = libraryCatalogDurations();
const ctxOf = (c: "lib" | "nolib") => (c === "lib" ? { catalog: CATALOG, library: true } : { catalog: null, library: false });
const EXAMPLE = JSON.parse(fs.readFileSync(path.join(ROOT, "services/modbuilder/sound-example.json"), "utf8"));
const NS = "nx_ab12cd34";

describe("sound library manifest (metadata only)", () => {
  const m = soundManifest();
  const files = librarySounds();
  it("covers all 514 files with unique, content-bound ids", () => {
    assert.equal(files.length, 514);
    assert.equal(m.source.fileCount, 514);
    assert.equal(new Set(files.map((f) => f.id)).size, 514, "ids unique");
    assert.equal(new Set(files.map((f) => f.sha256)).size, 514, "no duplicate audio");
    for (const f of files) {
      assert.equal(f.id, soundIdFor(f.file, f.sha256), f.file);
      assert.match(f.id, /^[a-z][a-z0-9_]{1,52}$/);
      assert.match(f.sha256, /^[0-9a-f]{64}$/);
    }
  });
  it("tags every file from its name: category, a keyword-matched group, at least two tags", () => {
    for (const f of files) {
      const t = tagsFromFilename(f.file);
      assert.deepEqual({ category: f.category, group: f.group, tags: f.tags }, t, f.file);
      assert.ok(groupFor(nameWords(f.file)), `no group keyword in "${f.file}"`);
      assert.ok(f.tags.length >= 2 && f.tags.includes(f.group), f.file);
      assert.ok(f.category && f.category !== "Misc", f.file);
    }
    const cats = new Set(files.map((f) => f.category));
    for (const c of ["Whoosh", "Hit", "Explosion", "Door", "Alert", "Animals", "Scream", "Gasp", "Water", "Gunshot"]) assert.ok(cats.has(c), `category ${c}`);
  });
  it("records audio facts and a ledger row per file, never asserting originality", () => {
    for (const f of files) {
      assert.ok(f.duration > 0 && f.duration < 120 && [44100, 48000].includes(f.sampleRate) && f.channels >= 1, f.file);
      assert.deepEqual(f.ledger, { provenance: LEDGER_PROVENANCE, licenceStatus: LEDGER_LICENCE_STATUS });
    }
    assert.equal(LEDGER_PROVENANCE, "owner-provided (2026-10-10)");
    assert.equal(LEDGER_LICENCE_STATUS, "unverified: owner to document source per file group");
    assert.ok(!JSON.stringify(m).match(/original(ity)?\b(?! to Nxeon)/i) || /NOT legal advice/.test(m.source.licenceDocument.nxeonReading));
    assert.match(m.source.licenceDocument.summary.join(" "), /distribute/);
  });
  it("no audio file is tracked by git", () => {
    const tracked = execFileSync("git", ["-C", ROOT, "ls-files"], { encoding: "utf8" }).split("\n");
    assert.deepEqual(tracked.filter((p) => /\.(mp3|ogg|wav|flac|m4a|aac|opus)$/i.test(p)), []);
  });
  it("search: text, tags, group, duration, limit; stable order", () => {
    const s = searchLibrary({ text: "scream" });
    assert.ok(s.total >= 7 && s.items.every((x) => x.tags.includes("scream") || stemOf(x.file).toLowerCase().includes("scream")));
    const g = searchLibrary({ group: "gunshot", maxDuration: 2 });
    assert.ok(g.total > 0 && g.items.every((x) => x.group === "gunshot" && x.duration <= 2));
    assert.ok(searchLibrary({ tags: ["door", "squeak"] }).items.every((x) => x.tags.includes("squeak")));
    assert.equal(searchLibrary({ text: "zzqqxx" }).total, 0);
    assert.equal(searchLibrary({ limit: 5 }).items.length, 5);
    assert.deepEqual(searchLibrary({ text: "whoosh" }).items.map((x) => x.id), searchLibrary({ text: "whoosh" }).items.map((x) => x.id));
  });
  it("the compact catalog has every id and no file names or audio", () => {
    const t = libraryCatalogText();
    const lines = t.split("\n").filter((l) => l && !l.startsWith("#"));
    assert.equal(lines.length, 514);
    for (const f of files) assert.ok(t.includes(`${f.id} ${f.duration.toFixed(2)}s`), f.id);
    assert.ok(!/\.mp3/i.test(t));
    assert.ok(Buffer.byteLength(t) < 32 * 1024, "small enough for the model's context");
  });
});

describe("generated files are current (runner bundle, service validator, catalogs)", () => {
  it("matches a fresh esbuild of the sources", async () => {
    const { soundArtifacts } = await import("../scripts/cyrus/build-sound-artifacts");
    for (const [rel, text] of Object.entries(await soundArtifacts())) assert.equal(fs.readFileSync(path.join(ROOT, rel), "utf8"), text, `${rel} is stale: npx tsx scripts/cyrus/build-sound-artifacts.ts`);
  });
});

describe("SoundSpec v1 validator: TS == JS on the shared fixtures", () => {
  it("valid fixtures pass, invalid ones fail, and both sides agree exactly", () => {
    let invalid = 0;
    for (const c of FIX.cases) {
      const ts = checkSoundSpec(c.spec, ctxOf(c.ctx));
      const js = SSJS.checkSoundSpec(c.spec, ctxOf(c.ctx));
      assert.deepEqual(js, ts, c.name);
      assert.equal(ts.ok, c.valid, `${c.name}: ${JSON.stringify(ts).slice(0, 200)}`);
      if (!ts.ok) invalid++;
    }
    assert.equal(invalid, 37);
  });
  it("normalises defaults and names the problem plainly", () => {
    const r = checkSoundSpec(EXAMPLE, { catalog: null, library: false });
    assert.ok(r.ok);
    if (r.ok) {
      assert.equal(r.spec.events[0].category, "hostile");
      assert.deepEqual(r.spec.events[0].variants[0].layers[0], { source: "synth:wail", start: 0, gain: 0, pitch: 0, trimStart: 0, length: 1.4, fadeIn: 0, fadeOut: 0, seed: 11, params: { breath: 0.4, end: 300, start: 520 } });
    }
    const byName = (n: string) => checkSoundSpec(FIX.cases.find((c) => c.name === n)!.spec, ctxOf(FIX.cases.find((c) => c.name === n)!.ctx));
    assert.match((byName("missing subtitle") as { error: string }).error, /subtitle is required/);
    assert.match((byName("library raw copy") as { error: string }).error, /may not ship unchanged/);
    assert.match((byName("library when off") as { error: string }).error, /not available for this build/);
    assert.match((byName("too long for role") as { error: string }).error, /at most 1.5 s/);
  });
});

// Golden PCM hashes (sha256 of the 16-bit PCM). A change here means every rendered sound changes: bump RENDER_VERSION.
const GOLDEN: Record<string, string> = {
  growl: "", wail: "", whoosh: "", impact: "", gunshot: "", click: "", confirm: "", magic: "",
  example_hurt_1: "", example_death_1: "",
};
const lengths: Record<string, number> = { growl: 0.9, wail: 1.2, whoosh: 0.5, impact: 0.4, gunshot: 0.6, click: 0.04, confirm: 0.3, magic: 1 };

describe("DSP + synth presets (deterministic)", () => {
  it("every preset renders the golden PCM, twice the same", () => {
    const got: Record<string, string> = {};
    for (const p of SYNTH_PRESETS) {
      const a = synth(p, lengths[p], 1), b = synth(p, lengths[p], 1);
      assert.equal(pcmSha256(a), pcmSha256(b), p);
      assert.equal(a.length, Math.round(lengths[p] * SAMPLE_RATE));
      assert.ok(Math.max(...Array.from(a, Math.abs)) <= 0.9 + 1e-9);
      got[p] = pcmSha256(a);
      assert.notEqual(pcmSha256(synth(p, lengths[p], 2)), got[p], `${p}: another seed is another take`);
    }
    const r = checkSoundSpec(EXAMPLE, { catalog: null, library: false });
    assert.ok(r.ok);
    const ev = renderSpec((r as { spec: SoundSpec }).spec, () => { throw new Error("no library"); });
    got.example_hurt_1 = pcmSha256(ev[1].variants[0].pcm);
    got.example_death_1 = pcmSha256(ev[2].variants[0].pcm);
    for (const [k, v] of Object.entries(got)) assert.equal(v, GOLDEN[k], `golden ${k}: ${JSON.stringify(got)}`);
  });
  it("chain pieces behave: repitch halves an octave up, mix offsets, fades, trim, echo/reverb tails, limiter ceiling", () => {
    const x = synth("whoosh", 0.5, 3);
    assert.equal(repitch(x, 12).length, Math.floor((x.length - 1) / 2));
    assert.equal(mixAt(new Float64Array(10), new Float64Array(10).fill(1), 1 / SAMPLE_RATE * 5).length, 15);
    const f = fade(new Float64Array(1000).fill(1), 5, 5);
    assert.equal(f[0], 0); assert.ok(f[500] === 1);
    const pad = new Float64Array(44100); pad.set(x, 20000);
    assert.ok(trimSilence(pad).length < x.length + 1500);
    assert.ok(echo(x, 100, 0.5, 0.5).length > x.length && reverb(x, 0.3).length > x.length);
    const loud = new Float64Array(4410).map((_, i) => 1.8 * Math.sin(i / 7));
    const lim = limit(loud, -1.5);
    assert.ok(Math.max(...Array.from(lim, Math.abs)) <= dbToLin(-1.5) + 1e-9);
    assert.equal(toS16(new Float64Array([1, -1, 0.5])).readInt16LE(0), 32767);
    assert.equal(wav(x).subarray(0, 4).toString(), "RIFF");
    assert.ok(biquad(x, "lowpass", 500).length === x.length);
  });
  it("a variant renders to the role's loudness and below the ceiling", () => {
    const v = (checkSoundSpec(EXAMPLE, { catalog: null, library: false }) as { spec: SoundSpec }).spec.events[2].variants[0];
    const r = renderVariant(v, "death", () => new Float64Array(0));
    const m = measure(r.pcm);
    assert.ok(Math.abs(m.lufs - -12) < 1.5 || r.peakLimited, JSON.stringify(m));
    assert.ok(m.samplePeakDb <= -1.49, JSON.stringify(m));
  });
});

describe("measurement + quality bar sq-1", () => {
  const sine = (f: number, amp: number, s: number, ph = 0) => new Float64Array(Math.round(s * SAMPLE_RATE)).map((_, i) => amp * Math.sin((2 * Math.PI * f * i) / SAMPLE_RATE + ph));
  it("loudness of a 1 kHz sine (BS.1770: full-scale sine = -3.01 LUFS)", () => {
    assert.ok(Math.abs(loudness(sine(1000, 1, 2)) - -3.01) < 0.3, String(loudness(sine(1000, 1, 2))));
    assert.ok(Math.abs(loudness(sine(1000, 0.1, 2)) - -23.01) < 0.3);
    assert.ok(Math.abs(loudness(sine(1000, 0.1, 0.2)) - -23.01) < 0.5, "short clip: one ungated block");
    assert.equal(loudness(new Float64Array(44100)), -999);
  });
  it("true peak sees the inter-sample peak a sample peak misses", () => {
    const x = new Float64Array(4000).map((_, i) => 0.5 * Math.sin((Math.PI / 2) * i + Math.PI / 4)); // fs/4, samples at +-0.354
    const m = measure(x);
    assert.ok(Math.abs(m.samplePeakDb - -9.03) < 0.1);
    assert.ok(truePeakDb(x) > -6.6 && truePeakDb(x) < -5.9, String(truePeakDb(x)));
  });
  it("silence ratio and DC offset", () => {
    const x = new Float64Array(44100); x.set(sine(440, 0.5, 0.25));
    assert.ok(Math.abs(measure(x).silenceRatio - 0.75) < 0.02);
    assert.ok(Math.abs(measure(new Float64Array(4410).fill(0.02)).dcOffset - 0.02) < 1e-6);
  });
  it("verdicts: pass in band, fail on stereo / clipping / too long, warn just out of band", () => {
    const ok = { durationS: 0.5, samplePeakDb: -3, truePeakDb: -2.5, lufs: -14, silenceRatio: 0.1, dcOffset: 0 };
    const enc = { codec: "vorbis", channels: 1, sampleRate: 44100 };
    assert.equal(soundQuality(ok, enc, "hurt").verdict, "pass");
    assert.equal(soundQuality(ok, { ...enc, channels: 2 }, "hurt").verdict, "fail");
    assert.equal(soundQuality({ ...ok, truePeakDb: 0.2 }, enc, "hurt").verdict, "fail");
    assert.equal(soundQuality({ ...ok, durationS: 2 }, enc, "hurt").verdict, "fail");
    assert.equal(soundQuality({ ...ok, lufs: -20 }, enc, "hurt").verdict, "warn");
    assert.equal(soundQuality({ ...ok, lufs: -40 }, enc, "hurt").verdict, "fail");
    assert.equal(soundQuality({ ...ok, lufs: -21 }, enc, "step").verdict, "pass");
    assert.equal(soundQuality({ ...ok, dcOffset: 0.05 }, enc, "hurt").verdict, "fail");
    assert.equal(soundQuality({ ...ok, silenceRatio: 0.7 }, enc, "hurt").verdict, "fail");
  });
});

// ---- a FAKE render host: the pure render in-process, "Ogg" = OggS + the 16-bit PCM (tests only; production renders on node-2)
function fakeOgg(pcm: Float64Array) { return Buffer.concat([Buffer.from("OggS"), toS16(pcm)]); }
function fakeHost(opts: { tamper?: boolean; fail?: boolean; stereo?: boolean } = {}): RenderHost & { jobs: RenderJob[] } {
  const jobs: RenderJob[] = [];
  return {
    id: "fake", jobs,
    async render(job) {
      jobs.push(job);
      if (opts.fail) return { ok: false, code: "busy", error: "busy" };
      const res: RenderResult = { ok: true, tool: { runner: "fake", render: "sr-1", quality: "sq-1", ffmpeg: "none" }, errors: [], sets: [] };
      for (const s of job.sets) {
        const c = checkSoundSpec(s.spec, { catalog: Object.fromEntries(job.library.map((l) => [l.id, l.duration])), library: true });
        if (!c.ok) { res.errors.push({ set: s.name, error: c.error }); continue; }
        res.sets.push({ name: s.name, events: c.spec.events.map((e) => ({ event: e.event, files: e.variants.map((v, i) => {
          const r = renderVariant(v, e.role, () => synth("impact", 0.3, 9)); // library stand-in
          const ogg = fakeOgg(r.pcm); const m = measure(r.pcm);
          const encd = { codec: "vorbis", channels: opts.stereo ? 2 : 1, sampleRate: 44100 };
          return { index: i + 1, weight: v.weight, ogg: ogg.toString("base64"), oggSha256: opts.tamper ? "0".repeat(64) : createHash("sha256").update(ogg).digest("hex"), pcmSha256: pcmSha256(r.pcm), bytes: ogg.length, encoded: { ...encd, durationS: m.durationS }, measure: m, quality: soundQuality(m, encd, e.role), render: { gainDb: r.gainDb, peakLimited: r.peakLimited, truncated: r.truncated, ceilingDb: -1.5, passes: 1 } };
        }) })) });
      }
      return res;
    },
  };
}
function memDeps(over: Partial<AssetSyncDeps> = {}) {
  const revs: { id: string; modBuildId: string | null; manifest: unknown }[] = [];
  const assets: { kind: string; assetKey: string; sha256: string; provenance: Record<string, unknown> }[] = [];
  const deps: AssetSyncDeps = {
    selectStore: () => ({ ok: false, reason: "off" } as never),
    projectForRootBuild: async () => ({ id: "cp1", namespace: NS, userId: "u1" }),
    createProject: async () => { throw new Error("unexpected"); },
    findRevisionForBuild: async (_p, m) => revs.find((r) => r.modBuildId === m) ?? null,
    headRevisionId: async () => revs.at(-1)?.id ?? null,
    addRevision: async (_p, i) => { const r = { id: `rev${revs.length + 1}`, modBuildId: i.modBuildId ?? null, manifest: i.manifest }; revs.push(r); return r; },
    recordAsset: async (_p, a) => { if (!assets.some((x) => x.kind === a.kind && x.assetKey === a.assetKey && x.sha256 === a.sha256)) assets.push(a as never); return null; },
    ...over,
  };
  return { deps, revs, assets };
}
const lib = librarySounds().find((f) => f.file === "Scream 2.MP3")!;
const LIBSPEC = { version: 1, name: "screamer", events: [{ event: "hurt", role: "hurt", subtitle: "Screamer yelps", variants: [{ layers: [{ source: `lib:${lib.id}`, pitch: 3, length: 0.5 }] }] }] };
const svcSound = (spec: { name: string }) => ({ key: spec.name, path: `assets/sounds/${spec.name}.json`, sha256: "", spec, quality: null });
const AR = (sounds: unknown[], textures: unknown[] = []): SvcAssetResult => ({ namespace: NS, promptVersion: "mb-assets-2026-10-10.2", qualityVersion: "tq-1", kept: false, textures: textures as never, sounds: sounds as never, downgraded: [], warnings: [] });
const BUILD = { id: "mbS1", userId: "u1", rootBuildId: null, mcVersion: "1.21.11", pluginName: "Banshee", jarName: "Banshee-1.0.0.jar", jarSha256: "a".repeat(64) };

