describe("sound library manifest (metadata only)", () => {
  const m = soundManifest();
  const files = librarySounds();
  it("covers all 514 files with unique, content-bound ids", () => {
    assert.equal(files.length, 514);
    assert.equal(m.source.fileCount, 514);
    assert.equal(new Set(files.map((f) => f.id)).size, 514, "ids unique");
    assert.equal(new Set(files.map((f) => f.sha256)).size, 514, "no duplicate audio");
    for (const f of files) {
      assert.equal(f.id, soundIdFor(f.file, f.sha256), f.file);
      assert.match(f.id, /^[a-z][a-z0-9_]{1,52}$/);
      assert.match(f.sha256, /^[0-9a-f]{64}$/);
    }
  });
  it("tags every file from its name: category, a keyword-matched group, at least two tags", () => {
    for (const f of files) {
      const t = tagsFromFilename(f.file);
      assert.deepEqual({ category: f.category, group: f.group, tags: f.tags }, t, f.file);
      assert.ok(groupFor(nameWords(f.file)), `no group keyword in "${f.file}"`);
      assert.ok(f.tags.length >= 2 && f.tags.includes(f.group), f.file);
      assert.ok(f.category && f.category !== "Misc", f.file);
    }
    const cats = new Set(files.map((f) => f.category));
    for (const c of ["Whoosh", "Hit", "Explosion", "Door", "Alert", "Animals", "Scream", "Gasp", "Water", "Gunshot"]) assert.ok(cats.has(c), `category ${c}`);
  });
  it("records audio facts and a ledger row per file, never asserting originality", () => {
    for (const f of files) {
      assert.ok(f.duration > 0 && f.duration < 120 && [44100, 48000].includes(f.sampleRate) && f.channels >= 1, f.file);
      assert.deepEqual(f.ledger, { provenance: LEDGER_PROVENANCE, licenceStatus: LEDGER_LICENCE_STATUS });
    }
    assert.equal(LEDGER_PROVENANCE, "owner-provided (2026-10-10)");
    assert.equal(LEDGER_LICENCE_STATUS, "unverified: owner to document source per file group");
    assert.ok(!JSON.stringify(m).match(/original(ity)?\b(?! to Nxeon)/i) || /NOT legal advice/.test(m.source.licenceDocument.nxeonReading));
    assert.match(m.source.licenceDocument.summary.join(" "), /distribute/);
  });
  it("no audio file is tracked by git", () => {
    const tracked = execFileSync("git", ["-C", ROOT, "ls-files"], { encoding: "utf8" }).split("\n");
    assert.deepEqual(tracked.filter((p) => /\.(mp3|ogg|wav|flac|m4a|aac|opus)$/i.test(p)), []);
  });
  it("search: text, tags, group, duration, limit; stable order", () => {
    const s = searchLibrary({ text: "scream" });
    assert.ok(s.total >= 7 && s.items.every((x) => x.tags.includes("scream") || stemOf(x.file).toLowerCase().includes("scream")));
    const g = searchLibrary({ group: "gunshot", maxDuration: 2 });
    assert.ok(g.total > 0 && g.items.every((x) => x.group === "gunshot" && x.duration <= 2));
    assert.ok(searchLibrary({ tags: ["door", "squeak"] }).items.every((x) => x.tags.includes("squeak")));
    assert.equal(searchLibrary({ text: "zzqqxx" }).total, 0);
    assert.equal(searchLibrary({ limit: 5 }).items.length, 5);
    assert.deepEqual(searchLibrary({ text: "whoosh" }).items.map((x) => x.id), searchLibrary({ text: "whoosh" }).items.map((x) => x.id));
  });
  it("the compact catalog has every id and no file names or audio", () => {
    const t = libraryCatalogText();
    const lines = t.split("\n").filter((l) => l && !l.startsWith("#"));
    assert.equal(lines.length, 514);
    for (const f of files) assert.ok(t.includes(`${f.id} ${f.duration.toFixed(2)}s`), f.id);
    assert.ok(!/\.mp3/i.test(t));
    assert.ok(Buffer.byteLength(t) < 32 * 1024, "small enough for the model's context");
  });
});

