    const again = buildPack({ namespace: NS, description: "x", mcVersion: "1.21.11", textures: [ruby], sounds: [{ set: "banshee", event: "hurt", subtitle: "Banshee shrieks", files: [{ index: 1, weight: 3, data: ogg(9) }, { index: 2, weight: 1, data: ogg(10) }] }] });
    assert.ok(again.ok && again.pack.sha1 === b.pack.sha1, "deterministic regardless of input order");
