  it("sound-only packs work without item models (older versions too); bad input refused", () => {
    const s = buildPack({ namespace: NS, description: "x", mcVersion: "1.21.1", textures: [], sounds: [{ set: "a1", event: "b", subtitle: "Abc", files: [{ index: 1, weight: 1, data: ogg(3) }] }] });
    assert.ok(s.ok, JSON.stringify(s));
    assert.equal(buildPack({ namespace: NS, description: "x", mcVersion: "1.21.11", textures: [] }).ok, false);
    assert.equal(buildPack({ namespace: NS, description: "x", mcVersion: "1.21.11", textures: [], sounds: [{ set: "a1", event: "b", subtitle: "Abc", files: [{ index: 1, weight: 1, data: Buffer.from("RIFF....") }] }] }).ok, false);
    const dup = { set: "a1", event: "b", subtitle: "Abc", files: [{ index: 1, weight: 1, data: ogg(3) }] };
    assert.equal(buildPack({ namespace: NS, description: "x", mcVersion: "1.21.11", textures: [], sounds: [dup, dup] }).ok, false);
  });
});

