describe("render-host transport (fake ssh Remote)", () => {
  it("places the content-addressed runner once, runs it under flock/timeout/nice, parses the result", async () => {
    const cmds: string[] = [];
    const remote = { exec: async (c: string) => { cmds.push(c); return c.includes("flock") ? { code: 0, stdout: JSON.stringify({ ok: true, tool: {}, sets: [], errors: [] }), stderr: "" } : { code: 0, stdout: "", stderr: "" }; } };
    const h = sshRenderHost({ remote, bundle: Buffer.from("console.log(1)") });
    const r = await h.render({ v: 1, library: [], sets: [], vorbisQuality: 4 });
    assert.equal(r.ok, true);
    assert.match(cmds[0], /test -f '\/tank\/nxeon-build\/tmp\/sound-render\/runner-[0-9a-f]{16}\.cjs' \|\|/);
    assert.match(cmds[1], /flock -E 75 -w 90 .* timeout -k 5 120 nice -n 10 ionice -c2 -n7 node --max-old-space-size=768 'runner-[0-9a-f]{16}\.cjs' --ffmpeg '\/tank\/nxeon-build\/tmp\/ffmpeg\/current\/bin' --library '\/tank\/nxeon-build\/tmp\/sound-library\/files'/);
    const busy = sshRenderHost({ remote: { exec: async (c: string) => ({ code: c.includes("flock") ? 75 : 0, stdout: "", stderr: "" }) }, bundle: Buffer.from("x") });
    assert.deepEqual(await busy.render({ v: 1, library: [], sets: [], vorbisQuality: 4 }), { ok: false, code: "busy", error: "the render host is busy" });
    assert.throws(() => sshRenderHost({ remote, root: "/tmp/../etc" }));
  });
  it("is off unless CYRUS_SOUND_RENDER=ssh", () => {
    assert.equal(selectRenderHost({}).ok, false);
