    assert.equal(selectRenderHost({ CYRUS_SOUND_RENDER: "ssh" }).ok, true);
  });
});

describe("sound gate across plans (only creating/editing is gated)", () => {
  it("pipeline flag is on; Saka and the top plan may create sounds; free/Katara/unknown may not", () => {
    assert.deepEqual(ASSET_PIPELINE_READY, { texture: true, sound: true });
    const want: Record<string, boolean> = { free: false, katara: false, saka: true, all: true, yakko: true, nonsense: false, "": false };
    for (const [plan, ok] of Object.entries(want)) {
      for (const change of [false, true]) {
        const p = planBuildAssets({ plan, requested: ["sound"], mcVersion: "1.21.11", change });
        assert.equal(p.allowed.sound, ok, `${plan} ${change ? "edit" : "create"}`);
        if (!ok) assert.equal(p.notices.length, 1);
      }
    }
    assert.equal(planBuildAssets({ plan: "saka", requested: ["sound"], mcVersion: "1.21.1" }).allowed.sound, true, "sounds need no item models");
    assert.match(planBuildAssets({ plan: "katara", requested: ["sound"], mcVersion: "1.21.11", change: true, existing: ["sound"] }).notices[0], /existing custom sounds are kept exactly as they are/);
