});

describe("service prompt: SOUND_SECTION only when sounds are allowed", () => {
  it("absent without sound, two cached variants with it, namespace in the user turn", () => {
    const plain = P.systemPrompt("1.21.11");
    assert.equal(P.systemPrompt("1.21.11", { textures: false, sound: false }), plain);
    assert.ok(!/CUSTOM SOUNDS/.test(plain));
    const synthOnly = P.systemPrompt("1.21.11", { sound: true });
