});

describe("NxLabs page lines for sounds", () => {
  const a = (o: Partial<MbAssets>): MbAssets => ({ status: "ready", namespace: NS, projectId: "p", revisionId: "r", textures: [], dropped: [], pack: null, loader: null, notices: [], ...o });
  const row = { set: "banshee", event: "hurt", key: `${NS}:banshee.hurt`, subtitle: "Banshee shrieks", role: "hurt", category: "hostile", variants: 2, quality: "pass" as const, specSha256: "x" };
