const fresh = { userId: "u1", rootBuildId: "mb1", change: false, mcVersion: "1.21.11" };

describe("asset gate wiring in the build request (all plans x requested / not)", () => {
  const PLANS: [string, string | Error | null][] = [["free", "free"], ["katara", "katara"], ["saka", "saka"], ["all", "all"], ["yakko (alias of all)", "yakko"], ["unknown string", "platinum"], ["null", null], ["lookup throws", new Error("db")]];
  const REQUESTS: [string, { explicit?: unknown; text: string }][] = [
    ["nothing", { text: "A /spawn command that teleports players to spawn" }],
    ["texture (explicit list)", { explicit: ["texture"], text: "A ruby sword that sets enemies on fire" }],
    ["texture (explicit object)", { explicit: { texture: true }, text: "A ruby sword" }],
    ["texture (words)", { text: "A ruby sword with a custom texture" }],
    ["sound (words)", { text: "A boss that roars with custom sounds" }],
    ["texture + sound", { explicit: ["texture", "sound"], text: "A banshee" }],
  ];
  for (const [pl, tier] of PLANS) for (const [rq, req] of REQUESTS) {
    it(`${pl} x ${rq}`, async () => {
      const d = deps(tier);
      const r = await resolveBuildAssets({ ...fresh, ...req }, d);
      const kinds = requestedAssetKinds({ explicit: req.explicit, text: req.text });
      if (!kinds.length) {
        assert.deepEqual(r, { plan: null, service: null, meta: null });
        assert.deepEqual(d.calls, { tier: 0, find: 0, create: 0 }, "nothing requested: no lookups, no project");
        return;
      }
      assert.equal(d.calls.tier, 1);
      const top = tier === "all" || tier === "yakko";
      const wantTexture = top && kinds.includes("texture");
      assert.equal(r.service?.texture ?? false, wantTexture);
      assert.equal(r.service?.sound ?? false, false, "sound pipeline is not built yet: never sent");
      if (wantTexture) {
        assert.deepEqual(r.service, { texture: true, sound: false, namespace: NS });
        assert.equal(d.calls.create, 1);
        assert.equal(r.meta?.namespace, NS);
      } else {
        assert.equal(r.service, null, "refused: the service request stays byte-identical (no assets field)");
        assert.equal(d.calls.create, 0, "no project for a refused request");
      }
      // every refused kind has exactly one customer-visible reason
      const refused = kinds.filter((k) => !(k === "texture" && wantTexture));
      assert.equal(r.meta!.notices.length, refused.length, JSON.stringify(r.meta));
      for (const n of r.meta!.notices) assert.match(n, /needs the|couldn't confirm|not built into Cyrus yet/);
      if (kinds.includes("sound") && (tier === "saka" || top)) assert.ok(r.meta!.notices.some((n) => /Custom sounds are not built into Cyrus yet/.test(n)));
      if (kinds.includes("texture") && !top) assert.ok(r.meta!.notices.some((n) => /(All models plan|couldn't confirm your Cyrus plan)/.test(n)));
    });
  }

