// Measured audio descriptors for the sound library (Cyrus R1 sound slice). Pure DSP on mono PCM; run ON node-2 over
// the library by scripts/cyrus/sound-descriptors.ts (the audio never leaves the render host), the raw numbers are
// committed in the manifest and turned into classes by the thresholds in taxonomy.json (classify.ts).
import { linToDb, SAMPLE_RATE, type Mono } from "./dsp";

export type RawDescriptors = {
  /** mean spectral centroid (Hz) over the louder frames */
  centroidHz: number;
  /** ms from the start to the loudest 10 ms window */
  attackMs: number;
  /** share of the energy in the first 25 % of the sound (high = a sharp transient that dies away) */
  frontEnergy: number;
  /** RMS (dBFS) of the first / last 50 ms (loop heuristic) */
  startDb: number;
  endDb: number;
  /** crest factor (peak / RMS, dB) */
  crestDb: number;
};

/** In-place iterative radix-2 FFT (re/im of length 2^k). */
function fft(re: Float64Array, im: Float64Array) {
  const n = re.length;
  for (let i = 1, j = 0; i < n; i++) {
    let bit = n >> 1;
    for (; j & bit; bit >>= 1) j ^= bit;
    j ^= bit;
    if (i < j) { [re[i], re[j]] = [re[j], re[i]]; [im[i], im[j]] = [im[j], im[i]]; }
  }
  for (let len = 2; len <= n; len <<= 1) {
    const ang = (-2 * Math.PI) / len, wr = Math.cos(ang), wi = Math.sin(ang);
    for (let i = 0; i < n; i += len) {
      let cr = 1, ci = 0;
      for (let k = 0; k < len / 2; k++) {
        const a = i + k, b = a + len / 2;
        const tr = re[b] * cr - im[b] * ci, ti = re[b] * ci + im[b] * cr;
        re[b] = re[a] - tr; im[b] = im[a] - ti; re[a] += tr; im[a] += ti;
        const nr = cr * wr - ci * wi; ci = cr * wi + ci * wr; cr = nr;
      }
    }
  }
}

const rms = (x: Mono, a: number, b: number) => { let s = 0; const e = Math.min(x.length, b); for (let i = a; i < e; i++) s += x[i] * x[i]; return e > a ? Math.sqrt(s / (e - a)) : 0; };
const r1 = (v: number) => (Number.isFinite(v) ? Math.round(v * 10) / 10 : -999);

export function rawDescriptors(x: Mono, fs = SAMPLE_RATE): RawDescriptors {
  const N = 2048, hop = 2048;
  const frames: { e: number; c: number }[] = [];
  const win = new Float64Array(N).map((_, i) => 0.5 - 0.5 * Math.cos((2 * Math.PI * i) / (N - 1)));
  for (let a = 0; a + N <= x.length && frames.length < 400; a += hop) {
    const re = new Float64Array(N), im = new Float64Array(N);
    for (let i = 0; i < N; i++) re[i] = x[a + i] * win[i];
    fft(re, im);
    let num = 0, den = 0;
    for (let k = 1; k < N / 2; k++) { const m = Math.hypot(re[k], im[k]); num += m * ((k * fs) / N); den += m; }
    frames.push({ e: den, c: den > 0 ? num / den : 0 });
  }
  const maxE = Math.max(0, ...frames.map((f) => f.e));
  const loud = frames.filter((f) => f.e >= maxE * 0.1);
  const centroidHz = loud.length ? loud.reduce((s, f) => s + f.c * f.e, 0) / loud.reduce((s, f) => s + f.e, 0) : 0;
  const w = Math.round(0.01 * fs);
  let best = 0, bestAt = 0;
  for (let a = 0; a < x.length; a += w) { const v = rms(x, a, a + w); if (v > best) { best = v; bestAt = a; } }
  let total = 0, front = 0;
  const q = Math.floor(x.length / 4);
  let peak = 0;
  for (let i = 0; i < x.length; i++) { const e = x[i] * x[i]; total += e; if (i < q) front += e; peak = Math.max(peak, Math.abs(x[i])); }
  const allRms = x.length ? Math.sqrt(total / x.length) : 0;
  const t50 = Math.round(0.05 * fs);
  return {
    centroidHz: Math.round(centroidHz), attackMs: Math.round((bestAt / fs) * 1000), frontEnergy: total > 0 ? Math.round((front / total) * 1000) / 1000 : 0,
    startDb: r1(linToDb(rms(x, 0, t50))), endDb: r1(linToDb(rms(x, Math.max(0, x.length - t50), x.length))), crestDb: r1(linToDb(peak) - linToDb(allRms)),
  };
}

