// Measure the raw audio descriptors (lib/cyrus/sound/descriptors.ts) of every library file. Runs ON node-2 only (the
// audio is there and never leaves): decode with the isolated ffmpeg, measure, write metadata JSON.
//   npx tsx scripts/cyrus/sound-descriptors.ts <scan.json> <out descriptors.json>
//   (env SOUND_LIBRARY_DIR, SOUND_FFMPEG_DIR default to the node-2 paths)
import { readFileSync, writeFileSync } from "node:fs";
import path from "node:path";
import { rawDescriptors } from "../../lib/cyrus/sound/descriptors";
import { decodeFile } from "../../lib/cyrus/sound/runner";
import { SOUND_FFMPEG_DIR, SOUND_LIBRARY_DIR } from "../../lib/cyrus/sound/host";

const [, , scanPath, outPath] = process.argv;
const lib = process.env.SOUND_LIBRARY_DIR || SOUND_LIBRARY_DIR;
const ffDir = process.env.SOUND_FFMPEG_DIR || SOUND_FFMPEG_DIR;
const ff = { ffmpeg: path.join(ffDir, "ffmpeg"), ffprobe: path.join(ffDir, "ffprobe") };
const scan = JSON.parse(readFileSync(scanPath, "utf8")) as { files: { file: string; channels: number }[] };
const out: Record<string, unknown> = {};
for (const f of scan.files) out[f.file] = rawDescriptors(decodeFile(ff, path.join(lib, f.file), f.channels));
writeFileSync(outPath, JSON.stringify(out, null, 0));
console.log(`${Object.keys(out).length} files measured`);

