// Search over the sound library manifest (pure, client-safe; the Sound Studio library browser and the AI helpers use
// it). Free text with synonym expansion (taxonomy.json querySynonyms + synonyms) and ranking
//   exact tag (5, 4 via a synonym) > use case / category (3) > tag prefix (2) > file-name words (1)
// where EVERY query word must match something; facets and filters; pagination; and `similarTo`.
import { categoryLabel, canonicalWords, stemOf, TAXONOMY, type Descriptors } from "./classify";
import { librarySound, librarySounds, type LibrarySound } from "./library";

export type LibraryFilters = {
  category?: string | string[]; useCase?: string | string[]; tags?: string[];
  durationClass?: Descriptors["durationClass"][]; intensity?: Descriptors["intensity"][]; pitchBand?: Descriptors["pitchBand"][]; character?: Descriptors["character"][];
  loopable?: boolean; minDuration?: number; maxDuration?: number;
};
export type LibraryQuery = LibraryFilters & { text?: string; limit?: number; offset?: number };
export type Facets = { category: Record<string, number>; useCase: Record<string, number>; durationClass: Record<string, number>; intensity: Record<string, number>; pitchBand: Record<string, number> };
export type SearchResult = { total: number; items: LibrarySound[]; facets: Facets; expanded: string[][] };

const arr = <T>(v: T | T[] | undefined) => (v == null ? null : Array.isArray(v) ? v : [v]);

/** The terms one query word stands for: itself, its canonical form, and the query synonyms (one level, plus nested aliases). */
export function expandWord(w: string): string[] {
  const out = new Set<string>([w]);
  const canon = TAXONOMY.synonyms[w]; if (canon) out.add(canon);
  for (const x of [w, canon].filter(Boolean) as string[]) for (const s of TAXONOMY.querySynonyms[x] ?? []) { out.add(s); for (const t of TAXONOMY.querySynonyms[s] ?? []) out.add(t); }
  return [...out];
}

function matchesFilters(s: LibrarySound, f: LibraryFilters): boolean {
  const cats = arr(f.category), ucs = arr(f.useCase);
  if (cats && !cats.includes(s.category)) return false;
  if (ucs && !ucs.some((u) => s.useCases.includes(u))) return false;
  if (f.tags && f.tags.some((t) => !s.tags.includes(t.toLowerCase()))) return false;
  if (f.durationClass && !f.durationClass.includes(s.descriptors.durationClass)) return false;
  if (f.intensity && !f.intensity.includes(s.descriptors.intensity)) return false;
  if (f.pitchBand && !f.pitchBand.includes(s.descriptors.pitchBand)) return false;
  if (f.character && !f.character.includes(s.descriptors.character)) return false;
  if (f.loopable != null && s.descriptors.loopable !== f.loopable) return false;
  if (f.minDuration != null && s.duration < f.minDuration) return false;
  if (f.maxDuration != null && s.duration > f.maxDuration) return false;
  return true;
}

function scoreWord(s: LibrarySound, word: string, terms: string[], name: string[]): number {
  let best = 0;
  for (const t of terms) {
    const self = t === word || t === TAXONOMY.synonyms[word];
    if (s.tags.includes(t)) best = Math.max(best, self ? 5 : 4);
    else if (s.useCases.includes(t) || s.category === t || categoryLabel(s.category).toLowerCase() === t) best = Math.max(best, 3);
    else if (t.length >= 3 && s.tags.some((x) => x.startsWith(t))) best = Math.max(best, 2);
    else if (name.some((n) => n.includes(t))) best = Math.max(best, 1);
  }
  return best;
}

export function searchLibrary(q: LibraryQuery, files: readonly LibrarySound[] = librarySounds()): SearchResult {
  const qWords = canonicalWords(q.text ?? "").filter((w) => !TAXONOMY.stopWords.includes(w));
  const expanded = qWords.map(expandWord);
  const scored: { s: LibrarySound; score: number }[] = [];
  for (const s of files) {
    if (!matchesFilters(s, q)) continue;
    const name = canonicalWords(stemOf(s.file));
    let score = 0, miss = false;
    for (const [i, w] of qWords.entries()) { const v = scoreWord(s, w, expanded[i], name); if (!v) { miss = true; break; } score += v; }
    if (!miss) scored.push({ s, score });
  }
  scored.sort((a, b) => b.score - a.score || a.s.duration - b.s.duration || (a.s.id < b.s.id ? -1 : 1));
  const facets: Facets = { category: {}, useCase: {}, durationClass: {}, intensity: {}, pitchBand: {} };
  for (const { s } of scored) {
    facets.category[s.category] = (facets.category[s.category] ?? 0) + 1;
    for (const u of s.useCases) facets.useCase[u] = (facets.useCase[u] ?? 0) + 1;
    facets.durationClass[s.descriptors.durationClass] = (facets.durationClass[s.descriptors.durationClass] ?? 0) + 1;
    facets.intensity[s.descriptors.intensity] = (facets.intensity[s.descriptors.intensity] ?? 0) + 1;
    facets.pitchBand[s.descriptors.pitchBand] = (facets.pitchBand[s.descriptors.pitchBand] ?? 0) + 1;
  }
  const off = Math.max(0, q.offset ?? 0), lim = Math.min(200, Math.max(1, q.limit ?? 50));
  return { total: scored.length, items: scored.slice(off, off + lim).map((x) => x.s), facets, expanded };
}

/** Sounds like this one: same category, shared use cases, close descriptors and duration (most similar first). */
export function similarTo(id: string, limit = 10, files: readonly LibrarySound[] = librarySounds()): LibrarySound[] {
  const me = librarySound(id) ?? files.find((f) => f.id === id);
  if (!me) return [];
  const d = me.descriptors;
  return files.filter((f) => f.id !== me.id).map((f) => {
    let s = 0;
    if (f.category === me.category) s += 4;
    s += 2 * f.useCases.filter((u) => me.useCases.includes(u)).length;
    if (f.descriptors.durationClass === d.durationClass) s += 1;
    if (f.descriptors.pitchBand === d.pitchBand) s += 1;
    if (f.descriptors.intensity === d.intensity) s += 1;
    if (f.descriptors.character === d.character) s += 1;
    s -= Math.min(2, Math.abs(Math.log2((f.duration + 0.05) / (me.duration + 0.05))));
    return { f, s };
  }).filter((x) => x.s >= 4).sort((a, b) => b.s - a.s || (a.f.id < b.f.id ? -1 : 1)).slice(0, limit).map((x) => x.f);
}
