import { describe, it, before, after } from "node:test";
import assert from "node:assert/strict";
import fs from "node:fs";
import os from "node:os";
import path from "node:path";

/**
 * Cyrus R1 asset slice against a THROWAWAY Postgres: the build-request gate with the REAL plan lookup (CyrusPlan +
 * admin override through tokens/access tierOf) and the real project store; the portal sync with the real engine-core
 * store and the local pack store (re-sync and concurrent syncs record exactly one revision); pack delivery with the
 * real managed-plugin service (memory installer, local fake guest). No server, no model, no network.
 *
 * Opt-in and fail-closed: runs only when CYRUS_ASSETS_DB_TEST=1 and DATABASE_URL is a node-2 agent database.
 *   devhost db push && devhost run --lock -- env CYRUS_ASSETS_DB_TEST=1 npx tsx --test test/cyrus-assets-db.test.ts
 */
const url = process.env.DATABASE_URL ?? "";
const safe = process.env.CYRUS_ASSETS_DB_TEST === "1" && /^postgres(ql)?:\/\/[^@]*@127\.0\.0\.1:5433\/wt_[a-z0-9_]+(\?.*)?$/.test(url);
const skip = safe ? false : "set CYRUS_ASSETS_DB_TEST=1 with a node-2 throwaway DATABASE_URL to run";

type Db = typeof import("../lib/db.ts")["db"];
let db: Db;
const uniq = `${Date.now().toString(36)}${Math.random().toString(36).slice(2, 6)}`;
const uid = (n: string) => `cyas-${uniq}-${n}`;
const tmp = fs.mkdtempSync(path.join(os.tmpdir(), "cyrus-assets-db-"));
const env = { CYRUS_PACK_STORE: "local", CYRUS_PACK_LOCAL_DIR: path.join(tmp, "packs"), CYRUS_PACK_PUBLIC_BASE: "https://packs.example.invalid" };
const fixture = (n: string) => JSON.parse(fs.readFileSync(path.join(__dirname, "fixtures/cyrus-textures", `${n}.json`), "utf8"));

before(async () => {
  if (!safe) return;
  db = (await import("../lib/db.ts")).db;
  const end = new Date(Date.now() + 20 * 86400_000);
  for (const t of ["katara", "saka", "all"]) {
    await db.cyrusPlan.create({ data: { userId: uid(t), stripeCustomerId: `cus_${uid(t)}`, stripeSubscriptionId: `sub_${uid(t)}`, tier: t, priceTier: t, status: "active", currentPeriodEnd: end } });
  }
  await db.cyrusPlan.create({ data: { userId: uid("lapsed"), stripeCustomerId: `cus_${uid("lapsed")}`, stripeSubscriptionId: `sub_${uid("lapsed")}`, tier: "all", priceTier: "all", status: "canceled", currentPeriodEnd: new Date(Date.now() - 86400_000) } });
  await db.cyrusTokenAccount.create({ data: { userId: uid("comp"), tierOverride: "all" } });
});
after(async () => {
  if (!safe) return;
  const projects = await db.cyrusProject.findMany({ where: { userId: { startsWith: `cyas-${uniq}-` } }, select: { id: true } });
  const ids = projects.map((p) => p.id);
  await db.cyrusProjectAsset.deleteMany({ where: { projectId: { in: ids } } });
  await db.cyrusRevision.deleteMany({ where: { projectId: { in: ids } } });
  await db.cyrusProject.deleteMany({ where: { id: { in: ids } } });
  await db.cyrusServerManagedPlugin.deleteMany({ where: { serverId: { startsWith: `cyas-${uniq}-` } } });
  await db.cyrusPlan.deleteMany({ where: { userId: { startsWith: `cyas-${uniq}-` } } });
  await db.cyrusTokenAccount.deleteMany({ where: { userId: { startsWith: `cyas-${uniq}-` } } });
  await db.$disconnect();
  fs.rmSync(tmp, { recursive: true, force: true });
});

describe("Cyrus asset slice (throwaway DB)", { skip }, () => {
  it("build request gate with the real plan lookup: only the top plan (or an admin comp) gets textures, with a reserved namespace", async () => {
    const { resolveBuildAssets } = await import("../lib/cyrus/assets/request.ts");
    const { assetRequestDeps } = await import("../lib/modbuilder/create.ts");
    const want: Record<string, boolean> = { free: false, katara: false, saka: false, all: true, lapsed: false, comp: true };
    for (const [who, ok] of Object.entries(want)) {
      const root = `mb${uniq}${who}`.slice(0, 40);
      const r = await resolveBuildAssets({ userId: uid(who), rootBuildId: root, change: false, explicit: ["texture"], text: "A ruby sword", mcVersion: "1.21.11" }, assetRequestDeps);
      assert.equal(!!r.service?.texture, ok, `${who}: ${JSON.stringify(r.meta)}`);

      assert.equal(!!r.service?.texture, ok, `${who}: ${JSON.stringify(r.meta)}`);
      const p = await db.cyrusProject.findUnique({ where: { rootBuildId: root } });
      if (ok) {
        assert.ok(p && /^nx_[a-z0-9]{8}$/.test(p.namespace));
        assert.equal(r.service!.namespace, p!.namespace);
        // the next version of the same chain reuses the project
        const again = await resolveBuildAssets({ userId: uid(who), rootBuildId: root, change: true, explicit: ["texture"], text: "make it blue", mcVersion: "1.21.11" }, assetRequestDeps);
        assert.equal(again.service!.namespace, p!.namespace);
        assert.equal(await db.cyrusProject.count({ where: { rootBuildId: root } }), 1);
      } else {
        assert.equal(p, null, `${who}: no project for a refused request`);
        assert.equal(r.service, null);
        assert.equal(r.meta!.notices.length, 1);
      }
    }
    // nothing requested: no project, no lookups that create anything
    const none = await resolveBuildAssets({ userId: uid("all"), rootBuildId: `mb${uniq}none`, change: false, text: "A /spawn command", mcVersion: "1.21.11" }, assetRequestDeps);
    assert.deepEqual(none, { plan: null, service: null, meta: null });
  });

  it("sync: pack hosted, one revision + asset rows; re-sync and concurrent syncs never duplicate", async () => {
    const { createProject } = await import("../lib/cyrus/engine-core/store.ts");
    const { syncBuildAssets } = await import("../lib/cyrus/assets/sync.ts");
    const { defaultAssetSyncDeps } = await import("../lib/cyrus/assets/sync-deps.ts");
    // eslint-disable-next-line @typescript-eslint/no-require-imports
    const TXJS = require("../services/modbuilder/textures.js");
    const root = `mb${uniq}sync`;
    const p = await createProject({ userId: uid("all"), game: "minecraft", rootBuildId: root });
    const specs = [fixture("ruby_sword"), fixture("flat_square")];
    const ar = { namespace: p.namespace, promptVersion: "mb-assets-2026-10-10.1", qualityVersion: "tq-1", kept: false, downgraded: [], warnings: [], textures: specs.map((s) => ({ name: s.name, path: `assets/textures/${s.name}.json`, sha256: "", spec: TXJS.checkSpec(s).spec, quality: null })) };
    const build = { id: root, userId: uid("all"), rootBuildId: root, mcVersion: "1.21.11", pluginName: "Ruby", jarName: "Ruby-1.0.0.jar", jarSha256: "c".repeat(64) };
    const deps = defaultAssetSyncDeps(env);
    const a = (await syncBuildAssets(build, ar, deps))!;
    assert.equal(a.status, "ready", JSON.stringify(a.notices));
    assert.deepEqual(a.textures.map((t) => t.name), ["ruby_sword"], "the failing spec is dropped by the portal too");
    assert.deepEqual(a.dropped.map((d) => d.name), ["flat_square"]);
    assert.ok(fs.existsSync(path.join(env.CYRUS_PACK_LOCAL_DIR, "p", `${a.pack!.sha1}.zip`)));
    const again = await Promise.all([syncBuildAssets(build, ar, deps), syncBuildAssets(build, ar, deps), syncBuildAssets(build, ar, deps)]);
    for (const x of again) assert.equal(x!.revisionId, a.revisionId);
    const revs = await db.cyrusRevision.findMany({ where: { projectId: p.id } });
    assert.equal(revs.length, 1, "exactly one revision for the build");
    assert.equal(revs[0].modBuildId, root);
    assert.equal(revs[0].kind, "generated");
    assert.equal(revs[0].status, "passed");
    assert.deepEqual((revs[0].manifest as { role: string }[]).map((m) => m.role).sort(), ["artifact", "asset", "resourcePack"]);
    const assets = await db.cyrusProjectAsset.findMany({ where: { projectId: p.id } });
    assert.equal(assets.length, 1);
    assert.equal((assets[0].provenance as { quality: { verdict: string } }).quality.verdict, "pass");
    const proj = await db.cyrusProject.findUnique({ where: { id: p.id } });
    assert.equal(proj!.headRevisionId, revs[0].id);
    assert.equal(proj!.lastPassingRevisionId, revs[0].id);

    // a fresh build synced by three callers AT ONCE (route + page loader + worker sweep): still one revision
    const root2 = `mb${uniq}race`;
    const p2 = await createProject({ userId: uid("all"), game: "minecraft", rootBuildId: root2 });
    const ar2 = { ...ar, namespace: p2.namespace };
    const b2 = { ...build, id: root2, rootBuildId: root2 };
    const race = await Promise.all([syncBuildAssets(b2, ar2, deps), syncBuildAssets(b2, ar2, deps), syncBuildAssets(b2, ar2, deps)]);
    assert.equal(new Set(race.map((x) => x!.revisionId)).size, 1);
    assert.equal(await db.cyrusRevision.count({ where: { projectId: p2.id } }), 1);
    assert.equal(await db.cyrusProjectAsset.count({ where: { projectId: p2.id } }), 1);
  });

  it("delivery (flag on, memory installer, fake guest): Pack Loader ensured, packs.json upserted once, removed again", async () => {
    const { createProject } = await import("../lib/cyrus/engine-core/store.ts");
    const { syncBuildAssets } = await import("../lib/cyrus/assets/sync.ts");
    const { defaultAssetSyncDeps } = await import("../lib/cyrus/assets/sync-deps.ts");
    const { deliverBuildPack, removeBuildPack, PACK_LOADER_KEY } = await import("../lib/cyrus/assets/deliver.ts");
    const { memoryInstaller } = await import("../lib/cyrus/managed/installer.ts");
    const { loadCatalog } = await import("../lib/cyrus/managed/catalog.ts");
    const { LocalGuestFs } = await import("../lib/mods/guest-fs.ts");
    const { readLoaderConfig } = await import("../lib/cyrus/packhost/deliver.ts");
    // eslint-disable-next-line @typescript-eslint/no-require-imports
    const TXJS = require("../services/modbuilder/textures.js");
    const root = `mb${uniq}dlv`;
    const p = await createProject({ userId: uid("all"), game: "minecraft", rootBuildId: root });
    const ar = { namespace: p.namespace, promptVersion: null, qualityVersion: "tq-1", kept: false, downgraded: [], warnings: [], textures: [{ name: "ruby_sword", path: "x", sha256: "", spec: TXJS.checkSpec(fixture("ruby_sword")).spec, quality: null }] };
    const a = (await syncBuildAssets({ id: root, userId: uid("all"), rootBuildId: root, mcVersion: "1.21.11", pluginName: "Ruby", jarName: null, jarSha256: null }, ar, defaultAssetSyncDeps(env)))!;
    const guestRoot = path.join(tmp, "guest");
    fs.mkdirSync(path.join(guestRoot, "opt/mc"), { recursive: true });
    fs.writeFileSync(path.join(guestRoot, "opt/mc/server.properties"), "motd=x\n");
    const inst = memoryInstaller();
    const deps = { managed: { db, installer: inst, catalog: loadCatalog() }, fs: new LocalGuestFs(guestRoot), env: { CYRUS_MANAGED_PLUGINS_REAL: "1" } };
    const server = uid("srv");
    const b = { id: root, mcVersion: "1.21.11", result: { assets: a } };
    const d1 = await deliverBuildPack(server, b, deps);
    assert.deepEqual(d1.ok && [d1.action, d1.wrote, d1.loader], ["added", true, "installed"], JSON.stringify(d1));
    const cfg = await readLoaderConfig(deps.fs);
    assert.ok(cfg.ok && cfg.config);
    if (cfg.ok) assert.deepEqual(cfg.config!.packs.map((x) => [x.id, x.url, x.sha1, x.required]), [[a.loader!.id, a.loader!.url, a.pack!.sha1, false]]);
    const d2 = await deliverBuildPack(server, b, deps);
    assert.deepEqual(d2.ok && [d2.action, d2.wrote, d2.loader], ["unchanged", false, "already"]);
    assert.equal(inst.calls.filter((c) => c.op === "install").length, 1);
    const row = await db.cyrusServerManagedPlugin.findUnique({ where: { serverId_key: { serverId: server, key: PACK_LOADER_KEY } } });
    assert.deepEqual(row!.dependents, [`project:${p.id}`]);
    const r = await removeBuildPack(server, { namespace: p.namespace, projectId: p.id }, deps);
    assert.deepEqual(r.ok && [r.action, r.wrote, r.loader], ["removed", true, "removed"]);
    const after = await readLoaderConfig(deps.fs);
    assert.ok(after.ok && after.config && after.config.packs.length === 0);
    const gone = await db.cyrusServerManagedPlugin.findUnique({ where: { serverId_key: { serverId: server, key: PACK_LOADER_KEY } } });
    assert.equal(gone!.refCount, 0);
  });
});
package dev.nxeon.tf.itemmodel;

import org.bukkit.Material;
import org.bukkit.NamespacedKey;
import org.bukkit.command.Command;
import org.bukkit.command.CommandSender;
import org.bukkit.inventory.ItemStack;
import org.bukkit.inventory.meta.ItemMeta;
import org.bukkit.plugin.java.JavaPlugin;

/**
 * Cyrus R1 Test Flight fixture: does exactly what the build prompt tells a generated mod to do for a custom texture,
 * meta.setItemModel(new NamespacedKey(namespace, name)), then reads the key back from the item, so a flight proves the
 * registry-backed key works on the real Paper server (no client involved).
 */
public class ItemModelPlugin extends JavaPlugin {
    @Override
    public boolean onCommand(CommandSender sender, Command command, String label, String[] args) {
        if (args.length != 2) {
            sender.sendMessage("usage: /tfitem <namespace> <name>");
            return true;
        }
        ItemStack stack = new ItemStack(Material.IRON_SWORD);
        ItemMeta meta = stack.getItemMeta();
        meta.setItemModel(new NamespacedKey(args[0], args[1]));
        stack.setItemMeta(meta);
        ItemMeta back = stack.getItemMeta();
        String key = back != null && back.hasItemModel() ? back.getItemModel().toString() : "none";
        sender.sendMessage("itemModel=" + key + " material=" + stack.getType().name());
        return true;
    }
}
