import { tmpdir } from "node:os";
import path from "node:path";
import { runTestFlight, sshRemote, shq, tarball, type RunResult } from "../lib/cyrus/testflight/client";
import { describe } from "../lib/cyrus/testflight/summary";
import type { TestFlightSpec } from "../lib/cyrus/testflight/types";
import { applyPackChange, LOADER_CONFIG_PATH, serializeLoaderConfig } from "../lib/cyrus/packhost/loader-config";
import { LocalDiskStore } from "../lib/cyrus/packhost/local";
import { publishPack } from "../lib/cyrus/packhost/publish";
import { buildPack } from "../lib/cyrus/textures/pack";
import { checkSpec } from "../lib/cyrus/textures/dsl";
import { HEALTH_POTION } from "../lib/cyrus/textures/sample-items";
import { syncBuildAssets, type AssetSyncDeps } from "../lib/cyrus/assets/sync";
import { acceptRendered, checkReturnedSound, packSoundsOf, renderJobFor } from "../lib/cyrus/assets/sounds";
import { sshRenderHost } from "../lib/cyrus/sound/host";
import { searchLibrary } from "../lib/cyrus/sound/library-search";
import type { RenderResult } from "../lib/cyrus/sound/job";

const FX = "/tank/nxeon-build/tmp/testflight/inbox/fx";
const NS = "nx_r1s0und";
const BASE = "https://packs.example.invalid";
const PROBE_DIR = "/tank/nxeon-build/tmp/sound-render/probe";
const FFPROBE = "/tank/nxeon-build/tmp/ffmpeg/current/bin/ffprobe";
const ruby = JSON.parse(readFileSync(path.join(__dirname, "fixtures/cyrus-textures/ruby_sword.json"), "utf8"));
const textures = [ruby, HEALTH_POTION].map((s) => { const c = checkSpec(s); if (!c.ok) throw new Error(c.error); return c.spec; });

const pick = (text: string, filters: Parameters<typeof searchLibrary>[0] = {}) => { const r = searchLibrary({ text, ...filters, limit: 1 }).items[0]; if (!r) throw new Error(`no library sound for ${text}`); return r.id; };
/** The banshee: a reskinned zombie that wails. Library layers are always transformed (pitch/effects), never raw. */
function bansheeSpec() {
  const scream = pick("scream"), gasp = pick("gasp"), growl = pick("monster"), steps = pick("footsteps", { maxDuration: 3 }), whoosh = pick("whoosh", { maxDuration: 1.5 }), hit = pick("impact hit");
  return {
    version: 1, name: "banshee",
    events: [
      { event: "ambient", role: "ambient", subtitle: "Banshee moans", variants: [
        { layers: [{ source: "synth:wail", length: 1.4, seed: 11, params: { start: 520, end: 300, breath: 0.4 } }], processing: { reverb: 0.35 } },
        { layers: [{ source: `lib:${growl}`, pitch: 5, length: 1.2, fadeOut: 200 }, { source: "synth:wail", length: 1.1, seed: 12, gain: -6, params: { start: 600, end: 420 } }], processing: { reverb: 0.3 } } ] },
      { event: "hurt", role: "hurt", subtitle: "Banshee shrieks", variants: [
        { weight: 2, layers: [{ source: `lib:${scream}`, pitch: 4, length: 0.6, fadeOut: 80 }, { source: "synth:wail", length: 0.45, seed: 3, gain: -6, params: { start: 1300, end: 800, harmonics: 0.8 } }] },
        { layers: [{ source: `lib:${gasp}`, pitch: 7, length: 0.5, fadeOut: 60 }], processing: { highpass: 300, reverb: 0.15 } },
        { layers: [{ source: "synth:wail", length: 0.4, seed: 4, pitch: 2, params: { start: 1200, end: 700, harmonics: 0.8 } }, { source: "synth:impact", length: 0.2, gain: -10, params: { thump: 90 } }] } ] },
      { event: "death", role: "death", subtitle: "Banshee fades away", variants: [
        { layers: [{ source: `lib:${scream}`, pitch: -5, length: 1.2, fadeOut: 400 }, { source: "synth:wail", start: 0.2, length: 2.2, seed: 9, gain: -4, params: { start: 900, end: 140, depth: 0.6 } }, { source: `lib:${hit}`, pitch: -7, gain: -8, length: 0.8 }], processing: { reverb: 0.5, lowpass: 7000 } } ] },
      { event: "attack", role: "attack", subtitle: "Banshee lunges", variants: [
        { layers: [{ source: `lib:${whoosh}`, pitch: -3, length: 0.6 }, { source: "synth:growl", start: 0.05, length: 0.5, seed: 5, gain: -3, params: { pitch: 140, rough: 0.8 } }] },
        { layers: [{ source: "synth:whoosh", length: 0.4, seed: 6 }, { source: `lib:${hit}`, start: 0.15, pitch: 3, gain: -4, length: 0.4 }] } ] },
      { event: "step", role: "step", subtitle: "Banshee glides", variants: [
        { layers: [{ source: `lib:${steps}`, pitch: 5, length: 0.25, fadeOut: 40 }], processing: { lowpass: 3000 } },
        { layers: [{ source: "synth:whoosh", length: 0.22, seed: 1, params: { high: 2000 } }] },
        { layers: [{ source: "synth:whoosh", length: 0.2, seed: 2, params: { high: 4000 } }] } ] },
    ],
  };
}

async function renderPart() {
  const spec = bansheeSpec();
  const c = checkReturnedSound({ key: "banshee", spec }, { library: true });
  if (!c.ok) throw new Error(c.reason);
  const host = sshRenderHost();
  const t0 = Date.now();
  const a = await host.render(renderJobFor([c]));
  const ms1 = Date.now() - t0;
  const b = await host.render(renderJobFor([c]));
  if (!a.ok || !b.ok) throw new Error(`render failed: ${JSON.stringify(a.ok ? b : a).slice(0, 400)}`);
  const files = (r: Extract<RenderResult, { ok: true }>) => r.sets.flatMap((s) => s.events.flatMap((e) => e.files.map((f) => ({ name: `${e.event}_${f.index}`, f }))));
  const fa = files(a), fb = files(b);
  const same = fa.length === fb.length && fa.every((x, i) => x.f.oggSha256 === fb[i].f.oggSha256 && x.f.pcmSha256 === fb[i].f.pcmSha256);
  // ffprobe every Ogg ON node-2 (the bytes go back to node-2 into a scratch dir, are probed, then deleted)
  const remote = sshRemote();
  const dir = `${PROBE_DIR}/${Date.now().toString(36)}`;
  const tar = tarball(fa.map((x) => ({ name: `${x.name}.ogg`, data: Buffer.from(x.f.ogg, "base64") })));
  const pr = await remote.exec(`set -e; mkdir -p ${shq(dir)}; cd ${shq(dir)}; tar -xf -; for f in *.ogg; do printf '%s ' "$f"; timeout 20 ${shq(FFPROBE)} -v error -show_entries stream=codec_name,channels,sample_rate:format=duration -of csv=p=0 "$f" | tr '\\n' ' '; echo; done; cd /; rm -rf ${shq(dir)}`, { input: tar, timeoutMs: 120000 });
  const probes = pr.stdout.trim().split("\n").filter(Boolean).map((l) => { const [file, ...rest] = l.trim().split(/\s+/); return { file, ffprobe: rest.join(" ") }; });
  const accepted = acceptRendered([c], a);
  return {
    spec, tool: a.tool, renderMs: ms1, deterministic: same, errors: a.errors, dropped: accepted.dropped,
    files: fa.map((x) => ({ name: x.name, bytes: x.f.bytes, oggSha256: x.f.oggSha256, pcmSha256: x.f.pcmSha256, encoded: x.f.encoded, measure: x.f.measure, quality: x.f.quality.verdict, warn: x.f.quality.checks.filter((k) => k.status !== "pass").map((k) => `${k.id}=${k.value}`), render: x.f.render })),
    probes, probeOk: probes.length === fa.length && probes.every((p) => /^vorbis,44100,1/.test(p.ffprobe.replace(/\s+/g, ",").replace(/^,/, ""))),
    libraryIds: c.libraryIds, accepted: accepted.events, checked: c,
  };
}

async function packFor(version: string, store: LocalDiskStore, r: Awaited<ReturnType<typeof renderPart>>) {
  if (version === "26.2") {
    const b = buildPack({ namespace: NS, description: "TfSound: custom textures and sounds by Cyrus", mcVersion: version, textures, sounds: packSoundsOf(r.accepted), allowPreview: true });
    if (!b.ok) throw new Error(b.error);
    const pub = await publishPack(store, b.pack.zip, { maxBytes: 10 * 1024 * 1024 });
    if (!pub.ok) throw new Error(pub.error);
    return { path: "buildPack(allowPreview, test only)", sha1: pub.sha1, url: pub.url, format: b.pack.packFormat, bytes: b.pack.bytes, files: b.pack.files.length, sounds: b.pack.sounds, prompt: "TfSound uses custom item textures and sounds. Accept the pack to see and hear them.", required: false };
  }
  const projects = new Map([[`mbsound${version}`, { id: "cp" + "s".repeat(20), namespace: NS, userId: "flight" }]]);
  const revs: { id: string; modBuildId: string | null }[] = [];
  const deps: AssetSyncDeps = {
    selectStore: () => ({ ok: true, store, maxBytes: 10 * 1024 * 1024 }),
    projectForRootBuild: async (x) => projects.get(x) ?? null,
    createProject: async () => { throw new Error("unexpected"); },
    findRevisionForBuild: async (_p, m) => revs.find((x) => x.modBuildId === m) ?? null,
    headRevisionId: async () => revs.at(-1)?.id ?? null,
    addRevision: async (_p, i) => { const x = { id: `rev${revs.length + 1}`, modBuildId: i.modBuildId ?? null }; revs.push(x); return x; },
    recordAsset: async () => null,
    selectRenderHost: () => ({ ok: true, host: sshRenderHost() }),
    soundLibraryCleared: () => true, // test only: production keeps the library off until the owner confirms the licence
  };
  const a = await syncBuildAssets(
    { id: `mbsound${version}`, userId: "flight", rootBuildId: `mbsound${version}`, mcVersion: version, pluginName: "TfSound", jarName: null, jarSha256: null },
    { namespace: NS, promptVersion: "mb-assets-2026-10-10.2", qualityVersion: "tq-1", kept: false, downgraded: [], warnings: [], textures: textures.map((s) => ({ name: s.name, path: `assets/textures/${s.name}.json`, sha256: "", spec: s, quality: null })), sounds: [{ key: "banshee", path: "assets/sounds/banshee.json", sha256: "", spec: r.spec, quality: null }] },
    deps,
  );
  if (!a || a.status !== "ready" || !a.loader || !a.pack || a.soundRender !== "rendered") throw new Error(`sync did not produce a hosted pack with sounds: ${JSON.stringify(a)}`);
  return { path: "syncBuildAssets (production path, real render host)", sha1: a.pack.sha1, url: a.loader.url, format: a.pack.format, bytes: a.pack.bytes, prompt: a.loader.prompt, required: a.loader.required, sounds: a.sounds, textures: a.textures.map((t) => `${t.name}:${t.quality}`), dropped: a.dropped };
}

async function flight(version: string, pack: Awaited<ReturnType<typeof packFor>>): Promise<{ spec: TestFlightSpec; loaderId: string }> {
  const r = applyPackChange(null, { op: "upsert", namespace: NS, role: "main", sha1: pack.sha1, prompt: pack.prompt, required: pack.required }, { urlFor: () => pack.url });
  if (!r.ok) throw new Error(r.error);
  return {
    loaderId: r.id,
    spec: {
      version,
      plugins: [{ remotePath: `${FX}/NxeonPackLoader-0.1.0.jar` }, { remotePath: `${FX}/TfItemModel-1.0.0.jar` }, { remotePath: `${FX}/TfSound-1.0.0.jar` }],
      files: [{ path: LOADER_CONFIG_PATH, content: serializeLoaderConfig(r.config) }],
      rcon: [
        { id: "pack-listed", command: "nxpacks list", expect: ["1 pack(s)", r.id, `sha1=${pack.sha1}`, "required=false"], expectNot: ["REJECTED"] },
        { id: "loader-status", command: "nxpacks status", expect: ["packs=1", "config=ok"] },
        { id: "item-model-ruby", command: `tfitem ${NS} ruby_sword`, expect: [`itemModel=${NS}:ruby_sword`] },
        { id: "sound-hurt", command: `tfsound ${NS}:banshee.hurt HOSTILE`, expect: [`played=${NS}:banshee.hurt`, "category=HOSTILE", "silent=true", "mob=ZOMBIE"] },
        { id: "sound-death", command: `tfsound ${NS}:banshee.death HOSTILE`, expect: [`played=${NS}:banshee.death`, "silent=true"] },
        { id: "plugins-listed", command: "plugins", expect: ["NxeonPackLoader", "TfItemModel", "TfSound"] },
      ],
    },
  };
}

const brief = (name: string, r: RunResult, extra: unknown) => ({
  name, version: r.report.version, status: r.report.status, overall: r.summary.overall, success: r.summary.success,
  bootMs: r.report.bootMs, peakRssKb: r.report.peakRssKb, checks: r.report.checks.map((c) => ({ id: c.id, status: c.status, evidence: c.evidence })),
  line: describe(r.summary), notes: r.report.notes, engine: r.report.engine, ...((extra as object) ?? {}),
});

async function main() {
  const which = process.argv[2] ?? "all";
  const outIdx = process.argv.indexOf("--out");
  const out: Record<string, unknown> = { client: "none (server-side only): playback, subtitles and the pack prompt are NOT verified" };
  const r = await renderPart();
  const { accepted: _a, checked: _c, ...renderReport } = r;
  out.render = renderReport;
  console.log(`render: ${r.files.length} files, deterministic=${r.deterministic}, ffprobe ok=${r.probeOk}, ${r.renderMs} ms`);
  if (which !== "render") {
    const dir = mkdtempSync(path.join(tmpdir(), "cyrus-snd-flight-"));
    const store = new LocalDiskStore(dir, BASE);
    const flights: unknown[] = [];
    try {
      for (const v of ["1.21.11", "26.2"]) { // strictly one at a time (node-2 rule)
        const pack = await packFor(v, store, r);
        const s = await flight(v, pack);
        const res = await runTestFlight(s.spec);
        flights.push(brief(v, res, { pack, loaderId: s.loaderId, namespace: NS }));
        console.log(`${v}: ${describe(res.summary)}`);
      }
    } finally { rmSync(dir, { recursive: true, force: true }); }
    out.flights = flights;
  }
  if (outIdx > 0) writeFileSync(process.argv[outIdx + 1], JSON.stringify(out, null, 1));
  else console.log(JSON.stringify(out, null, 1).slice(0, 4000));
}
main().catch((e) => { console.error(e); process.exit(1); });

