  it("sound slice: sync with sounds (fake render host) records one revision + one sound asset per set; concurrent syncs never duplicate", async () => {
    const { createProject } = await import("../lib/cyrus/engine-core/store.ts");
    const { syncBuildAssets } = await import("../lib/cyrus/assets/sync.ts");
    const { defaultAssetSyncDeps } = await import("../lib/cyrus/assets/sync-deps.ts");
    const { checkSoundSpec } = await import("../lib/cyrus/sound/spec.ts");
    const { renderVariant } = await import("../lib/cyrus/sound/render.ts");
    const { measure, soundQuality } = await import("../lib/cyrus/sound/measure.ts");
    const { toS16, pcmSha256 } = await import("../lib/cyrus/sound/dsp.ts");
    const { createHash } = await import("node:crypto");
    const example = JSON.parse(fs.readFileSync(path.join(__dirname, "../services/modbuilder/sound-example.json"), "utf8"));
    let renders = 0;
    // in-process stand-in for the node-2 render host ("Ogg" = OggS + PCM): the DB path is what this test is about
    const host = { id: "fake", render: async (job: { sets: { name: string; spec: unknown }[] }) => {
      renders++;
      return { ok: true as const, tool: { runner: "fake", render: "sr-1", quality: "sq-1", ffmpeg: "none" }, errors: [], sets: job.sets.map((s) => {
        const c = checkSoundSpec(s.spec, { catalog: null, library: false }); if (!c.ok) throw new Error(c.error);
        return { name: s.name, events: c.spec.events.map((e) => ({ event: e.event, files: e.variants.map((v, i) => {
          const r = renderVariant(v, e.role, () => new Float64Array(0)); const ogg = Buffer.concat([Buffer.from("OggS"), toS16(r.pcm)]); const m = measure(r.pcm); const enc = { codec: "vorbis", channels: 1, sampleRate: 44100 };
          return { index: i + 1, weight: v.weight, ogg: ogg.toString("base64"), oggSha256: createHash("sha256").update(ogg).digest("hex"), pcmSha256: pcmSha256(r.pcm), bytes: ogg.length, encoded: { ...enc, durationS: m.durationS }, measure: m, quality: soundQuality(m, enc, e.role), render: { gainDb: r.gainDb, peakLimited: r.peakLimited, truncated: r.truncated, ceilingDb: -1.5, passes: 1 } };
        }) })) };
      }) };
    } };
    const root = `mb${uniq}snd`;
    const p = await createProject({ userId: uid("saka"), game: "minecraft", rootBuildId: root });
    const ar = { namespace: p.namespace, promptVersion: "mb-assets-2026-10-10.2", qualityVersion: "tq-1", kept: false, downgraded: [], warnings: [], textures: [], sounds: [{ key: "banshee", path: "assets/sounds/banshee.json", sha256: "", spec: example, quality: null }] };
    const build = { id: root, userId: uid("saka"), rootBuildId: root, mcVersion: "1.21.11", pluginName: "Banshee", jarName: "Banshee-1.0.0.jar", jarSha256: "d".repeat(64) };
    const deps = { ...defaultAssetSyncDeps(env), selectRenderHost: () => ({ ok: true as const, host: host as never }) };
    const race = await Promise.all([syncBuildAssets(build, ar, deps), syncBuildAssets(build, ar, deps), syncBuildAssets(build, ar, deps)]);
    assert.equal(race[0]!.status, "ready", JSON.stringify(race[0]!.notices));
    assert.equal(race[0]!.soundRender, "rendered");
    assert.deepEqual(race[0]!.sounds!.map((x) => x.key), [`${p.namespace}:banshee.ambient`, `${p.namespace}:banshee.hurt`, `${p.namespace}:banshee.death`]);
    assert.equal(new Set(race.map((x) => x!.revisionId)).size, 1);
    assert.equal(new Set(race.map((x) => x!.pack!.sha1)).size, 1, "deterministic render -> one pack");
    const again = (await syncBuildAssets(build, ar, deps))!;
    assert.equal(again.revisionId, race[0]!.revisionId);
    assert.equal(renders, 4);
    assert.equal(await db.cyrusRevision.count({ where: { projectId: p.id } }), 1);
    const rows = await db.cyrusProjectAsset.findMany({ where: { projectId: p.id } });
    assert.equal(rows.length, 1);
    assert.equal(rows[0].kind, "sound");
    assert.equal(rows[0].mime, "application/vnd.nxeon.sound-spec+json");
    const prov = rows[0].provenance as { events: { files: unknown[] }[]; ledger: unknown[]; render: string };
    assert.equal(prov.render, "rendered"); assert.deepEqual(prov.ledger, []); assert.equal(prov.events.length, 3);
    const rev = await db.cyrusRevision.findFirst({ where: { projectId: p.id } });
    assert.ok((rev!.manifest as { path: string }[]).some((m) => m.path === "assets/sounds/banshee.json"));
    // no render host: designed sounds are still recorded, nothing is shipped
    const root2 = `mb${uniq}snd2`;
    const p2 = await createProject({ userId: uid("saka"), game: "minecraft", rootBuildId: root2 });
    const off = (await syncBuildAssets({ ...build, id: root2, rootBuildId: root2 }, { ...ar, namespace: p2.namespace }, defaultAssetSyncDeps(env)))!;
    assert.equal(off.soundRender, "off"); assert.equal(off.pack, null);
    assert.equal(await db.cyrusProjectAsset.count({ where: { projectId: p2.id, kind: "sound" } }), 1);
  });
